function evGot(id){ return !!(state.evidence && state.evidence[id]); }

function stGot(id){ return !!(state.statements && state.statements[id]); }

function missionEvidenceIds(m){ return EVIDENCE_ORDER.filter(function(k){ return EVIDENCE[k].m === m; }); }

function missionEvidenceGot(m){ var n=0; missionEvidenceIds(m).forEach(function(k){ if(evGot(k)) n++; }); return n; }

function currentMission(){

  if(!state.closed || !state.camp) return null;

  for(var i=0;i<MISSION_ORDER.length;i++){ if(!state.camp[MISSION_ORDER[i]].done) return MISSION_ORDER[i]; }

  return null;

}

function campaignDone(){ return !!state.closed && !currentMission(); }

