function campObjective(){

  var m = currentMission(); if(!m) return null;

  var list = MISSION_OBJS[m];

  for(var i=0;i<list.length;i++){ if(!list[i].done()){ var o = list[i]; return {m:m, id:o.id, text:o.text, map:o.map, where:o.where, spot:o.spot}; } }

  return null;

}

function missionMissing(m){

  var out = [];

  MISSION_OBJS[m].forEach(function(o){ if(!o.done() && o.id !== "brief") out.push(o.text); });

  return out;

}



