function doMissionConclusion(m){

  if(m === "m2"){

    showLines([["SGT. BROOKS", "You found Mr. Pickles! The poor foam fellow was stuck behind cereal boxes. But the real snack crates are still missing. Which lead is supported by your evidence?"]],

      function(){case2ConclusionChoices();});

  } else if(m === "m3"){

    showLines([["SGT. BROOKS", "House searched, harbormaster heard, and Hale himself on the phone. So — where is Emmett Hale, and what is he?"]],

      function(){ showChoiceSet("YOUR CONCLUSION — CASE 003", "Choose the conclusion the findings support:", CONCLUSION3, "m3", closeM3); });

  } else if(m === "m4"){

    showLines([["SGT. BROOKS", "Warehouse searched, evidence returned, and Ferris talked. Before I sign anything: what do we do with Doyle Ferris?"]],

      function(){ showChoiceSet("THE FERRIS CALL — CASE 004", "Choose the call the evidence supports:", FERRIS_CALL, "m4", closeM4); });

  } else if(m === "m5"){

    showLines([["SGT. BROOKS", "Shed opened, cache bagged, ledger returned. Four cases on this table, Detective. Who runs the ring?"]],

      function(){ showChoiceSet("FINAL ARREST — CASE 005", "Choose the arrest the whole campaign's evidence supports:", FINAL_ARREST, "m5", closeM5); });

  }

}

function showChoiceSet(title, prompt, set, m, onCorrect){

  showChoices(title, prompt, set.map(function(c, idx){

    return { label:c.label, fn:function(){

      if(c.correct){ onCorrect(); return; }

      state.camp[m].attempts++;

      awardScore("acc:" + m + ":" + idx, "Unsupported accusation", RULES.score.unsupported, "\u201C" + c.label + "\u201D \u2014 submitted to Sgt. Brooks; the evidence doesn't support it.");

      save(); sndBad();

      showFeedback("bad", "Brooks shakes her head — not supported.", " " + c.wrong + " Go back over your evidence and statements, then choose again.",

        "Reconsider — Choose Again", function(){ showChoiceSet(title, prompt, set, m, onCorrect); });

    }};

  }));

}

