function showEnding(){

  var endOverlay = document.getElementById("endOverlay");

  if(!endOverlay) return;

  if(!state.camp.ended){ state.camp.ended = true; save(); }

  var evN = EVIDENCE_ORDER.filter(function(k){ return evGot(k); }).length + (state.findings.drive ? 1 : 0);

  var stN = STATEMENTS_ORDER.filter(function(k){ return stGot(k); }).length + (state.findings.witness ? 1 : 0);

  var wrong = (state.attempts || 0) + MISSION_ORDER.reduce(function(a, m){ return a + (state.camp[m].attempts || 0); }, 0);

  document.getElementById("endSub").innerHTML = "Final rank: <b>DETECTIVE</b> · Cases closed: <b>5 / 5</b> · Evidence items on file: <b>" + evN + " / 11</b> · Witness statements recorded: <b>" + stN + " / 9</b> · Unsupported calls corrected along the way: <b>" + wrong + "</b> · Final Performance score: <b>" + state.perf.total + "</b> (full history under PERFORMANCE, top of the screen). Harbor City is open — keep exploring, or start the whole campaign again.";

  var host = document.getElementById("endSummary");

  host.innerHTML = "";

  CASE_SUMMARY.forEach(function(c){

    var d = document.createElement("div"); d.className = "finding";

    var h = document.createElement("h4"); h.textContent = "✓ " + c.n; d.appendChild(h);

    var p = document.createElement("p"); p.textContent = c.t; d.appendChild(p);

    host.appendChild(d);

  });

  endOverlay.classList.add("show");

}

function closeCase(){

  awardScore("concl:m1", "Supported conclusion", RULES.score.conclusion, "Case 001 \u2014 The Missing Drive: conclusion supported by all four findings.");

  state.closed = true; state.rank = "Patrol Officer"; save(); refreshPanels();

  tone(523, 0.12, 0, "sine"); tone(659, 0.12, 0.11, "sine"); tone(784, 0.22, 0.22, "sine");

  showLines([

    ["SGT. BROOKS", "Case 001: CLOSED. The drive goes back to Evidence \u2014 signed for properly this time \u2014 and the transfer form gets a second signature from today on."],

    ["SGT. BROOKS", "You followed the evidence instead of the easy accusation, Jay. That's the job. Promotion board agreed this morning: Cadet Jay is now PATROL OFFICER Jay."],

    ["JAY", "Thank you, Sergeant. Case 001 \u2014 closed."]

  ], function(){

    endShift("m1", function(){

      document.getElementById("winBanner").classList.add("show");

      toast("Promotion earned: Jay is now a Patrol Officer");

    });

  });

}



/* ============================== NEW STATION INTERACTIONS ============================== */

function doEvShelf(){

  var cm = currentMission();

  if(cm && state.camp[cm].brief && !state.camp[cm].returned){

    var ids = missionEvidenceIds(cm), total = ids.length, have = missionEvidenceGot(cm);

    if(have >= total){

      state.camp[cm].returned = true; save(); refreshPanels(); sndGood();

      var names = ids.map(function(k){ return EVIDENCE[k].name; }).join("; ");

      var extra = cm === "m3" ? " The Shed B key is logged, photographed, and checked back out to you \u2014 Brooks signed the authorization herself." : (cm === "m4" ? " With the warehouse evidence receipted, Brooks authorizes the Ferris interview in Holding." : "");

      showLines([

        ["EVIDENCE ROOM", "You log and shelve all " + total + " Case " + MISSIONS[cm].num + " items: " + names + " \u2014 each tagged, photographed and signed in." + extra],

        ["JAY", "Evidence returned and receipted. Chain of custody clean \u2014 that's what makes the next step stick."]

      ], function(){ toast("All Case " + MISSIONS[cm].num + " evidence returned to Precinct 9"); });

      return;

    }

    showLines([["EVIDENCE SHELVES", "Case " + MISSIONS[cm].num + " evidence return is open, but you have " + have + " of " + total + " items. Collect the full set first, then return them together here."]], null);

    return;

  }

  var got = ORDER.filter(function(k){ return state.findings[k]; });

  var lines = [["EVIDENCE SHELVES", "Locked evidence shelves. Every item is tagged, sealed and signed for \u2014 twice, since this morning's policy change."]];

  if(state.closed){

    lines.push(["EVIDENCE SHELVES", "Shelf A, slot 1: USB drive EV-001 \u2014 recovered from Intake Tray B, seal intact, transfer form TR-88 completed and countersigned. Case 001 property."]);

  } else if(state.findings.drive){

    lines.push(["JAY", "The EV-001 slot is empty, but the drive itself is sealed in my evidence pouch. Once Brooks closes the case, it comes back here \u2014 signed for properly."]);

  } else if(got.length){

    lines.push(["JAY", "Findings logged so far: " + got.map(function(k){ return FINDINGS[k].title; }).join("; ") + ". The EV-001 slot itself is still empty."]);

  } else {

    lines.push(["JAY", "The EV-001 slot is empty and no findings are logged yet. The tag clipped to this rail is the place to start."]);

  }

  showLines(lines, null);

}

/* ============================== LOCKER CLOSE-UP ==============================

   Interacting with Jay's Locker opens a front-view close-up of Locker 7.

   This REPLACES the old one-tap uniform toggle and folds it in: equipping

   or returning the uniform here drives the same state.uniform flag the

   sprite renderer and the intro already use, so there is one equip

   mechanic, not two. Every item lives in exactly one place (locker /

   inventory / equipped slot) in state.gear.where, which is what makes

   duplicates impossible. Rules: holster needs the belt equipped, pistol

   needs the holster equipped; removing a prerequisite cascades the

   dependent gear back into the inventory. Car keys carried in the

   inventory unlock Unit 9 (see enterCar); the radio carried or equipped

   enables dispatch interactions (see doTsRadio). Weapon handling stays

   abstract — a slot and an ammunition count, no loading simulation, and

   equipping the pistol introduces no combat. Art: Jay's final locker pack

   (assets/locker-pack/, driven by its manifest.json) — background and the

   fading foreground frame render at the 480x600 logical scene, item PNGs

   sit at the manifest coordinates (LK_DEFS pos percentages below match

   them), and the Equipped panel uses the pack's six slot icons. */

var LK_DEFS = {

  uniform:   { name:"Police Uniform & Cap", short:"Uniform & Cap", slot:"Uniform",

    desc:"Pressed navy dress uniform with your cap \u2014 the full Precinct 9 look. Wearing it is the locker room's original equip: Jay's sprite switches between dress uniform and cadet working blues. The photo of the Maple Court house stays taped inside the door either way.",

    pos:{l:4.2, t:6, w:40, h:52} },

  badge:     { name:"Badge", short:"Badge", slot:"Badge",

    desc:"Polished Precinct 9 shield, number 7-114. Brooks checks that it catches the light before every briefing.",

    pos:{l:52.5, t:7.3, w:17.5, h:14} },

  notebook:  { name:"Notebook", short:"Notebook",

    desc:"Your pocket notebook \u2014 findings, statements and plate numbers. The paper half of the Notebook panel; cases are won with what gets written in here.",

    pos:{l:74.2, t:7.3, w:20, h:14} },

  ammo:      { name:"Spare Ammunition", short:"Ammo \u00d712",

    desc:"One labeled box of spare ammunition \u2014 12 rounds, tracked as a simple count on the item. Harbor City keeps weapon handling abstract: equipment slots and counts only, no loading or assembly simulation.",

    pos:{l:52.5, t:25, w:20, h:12.7} },

  radio:     { name:"Police Radio", short:"Radio", slot:"Radio",

    desc:"Your shoulder radio, tuned to the Precinct 9 dispatch channel. Carry it (inventory or equipped) to run plate checks and talk to Dispatch out in the city \u2014 like the HBR-2084 check at the traffic stop.",

    pos:{l:75.8, t:23, w:17.5, h:20} },

  flashlight:{ name:"Flashlight", short:"Flashlight",

    desc:"Heavy-duty torch, issued with a fresh set of batteries. Harbor City's street lights are kind; its sheds, yards and evidence corners are not.",

    pos:{l:52.5, t:40, w:20, h:10} },

  carkeys:   { name:"Patrol-Car Keys", short:"Car Keys",

    desc:"Unit 9's keys on a Precinct 9 ring. The cruiser stays locked without them \u2014 take the keys into your inventory, then at the driver's door: unlock, open the door, get in, and start the engine from the vehicle panel. They work straight from your pocket; there is no key slot to equip.",

    pos:{l:76.7, t:45.3, w:15.8, h:11.7} },

  belt:      { name:"Duty Belt", short:"Duty Belt", slot:"Duty Belt",

    desc:"Leather duty belt with keepers and pouches. Everything else hangs off this \u2014 the belt must be equipped before the holster can attach to it.",

    pos:{l:4.2, t:56, w:41.7, h:12.7} },

  holster:   { name:"Holster", short:"Holster", slot:"Holster", needs:"belt",

    desc:"Belt holster with a retention strap, worn on the strong side. It clips onto the duty belt, so the belt has to be equipped first.",

    pos:{l:50.8, t:55, w:22.9, h:16} },

  pistol:    { name:"Service Pistol", short:"Pistol", slot:"Service Pistol", needs:"holster",

    desc:"Issue service pistol, stored in the locker's lock tray. Equip the duty belt, holster, then pistol. It stays holstered during ordinary exploration. Firing is available only in the marked Case 003 encounter; talking and backup remain options. Every shot matters.",

    pos:{l:4.2, t:72.7, w:31.3, h:14.7} },

  fieldmanual:{ name:"Officer Field Manual", short:"Field Manual",

    desc:"The Precinct 9 Officer Field Manual \u2014 seven short chapters covering exactly the rules this game implements: shift preparation, dispatch, witnesses, evidence, supported conclusions, the traffic-stop procedure, and returning equipment and completing reports. Read it here in the locker, or take it with you and read it anywhere from the locker panel's Read button while it's selected. Reading never costs mission progress.",

    pos:{l:52.5, t:73, w:20, h:14} }

};

/* Jay's locker pack art (data:application/json;base64,): item key ->

   PNG file. Item PNGs are already at the 480x600 scene scale; LK_DEFS pos

   percentages place them. Slot icons are slot_<item id>.webp for the six

   equippable items (uniform, badge, belt, holster, pistol, radio). */

var LK_ART_BASE = "assets/locker-pack/";

var LK_ART = {

  uniform:"uniform_cap.webp", badge:"badge.webp", notebook:"notebook.webp",

  ammo:"spare_ammo.webp", radio:"police_radio.webp", flashlight:"flashlight.webp",

  carkeys:"patrol_keys.webp", belt:"duty_belt.webp", holster:"holster.webp",

  pistol:"service_pistol.webp", fieldmanual:"officer_field_manual.webp"

};

var lockerOverlay = document.getElementById("lockerOverlay");

var lkSel = null, lkMsg = "", lkMsgBad = false, lkReturnPos = null;

function lkWhere(id){

  /* the uniform's equipped state IS state.uniform (sprite + intro read it),

     so derive it there rather than trusting the mirrored gear entry */

  if(id === "uniform") return state.uniform ? "equipped" : (state.gear.where.uniform === "equipped" ? "locker" : state.gear.where.uniform);

  return state.gear.where[id];

}

function lkHasRadio(){ return lkWhere("radio") === "inv" || lkWhere("radio") === "equipped"; }

function lkHasKeys(){ return lkWhere("carkeys") === "inv"; }

function doLocker(){ openLocker(); }

function openLocker(){

  if(lockerOverlay.classList.contains("show")) return;

  lkReturnPos = { x: player.x, y: player.y };

  lkSel = null; lkMsg = ""; lkMsgBad = false;

  renderLocker();

  lockerOverlay.classList.add("show");

  var sc = document.getElementById("lockerScene");

  sc.classList.remove("open");

  setTimeout(function(){ sc.classList.add("open"); }, 50);

  sndDoor();

  save();

}

function closeLocker(){

  if(!lockerOverlay.classList.contains("show")) return;

  document.getElementById("lockerScene").classList.remove("open");

  sndDoor();

  setTimeout(function(){ lockerOverlay.classList.remove("show"); }, 170);

  if(lkReturnPos){ player.x = lkReturnPos.x; player.y = lkReturnPos.y; }

  save();

  toast("Locker closed \u2014 back in the Precinct 9 locker room");

}

function lkPosStyle(p){ return "left:" + p.l + "%;top:" + p.t + "%;width:" + p.w + "%;height:" + p.h + "%;"; }

function lkStatusText(id){

  var w = lkWhere(id), d = LK_DEFS[id];

  if(w === "equipped") return "EQUIPPED \u2014 " + (d.slot || "").toUpperCase() + " SLOT";

  if(w === "inv") return "IN YOUR INVENTORY";

  return "IN THE LOCKER";

}

function renderLocker(){

  var scene = document.getElementById("lockerScene");

  scene.querySelectorAll(".lk-ghost,.lk-item").forEach(function(el){ el.remove(); });

  var door = document.getElementById("lkDoor");

  GEAR_ITEMS.forEach(function(id){

    var d = LK_DEFS[id];

    var ghost = document.createElement("div");

    ghost.className = "lk-ghost"; ghost.style.cssText = lkPosStyle(d.pos);

    scene.insertBefore(ghost, door);

    if(lkWhere(id) !== "locker") return;

    var b = document.createElement("button");

    b.type = "button"; b.className = "lk-item" + (lkSel === id ? " sel" : "");

    b.style.cssText = lkPosStyle(d.pos);

    b.setAttribute("aria-label", d.name + " \u2014 in locker");

    b.innerHTML = '<img src="' + LK_ART_BASE + LK_ART[id] + '" alt="" draggable="false">';

    b.addEventListener("click", function(){ lkSelect(id); });

    scene.insertBefore(b, door);

  });

  /* equipment slots */

  var slotsEl = document.getElementById("lkSlots");

  slotsEl.innerHTML = "";

  GEAR_ITEMS.filter(function(id){ return !!LK_DEFS[id].slot; }).forEach(function(id){

    var row = document.createElement("button");

    row.type = "button"; row.className = "lk-slot" + (lkSel === id ? " sel" : "");

    var eq = lkWhere(id) === "equipped";

    row.innerHTML = '<span class="lk-slot-l"><img class="lk-slot-ic' + (eq ? "" : " off") + '" src="' + LK_ART_BASE + "slot_" + id + '.webp" alt="">' +

      '<span class="lk-slotname">' + LK_DEFS[id].slot.toUpperCase() + " SLOT</span></span>" +

      (eq ? "<span><b>" + LK_DEFS[id].name + "</b></span>" : '<span class="lk-empty">\u2014 empty \u2014</span>');

    row.addEventListener("click", function(){ lkSelect(id); });

    slotsEl.appendChild(row);

  });

  /* inventory */

  var invEl = document.getElementById("lkInv");

  invEl.innerHTML = "";

  var carried = GEAR_ITEMS.filter(function(id){ return lkWhere(id) === "inv"; });

  if(!carried.length){

    invEl.innerHTML = '<p class="lk-none">Nothing carried yet \u2014 take what you need from the locker.</p>';

  } else {

    var wrap = document.createElement("div"); wrap.className = "lk-chiprow";

    carried.forEach(function(id){

      var chip = document.createElement("button");

      chip.type = "button"; chip.className = "lk-chip" + (lkSel === id ? " sel" : "");

      chip.textContent = LK_DEFS[id].name;

      chip.addEventListener("click", function(){ lkSelect(id); });

      wrap.appendChild(chip);

    });

    invEl.appendChild(wrap);

  }

  renderLkDetail();

}

function renderLkDetail(){

  var el = document.getElementById("lkDetail");

  var html = "";

  if(lkMsg) html += '<p class="lk-msg show' + (lkMsgBad ? " bad" : "") + '">' + lkMsg + "</p>";

  if(!lkSel || !LK_DEFS[lkSel]){

    html += "<h3>LOCKER 7 \u2014 PRECINCT 9</h3>" +

      '<span class="lk-status">TAP AN ITEM</span>' +

      "<p>Everything in this locker is yours for the shift. <b>Take</b> moves an item into your inventory, <b>Equip</b> puts it in its slot, <b>Return</b> puts it back. Order matters for the belt rig: <b>duty belt \u2192 holster \u2192 service pistol</b>. Unit 9 needs its <b>keys</b> carried; dispatch needs your <b>radio</b> carried.</p>";

    el.innerHTML = html; return;

  }

  var id = lkSel, d = LK_DEFS[id], w = lkWhere(id);

  html += "<h3>" + d.name + "</h3>";

  html += '<span class="lk-status' + (w === "equipped" ? " eq" : "") + '">' + lkStatusText(id) + "</span>";

  html += "<p>" + d.desc + "</p>";

  var acts = "";

  if(w === "locker"){

    acts += '<button type="button" class="dbtn gold" data-lkact="take">Take</button>';

    if(d.slot) acts += '<button type="button" class="dbtn" data-lkact="equip">Equip</button>';

  } else if(w === "inv"){

    if(d.slot) acts += '<button type="button" class="dbtn gold" data-lkact="equip">Equip</button>';

    acts += '<button type="button" class="dbtn ghost" data-lkact="return">Return to Locker</button>';

  } else {

    acts += '<button type="button" class="dbtn gold" data-lkact="unequip">Unequip</button>';

    acts += '<button type="button" class="dbtn ghost" data-lkact="return">Return to Locker</button>';

  }

  if(id === "fieldmanual") acts += '<button type="button" class="dbtn" data-lkact="read">Read Manual</button>';

  html += '<div class="lk-actions">' + acts + "</div>";

  if(d.needs && lkWhere(d.needs) !== "equipped"){

    html += '<p class="lk-need">Requires the <b>' + LK_DEFS[d.needs].name + "</b> equipped first.</p>";

  }

  if(id === "belt" && (lkWhere("holster") === "equipped" || lkWhere("pistol") === "equipped")){

    html += '<p class="lk-need">The holster rig is attached to this belt \u2014 unequipping or returning the belt moves the holster and pistol to your inventory.</p>';

  }

  if(id === "holster" && lkWhere("pistol") === "equipped"){

    html += '<p class="lk-need">The service pistol is holstered in this \u2014 removing the holster moves the pistol to your inventory.</p>';

  }

  el.innerHTML = html;

  el.querySelectorAll("[data-lkact]").forEach(function(btn){

    btn.addEventListener("click", function(){ lkAct(id, btn.getAttribute("data-lkact")); });

  });

}

function lkSelect(id){ lkSel = id; lkMsg = ""; lkMsgBad = false; sndClick(); renderLocker(); }

function lkCascade(id, verb){

  /* removing a prerequisite takes its dependents off with it */

  var notes = [];

  if(id === "belt"){

    if(lkWhere("holster") === "equipped"){ state.gear.where.holster = "inv"; notes.push("holster"); }

    if(lkWhere("pistol") === "equipped"){ state.gear.where.pistol = "inv"; notes.push("pistol"); }

  } else if(id === "holster"){

    if(lkWhere("pistol") === "equipped"){ state.gear.where.pistol = "inv"; notes.push("pistol"); }

  }

  if(notes.length) return " The " + notes.join(" and ") + " came" + (notes.length > 1 ? "" : "s") + " off with it, into your inventory.";

  return "";

}

function lkAct(id, act){

  var d = LK_DEFS[id], w = lkWhere(id);

  if(act === "read"){ openManual("officer", 0); return; }

  lkMsgBad = false;

  if(act === "take"){

    if(w !== "locker"){ lkMsg = d.name + " isn't in the locker right now."; lkMsgBad = true; }

    else { state.gear.where[id] = "inv"; lkMsg = "Taken: " + d.name + " is now in your inventory."; sndGood(); }

  } else if(act === "equip"){

    if(w === "equipped"){ lkMsg = d.name + " is already equipped \u2014 no duplicates."; lkMsgBad = true; }

    else if(d.needs && lkWhere(d.needs) !== "equipped"){

      lkMsg = "Can't equip the " + d.short.toLowerCase() + " yet \u2014 equip the " + LK_DEFS[d.needs].name + " first.";

      lkMsgBad = true; sndBad();

    } else {

      state.gear.where[id] = "equipped";

      if(id === "uniform") state.uniform = true;

      lkMsg = "Equipped: " + d.name + (id === "uniform" ? " \u2014 dress uniform on, cap straight." : " \u2014 in the " + d.slot + " slot.");

      sndGood();

    }

  } else if(act === "unequip"){

    if(w !== "equipped"){ lkMsg = d.name + " isn't equipped."; lkMsgBad = true; }

    else {

      var note1 = lkCascade(id, "unequip");

      state.gear.where[id] = "inv";

      if(id === "uniform") state.uniform = false;

      lkMsg = "Unequipped: " + d.name + " moved to your inventory." + note1 +

        (id === "uniform" ? " You're in cadet working blues now." : "");

      sndClick();

    }

  } else if(act === "return"){

    if(w === "locker"){ lkMsg = d.name + " is already in the locker."; lkMsgBad = true; }

    else {

      var note2 = lkCascade(id, "return");

      state.gear.where[id] = "locker";

      if(id === "uniform") state.uniform = false;

      lkMsg = "Returned: " + d.name + " is back in Locker 7." + note2 +

        (id === "uniform" ? " You hang the dress uniform up and switch to cadet working blues." : "");

      sndClick();

    }

  }

  save();

  renderLocker();

  /* Stage C: any gear change can complete the shift-readiness checklist

     (uniform + badge equipped, keys + radio carried). Equipping and

     unequipping themselves are never scored — only the first moment the

     whole checklist stands complete in a shift pays out, once. The note

     is repeated in the locker message because the floating score popup

     sits behind this open panel. */

  if(perfCheckReadiness()){

    lkMsg = (lkMsg ? lkMsg + " " : "") + "Performance " + fmtPts(RULES.score.readiness) + " \u2014 shift-readiness checklist complete: uniform, badge, keys, radio.";

    lkMsgBad = false;

    renderLocker();

  }

}

document.getElementById("btnLockerClose").addEventListener("click", closeLocker);

document.getElementById("btnLockerBack").addEventListener("click", closeLocker);

lockerOverlay.addEventListener("click", function(e){ if(e.target === lockerOverlay) closeLocker(); });



/* ============================== VEHICLE PANEL (STAGE A) ==============================

   Close-up interaction panel for Unit 9, modeled on the locker close-up.

   It EXTENDS the existing car entry/exit (enterCar / exitCar / updateCar)

   rather than duplicating it: the panel drives the same state. Four states

   stay separate throughout — car.locked, car.doorOpen, state.inCar,

   car.engine — and every unavailable action explains the missing

   requirement in the panel instead of failing silently. The shutdown

   order mirrors the access order: engine off -> step out -> close door ->

   lock. Driving itself stays in the top-down view. Placeholder art. */

var vehOverlay = document.getElementById("vehOverlay");

var vehMsg = "", vehMsgBad = false;

function vehSay(msg, bad){ vehMsg = msg; vehMsgBad = !!bad; if(bad) sndBad(); }

function openVehPanel(){

  if(vehOverlay.classList.contains("show")) return;

  if(car.map !== state.map && !isDriving()){ toast("Unit 9 isn't here \u2014 the blue marker on the city map (M) shows where it's parked"); sndBad(); return; }

  if(isDriving() && Math.abs(car.speed) > 6){ toast("Stop Unit 9 fully before opening the vehicle panel"); sndBad(); return; }

  vehMsg = ""; vehMsgBad = false;

  renderVeh();

  vehOverlay.classList.add("show");

  sndDoor();

}

function closeVehPanel(){

  if(!vehOverlay.classList.contains("show")) return;

  vehOverlay.classList.remove("show");

  sndClick();

  save();

}

function vehStateChips(){

  return [

    { name:"LOCK",   val: car.locked ? "LOCKED" : "UNLOCKED", cls: car.locked ? "warn" : "on" },

    { name:"DOOR",   val: car.doorOpen ? "OPEN" : "CLOSED",   cls: car.doorOpen ? "warn" : "" },

    { name:"SEAT",   val: isDriving() ? "INSIDE" : "OUTSIDE", cls: isDriving() ? "on" : "" },

    { name:"ENGINE", val: car.engine ? "RUNNING" : "OFF",     cls: car.engine ? "on" : "" }

  ];

}

function vehChecklist(){

  var inside = isDriving();

  return [

    { txt:"Carry the patrol-car keys (from your locker)", done: vehHasKeys() || !car.locked || inside },

    { txt:"Unlock Unit 9", done: !car.locked || inside },

    { txt:"Open the driver's door", done: car.doorOpen || inside },

    { txt:"Get into the driver's seat", done: inside },

    { txt:"Start the engine", done: car.engine },

    { txt:"Drive \u2014 top-down view, ENGINE button or G toggles the engine", done: car.engine && Math.abs(car.speed) > 6 }

  ];

}

function renderVeh(){

  var scene = document.getElementById("vehScene");

  scene.classList.toggle("door-open", !!car.doorOpen);

  scene.classList.toggle("engine-on", !!car.engine);

  var fob = document.getElementById("vehKeyfob");

  fob.textContent = vehHasKeys() ? "KEYS: IN YOUR POCKET" : "KEYS: NOT CARRIED";

  fob.classList.toggle("have", vehHasKeys());

  var stEl = document.getElementById("vehStates");

  stEl.innerHTML = "";

  vehStateChips().forEach(function(c){

    var d = document.createElement("div");

    d.className = "veh-state" + (c.cls ? " " + c.cls : "");

    d.innerHTML = '<span class="vs-name">' + c.name + '</span><span class="vs-val">' + c.val + "</span>";

    stEl.appendChild(d);

  });

  var ckEl = document.getElementById("vehCheck");

  ckEl.innerHTML = "";

  var list = vehChecklist(), nowMarked = false;

  list.forEach(function(it){

    var li = document.createElement("li");

    var now = !it.done && !nowMarked; if(now) nowMarked = true;

    li.className = (it.done ? "done" : "") + (now ? " now" : "");

    li.innerHTML = '<span class="box">' + (it.done ? "\u2713" : "") + '</span><span class="txt">' + it.txt + "</span>";

    ckEl.appendChild(li);

  });

  renderVehDetail();

}

function renderVehDetail(){

  var el = document.getElementById("vehDetail");

  var inside = isDriving();

  var html = "";

  if(vehMsg) html += '<p class="lk-msg show' + (vehMsgBad ? " bad" : "") + '">' + vehMsg + "</p>";

  html += "<h3>" + (inside ? "IN THE DRIVER'S SEAT" : "AT THE DRIVER'S DOOR") + "</h3>";

  html += '<span class="lk-status' + (car.engine ? " eq" : "") + '">' +

    (car.locked ? "LOCKED" : "UNLOCKED") + " \u00B7 DOOR " + (car.doorOpen ? "OPEN" : "CLOSED") + " \u00B7 ENGINE " + (car.engine ? "RUNNING" : "OFF") + "</span>";

  if(inside){

    html += "<p>" + (car.engine

      ? "Engine running. Close this panel and drive \u2014 <b>W</b> gas, <b>S</b> brake/reverse, <b>A/D</b> steer, <b>L</b> lights, <b>K</b> siren. To get out: stop fully, switch the engine off, then step out."

      : "You're in, door shut, engine <b>off</b> \u2014 Unit 9 won't move until it starts. Your keys work straight from your pocket; there is no separate ignition key to find.") + "</p>";

  } else {

    html += "<p>" + (car.locked

      ? "Unit 9 is locked." + (vehHasKeys() ? " The keys are in your pocket \u2014 unlock it." : " And the keys aren't in your pocket: they hang in <b>Locker 7</b> (Locker Room, top-right of Precinct 9). Take the Patrol-Car Keys there first.")

      : car.doorOpen

        ? "Unlocked, driver's door open. Get in when you're ready \u2014 or close the door and lock up if you're leaving her here."

        : "Unlocked, door shut." + (car.engine ? " The engine is still running." : "") + " Open the driver's door to get in.") + "</p>";

  }

  var acts = "";

  if(!inside){

    if(car.locked) acts += '<button type="button" class="dbtn gold" data-vehact="unlock">Unlock Unit 9</button>';

    if(!car.locked && !car.doorOpen) acts += '<button type="button" class="dbtn gold" data-vehact="opendoor">Open Driver\'s Door</button>';

    if(!car.locked && car.doorOpen){

      acts += '<button type="button" class="dbtn gold" data-vehact="enter">Get In \u2014 Driver\'s Seat</button>';

      acts += '<button type="button" class="dbtn" data-vehact="closedoor">Close Door</button>';

    }

    if(!car.locked) acts += '<button type="button" class="dbtn ghost" data-vehact="lock">Lock Unit 9</button>';

    if(car.locked) acts += '<button type="button" class="dbtn" data-vehact="tryenter">Try the Door Anyway</button>';

  } else {

    if(!car.engine) acts += '<button type="button" class="dbtn gold" data-vehact="start">Start Engine</button>';

    else acts += '<button type="button" class="dbtn" data-vehact="stopengine">Switch Engine Off</button>';

    acts += '<button type="button" class="dbtn" data-vehact="interior">Interior \u2014 Dashboard &amp; Glove Box</button>';

    acts += '<button type="button" class="dbtn ghost" data-vehact="exit">Step Out</button>';

  }

  html += '<div class="lk-actions">' + acts + "</div>";

  el.innerHTML = html;

  el.querySelectorAll("[data-vehact]").forEach(function(btn){

    btn.addEventListener("click", function(){ vehAct(btn.getAttribute("data-vehact")); });

  });

  var back = document.getElementById("btnVehBack");

  if(back) back.textContent = inside ? "Close Panel \u2014 Stay in Unit 9" : "Close Panel";

}

function vehAct(act){

  vehMsgBad = false;

  if(act === "unlock"){

    if(!car.locked){ vehSay("Unit 9 is already unlocked.", true); }

    else if(!vehHasKeys()){

      vehSay("Can't unlock \u2014 the patrol-car keys aren't in your pocket. They're in Locker 7, in the Precinct 9 locker room (top-right of the station): open the locker and take the Patrol-Car Keys.", true);

      toast("No keys \u2014 Unit 9's keys are in your locker");

    } else { car.locked = false; sndClick(); vehSay("Unlocked. The fob chirps and the locks pop \u2014 driver's door next."); }

  } else if(act === "lock"){

    if(car.locked){ vehSay("Unit 9 is already locked.", true); }

    else if(isDriving()){ vehSay("You can't lock Unit 9 from the driver's seat \u2014 step out first, then lock up.", true); }

    else if(car.doorOpen){ vehSay("Can't lock yet \u2014 the driver's door is still open. Close the door first, then lock.", true); }

    else { car.locked = true; sndClick(); vehSay("Locked. Unit 9 is secure \u2014 position, door and lock state are saved."); if(perfCheckShutdown()) vehSay("Locked. Unit 9 is secure \u2014 position, door and lock state are saved. Performance " + fmtPts(RULES.score.shutdown) + " \u2014 vehicle shutdown/security checklist complete."); }

  } else if(act === "opendoor"){

    if(car.locked){ vehSay("The door won't budge \u2014 Unit 9 is locked. Unlock it first" + (vehHasKeys() ? "." : " (you'll need the keys from your locker)."), true); }

    else if(car.doorOpen){ vehSay("The driver's door is already open.", true); }

    else { car.doorOpen = true; sndDoor(); vehSay("Driver's door open. Get in when you're ready."); }

  } else if(act === "closedoor"){

    if(!car.doorOpen){ vehSay("The driver's door is already shut.", true); }

    else { car.doorOpen = false; sndDoor(); vehSay("Door closed with a solid thunk."); }

  } else if(act === "tryenter"){

    vehSay("You pull the handle: locked, and it stays locked. " + (vehHasKeys()

      ? "The keys are in your pocket \u2014 use Unlock."

      : "No keys, no entry: Unit 9's keys hang in Locker 7 at Precinct 9."), true);

    toast("Locked \u2014 Unit 9 needs its keys");

  } else if(act === "enter"){

    if(car.locked){ vehSay("Can't get in \u2014 Unit 9 is locked. Unlock it first.", true); }

    else if(!car.doorOpen){ vehSay("Can't get in \u2014 the driver's door is shut. Open it first.", true); }

    else if(!vehHasKeys()){ vehSay("Can't get in \u2014 the keys aren't in your pocket, and Unit 9 stays locked without them.", true); }

    else {

      enterCar();

      if(isDriving()) vehSay("You're in the driver's seat and the door is pulled shut. " + (car.engine ? "Engine's running \u2014 close the panel and drive." : "Start the engine to drive \u2014 it won't move a wheel while it's off."));

      else vehSay("Something blocked entry \u2014 check the message up top and try again.", true);

    }

  } else if(act === "start"){

    startEngine();

    if(car.engine) vehSay("Engine running. Close the panel and drive \u2014 W for gas, and remember: stop fully and switch off before stepping out.");

  } else if(act === "stopengine"){

    stopEngine();

    if(!car.engine) vehSay("Engine off. You can step out now \u2014 then close the door and lock up from outside.");

  } else if(act === "exit"){

    if(exitCar()) vehSay("Out of Unit 9. The driver's door is open behind you \u2014 close it, then lock the car.");

    else if(car.engine) vehSay("Can't step out yet \u2014 the engine is still running. Switch it off first, then step out.", true);

    else if(Math.abs(car.speed) > 6) vehSay("Can't step out \u2014 Unit 9 is still moving. Brake to a full stop first.", true);

    else vehSay("No safe place to step out here \u2014 move the car a little and try again.", true);

  } else if(act === "interior"){

    closeVehPanel();

    openInterior();

    return;

  }

  save(); renderVeh(); lastPromptKey = "";

}

function startEngine(){

  if(!isDriving()){ vehSay("You have to be in the driver's seat to start Unit 9 \u2014 unlock, open the door and get in first.", true); toast("Get into Unit 9 first"); return false; }

  if(car.engine){ vehSay("The engine is already running.", true); return false; }

  if(!vehHasKeys()){

    vehSay("The ignition turns nothing \u2014 the patrol-car keys aren't in your pocket. They're in Locker 7 at Precinct 9: take them there, then start her up.", true);

    toast("No keys \u2014 the engine won't start without them");

    return false;

  }

  car.engine = true;

  tone(140, 0.16, 0, "square"); setTimeout(function(){ tone(220, 0.2, 0, "triangle"); }, 130);

  sndGood(); save(); updateDriveUI(); lastPromptKey = "";

  toast("Unit 9 \u2014 engine running");

  return true;

}

function stopEngine(){

  if(!isDriving()){ vehSay("Nobody's in the driver's seat \u2014 the engine can only be switched off from inside.", true); return false; }

  if(!car.engine){ vehSay("The engine is already off.", true); return false; }

  if(Math.abs(car.speed) > 6){ vehSay("Stop Unit 9 fully before switching the engine off.", true); toast("Stop fully before switching off"); return false; }

  car.engine = false; car.speed = 0;

  if(car.siren) car.siren = false;

  sndClick(); save(); updateDriveUI(); lastPromptKey = "";

  toast("Unit 9 \u2014 engine off");

  return true;

}

function toggleEngine(){

  if(!isDriving()) return;

  if(car.engine){ if(stopEngine()) vehSay(""); }

  else { if(startEngine()) vehSay(""); }

  if(vehOverlay.classList.contains("show")) renderVeh();

}

document.getElementById("btnVehClose").addEventListener("click", closeVehPanel);

document.getElementById("btnVehBack").addEventListener("click", closeVehPanel);

vehOverlay.addEventListener("click", function(e){ if(e.target === vehOverlay) closeVehPanel(); });



/* ==================== STAGE B — MANUALS ====================

   Two readable manuals, one shared reader. The Officer Field Manual

   lives in Locker 7 (a locker gear item, "fieldmanual"); the Patrol

   Vehicle Manual lives in Unit 9's glove compartment (a glove item,

   "vehmanual"). Every instruction below describes only what this game

   actually implements — the same rules the locker, vehicle panel,

   interior and mission code enforce — and nothing here is scored or

   gated: opening a manual never touches mission progress, and closing

   it returns the player to the panel they came from. */

var MANUALS = {

  officer:{ title:"Officer Field Manual", chapters:[

    { title:"Preparing for a shift", body:[

      "Start at <b>Locker 7</b> in the Locker Room, top-right of Precinct 9. Walk to the gold-ringed <b>Jay's Locker</b> marker and press <kbd>E</kbd> (or tap <b>INTERACT</b>) to open the locker close-up.",

      "Tap an item to inspect it, then <b>Take</b> it into your inventory or <b>Equip</b> it into its slot. The rig order is enforced: <b>duty belt</b> first, then the <b>holster</b> on the belt, then the <b>service pistol</b> in the holster. If a step is blocked, the locker tells you exactly what is missing \u2014 nothing is ever just refused in silence.",

      "Two items gate other systems: the <b>Patrol-Car Keys</b> must be in your inventory before Unit 9 will unlock or start, and the <b>Police Radio</b> must be carried or equipped for dispatch interactions, including the plate check at the traffic stop. Equipping the <b>uniform</b> switches Jay between dress uniform and cadet working blues. Everything in the locker is saved automatically.",

      "That gear-up is the <b>shift-readiness checklist</b>: uniform equipped, badge equipped, patrol-car keys carried, police radio carried or equipped. The first time in a shift the whole checklist stands complete, your <b>Performance</b> score \u2014 the number at the top of the screen; tap it for the full history \u2014 gains <b>+" + RULES.score.readiness + "</b>, once per shift. Taking gear off and putting it back on never pays twice: the score rewards being ready, not fiddling with the locker. Opening this manual is never scored either."]},

    { title:"Dispatch and responding to calls", body:[

      "Work arrives as dialogue: Dispatch and Sergeant Brooks assign each case, and the <b>Objectives</b> panel always shows the current step. A gold beacon in the world and the green star on the city map (<kbd>M</kbd>) point at the current objective.",

      "Every case starts with a <b>briefing from Sgt. Brooks</b> in her office at Precinct 9. The prompt bar at the bottom of the screen names whatever you are standing near; press <kbd>E</kbd> or tap <b>INTERACT</b> to use it.",

      "Some story moments play as <b>cutscenes</b>. Advance dialogue with <b>Next</b>, <kbd>Enter</kbd> or a tap; the <b>Skip Scene</b> button jumps ahead and still applies every required outcome exactly once. When a scene ends, control returns to you where the scene left you."]},

    { title:"Talking to witnesses", body:[

      "Walk up to a person and press <kbd>E</kbd> to talk. Choose your questions from the dialogue choices; a recorded statement is written into the <b>Notebook</b> panel word for word, and the objective ticks off. Recording a required witness statement earns <b>+" + RULES.score.statement + " Performance</b>, once per statement \u2014 re-reading or replaying a conversation pays nothing.",

      "Some people will only talk once the evidence supports it. Doyle Ferris, for example, refuses until the warehouse evidence is logged in the Evidence Room \u2014 and he says so plainly. When that happens, do the evidence step first and come back; nobody is a dead end.",

      "Townsfolk with no case role offer short optional chats. They never block a case, witnesses with names stay at their posts, and civilians are never solid \u2014 no conversation can trap you or Jay."]},

    { title:"Recording and collecting evidence", body:[

      "Case scenes have gold-ringed markers: examine entry points, search shelves, desks, trays and sheds. Collected evidence appears in the <b>Evidence Inventory</b> panel with its description; Case 001 findings (tag, records, witness, drive) fill the <b>Notebook</b> instead. Collecting a required evidence item earns <b>+" + RULES.score.evidence + " Performance</b> as it is logged, once per item.",

      "The <b>Records database</b> terminal in the Records Room searches people, vehicles and cases \u2014 try a name, a badge number, or a plate such as <b>HBR-4417</b>. Several cases have a database step as a set objective.",

      "Collected case evidence must be <b>returned to the Evidence Room</b> shelves at Precinct 9 to be logged. Later steps can depend on it: Ferris only talks after the warehouse haul is logged, and Brooks only hears a conclusion once a case's evidence is back."]},

    { title:"Making conclusions supported by evidence", body:[

      "When a case's objectives are done, report to <b>Sgt. Brooks</b> and pick a conclusion. She accepts only a conclusion the collected findings, statements and evidence actually support \u2014 that support is the whole test.",

      "A supported conclusion earns <b>+" + RULES.score.conclusion + " Performance</b>, once per case. An unsupported accusation costs <b>" + RULES.score.unsupported + " Performance</b>, once per distinct accusation \u2014 submitting the same one again costs nothing more \u2014 and it is <b>explained, never a dead end</b>: Brooks tells you what doesn't hold up, and you can gather what is missing and try again. There is no hidden rule to break \u2014 if the game wanted it, it is listed as an objective.",

      "Promotions follow case completions: <b>Patrol Officer</b> after Case 001, <b>Detective</b> after Case 004. The five cases run in order \u2014 001 The Missing Drive, 002 The Midnight Pickle Panic, 003 The Missing Resident, 004 Warehouse Trail, 005 Harbor Reckoning \u2014 and each feeds the next. Performance never changes any of that: promotions follow case completions only, and a low score blocks nothing."]},

    { title:"In-game traffic-stop procedure", body:[

      "The demonstration stop waits in <b>Midtown, Harbor Ave East</b>: a flagged grey sedan in the eastbound lane. Make it like a real pull-over \u2014 drive Unit 9 up behind the sedan, switch the <b>emergency lights</b> on (<kbd>L</kbd>; the siren, <kbd>K</kbd>, counts too) and stop, and the arrival cutscene begins. On foot, the gold-ringed marker on the south sidewalk starts it instead.",

      "After the arrival scene and the exchange with the driver, <b>Dana Cole</b>, you choose an approach, then control returns for the investigation: <b>question the driver</b>, <b>inspect the sedan's rear and brake light</b>, and <b>run plate HBR-2084</b> through <b>Inventory → Police Radio → Run plate HBR-2084</b>. The plate check needs your <b>police radio</b> carried or equipped.",

      "With all three checks done, decide at the driver's window \u2014 <b>citation</b>, <b>verbal warning</b>, or <b>tow</b> \u2014 and the matching outcome scene plays. The decision and completion are saved, and the stop is one-time: it never replays or pays out twice."]},

    { title:"Returning equipment and completing reports", body:[

      "Reports in Harbor City are completed in person: each case ends by <b>reporting your conclusion to Sgt. Brooks</b>, and the campaign's final report opens the campaign summary. There is no separate paperwork screen and no form to lose.",

      "Gear goes home through the same panels it came from: open <b>Locker 7</b> and <b>Return</b> any item; taken items vanish from the locker and returned items reappear in their exact spots. Taking the belt or holster off moves whatever hangs on it into your inventory, so nothing is ever stranded.",

      "Case evidence is returned to the <b>Evidence Room</b>, and Unit 9 is secured at the end of a shift the way the Vehicle Manual describes: engine off, step out, door closed, locked. Inventory, equipment, evidence and vehicle state all save automatically in this browser.",

      "Closing a case ends the shift, and a <b>shift summary</b> appears before the next one begins: every Performance point the shift earned or lost, the shift total, your campaign total, and a line of feedback on each part of the work. Your full score history is always one tap away \u2014 the <b>Performance</b> number at the top of the screen."]}

  ]},

  vehicle:{ title:"Patrol Vehicle Manual \u2014 Unit 9", chapters:[

    { title:"Unlocking, entering, and starting", body:[

      "Unit 9 starts locked in the Precinct 9 garage, bay 1 \u2014 the station's south-east room, through the Locker Room's south door or in through the vehicle opening from the parking lot. First take the <b>Patrol-Car Keys</b> from Locker 7 (Locker Room, Precinct 9) into your inventory \u2014 without them, every step below explains that the keys are what is missing.",

      "Walk to the <b>driver's door</b> and press <kbd>E</kbd>: the vehicle close-up panel opens. Work it in order \u2014 <b>Unlock</b>, <b>Open the driver's door</b>, <b>Get in</b> (the door pulls shut behind you), then <b>Start Engine</b>. Lock, door, seat and engine are four separate states, all shown as readouts in the panel, and all saved.",

      "The engine can also be toggled with <kbd>G</kbd> once you are seated. <b>Unit 9 will not drive with the engine off</b> \u2014 the pedals simply answer with a reminder to start it."]},

    { title:"Driving and parking controls", body:[

      "Driving stays in the top-down view. Desktop: <kbd>W</kbd>/<kbd>&uarr;</kbd> accelerate, <kbd>S</kbd>/<kbd>&darr;</kbd> brake then reverse, <kbd>A</kbd><kbd>D</kbd> or the arrow keys steer (only while moving), <kbd>Space</kbd> is the brake. On a phone, the driving panel replaces the walking pad: STEER buttons left, BRAKE/REV and GAS right, ENGINE / LIGHTS / SIREN / EXIT / MAP in the middle.",

      "Top speed is limited, and buildings, parked cars, trees and fences are solid \u2014 a bump stops Unit 9 with a message and there is no damage, ever. But a bump at speed goes on your Performance record as an <b>avoidable collision</b> (<b>" + RULES.score.collision + "</b>), with a short grace period after each one so a single bump never costs twice; creeping into something while parking is not scored. Drive out through the street gates to move between districts; the car comes with you.",

      "Park anywhere the car fits. Where Unit 9 is parked \u2014 and its lock, door and engine states \u2014 are saved. If you leave it somewhere awkward, <b>Return Patrol Car</b> in the top bar (it asks first) recovers it to the precinct lot. With the car fully stopped, <kbd>E</kbd> or <kbd>F</kbd> opens the vehicle panel."]},

    { title:"Radio, emergency lights, and siren", body:[

      "While driving you never need a menu for these: <kbd>L</kbd> toggles the <b>emergency lights</b>, <kbd>K</kbd> toggles the <b>siren</b>, and the phone driving panel has LIGHTS and SIREN buttons. Turning the siren on switches the lights on too; switching the lights off silences the siren. The parked <b>interior view</b> (vehicle panel \u2192 Interior, or <kbd>I</kbd> while stopped) has the same three controls plus the ignition on one screen.",

      "With the siren sounding nearby, civilian traffic slows and pulls toward the shoulder where the road leaves room, and pedestrians stop to watch Unit 9 pass. The flagged sedan on Harbor Ave East can be pulled over with lights alone \u2014 see the traffic-stop chapter of the Officer Field Manual.",

      "The dashboard <b>Police Radio</b> button opens the same equipment screen as <b>Inventory → Police Radio</b>. Carry or equip the issued radio from Locker 7 before transmitting. Plate checks and routine calls use this one interface."]},

    { title:"Glove-compartment contents", body:[

      "Park, stay in the driver's seat, and open the <b>interior view</b> (vehicle panel \u2192 <b>Interior</b>, or <kbd>I</kbd> while stopped). The <b>Glove Compartment</b> button on the passenger side of the dash opens the glove box.",

      "Three items live there: this <b>Vehicle Manual</b>, Unit 9's <b>vehicle registration</b> (a fictional Harbor City document), and a pad of <b>incident-report forms</b>. Tap any of them to inspect it, <b>Take</b> it into your inventory, or <b>Return</b> it. Each item is in exactly one place at a time, so duplicates are impossible, and glove contents are saved. Reports themselves are completed by reporting to Sgt. Brooks \u2014 the forms are the car's paper backup, not a separate system.",

      "There is no flashlight in the glove box on purpose: Jay's flashlight is issued from <b>Locker 7</b> at the precinct, and a second one is never created."]},

    { title:"Ending a shift and securing the vehicle", body:[

      "Shutdown mirrors startup, in reverse. <b>Stop fully</b> first \u2014 Unit 9 will not let you step out or switch off while it is moving. Switch the <b>engine off</b> (<kbd>G</kbd>, the panel, or the interior ignition), open the vehicle panel with <kbd>E</kbd> and <b>Step Out</b>, then <b>close the driver's door</b> and <b>Lock Unit 9</b> from the panel.",

      "Lock, door, seat, engine and parking position are all saved exactly as you leave them, so a locked, secured Unit 9 is what you will find next shift. The siren switches itself off with the engine; the lights stay as you left them in the save, ready to check in the panel. Completing the full shutdown \u2014 engine off, stepped out, door closed, locked \u2014 is the <b>vehicle shutdown/security checklist</b>, and it earns <b>+" + RULES.score.shutdown + " Performance</b>, once per shift.",

      "Back at Precinct 9, return anything you borrowed to <b>Locker 7</b> and report to Sgt. Brooks \u2014 that closes the shift the way the Officer Field Manual's last chapter describes."]}

  ]}

};

var manualOverlay = document.getElementById("manualOverlay");

var manCur = { id:"officer", chap:0 };

function openManual(id, chap){

  if(!MANUALS[id]) id = "officer";

  manCur.id = id;

  manCur.chap = Math.max(0, Math.min(MANUALS[id].chapters.length - 1, chap|0));

  renderManual();

  manualOverlay.classList.add("show");

  sndClick();

}

function closeManual(){

  if(!manualOverlay.classList.contains("show")) return;

  manualOverlay.classList.remove("show");

  sndClick();

}

function renderManual(){

  var m = MANUALS[manCur.id];

  document.getElementById("manTitle").textContent = m.title.toUpperCase();

  var toc = document.getElementById("manToc");

  toc.innerHTML = "";

  m.chapters.forEach(function(ch, i){

    var b = document.createElement("button");

    b.type = "button";

    b.className = i === manCur.chap ? "cur" : "";

    b.textContent = (i + 1) + ". " + ch.title;

    b.addEventListener("click", function(){ manCur.chap = i; renderManual(); sndClick(); });

    toc.appendChild(b);

  });

  var ch = m.chapters[manCur.chap];

  var html = '<span class="man-chap">CHAPTER ' + (manCur.chap + 1) + " OF " + m.chapters.length + "</span><h3>" + ch.title + "</h3>";

  ch.body.forEach(function(p){ html += "<p>" + p + "</p>"; });

  document.getElementById("manPage").innerHTML = html;

  var prev = document.getElementById("btnManPrev"), next = document.getElementById("btnManNext");

  prev.disabled = manCur.chap <= 0; prev.style.opacity = prev.disabled ? ".45" : "";

  next.disabled = manCur.chap >= m.chapters.length - 1; next.style.opacity = next.disabled ? ".45" : "";

}

document.getElementById("btnManClose").addEventListener("click", closeManual);

document.getElementById("btnManBack").addEventListener("click", closeManual);

document.getElementById("btnManPrev").addEventListener("click", function(){ if(manCur.chap > 0){ manCur.chap--; renderManual(); sndClick(); } });

document.getElementById("btnManNext").addEventListener("click", function(){ var n = MANUALS[manCur.id].chapters.length; if(manCur.chap < n - 1){ manCur.chap++; renderManual(); sndClick(); } });

document.getElementById("btnManContents").addEventListener("click", function(){ var t = document.getElementById("manToc"); if(t) t.scrollIntoView({block:"nearest"}); sndClick(); });

manualOverlay.addEventListener("click", function(e){ if(e.target === manualOverlay) closeManual(); });



/* ==================== STAGE C — PERFORMANCE SCORE ====================

   A persistent Performance score in the top bar. Every value and every

   checklist comes from the shared RULES object (top of this script) —

   the same object the manuals' scoring text is built from — so the

   score, the manuals and the action gates cannot drift apart.



   Exactly-once discipline: every one-time event goes through

   awardScore(flagKey, ...), which refuses to pay when the flag is

   already set. Flags live in state.perf.flags (saved), so reloads,

   replays, repeated dialogue, equip/unequip cycles, manual opens and

   control toggles can never re-pay: those actions simply never call

   awardScore at all. Blocked actions (starting without keys, etc.)

   were already explanatory-feedback-only in Stages A/B and stay that

   way — no deduction exists for them anywhere in RULES.



   "Shift" = the case in progress (Case 001 is shift "m1"; Cases

   002–005 are "m2".."m5"; after the campaign, "free" free patrol).

   Closing a case ends its shift: endShift() shows the breakdown, then

   the next shift's total starts from zero. The campaign total never

   resets except on a full game Reset. Performance never gates

   promotions or progress. */

function perfShiftId(){

  if(!state.closed) return "m1";

  var m = currentMission();

  return m ? m : "free";

}

function perfShiftLabel(id){

  id = id || perfShiftId();

  if(id === "m1") return "Case 001 \u2014 The Missing Drive";

  if(id === "free") return "Free Patrol";

  var M = MISSIONS[id];

  return M ? ("Case " + M.num + " \u2014 " + M.name) : id;

}

function perfSyncShift(){

  var cur = perfShiftId();

  if(state.perf.shift !== cur){ state.perf.shift = cur; state.perf.shiftTotal = 0; }

}

function fmtPts(p){ return (p >= 0 ? "+" : "") + p; }

var perfPopTimer = 0;

function scorePop(text, neg){

  var el = document.getElementById("scorePop");

  if(!el) return;

  el.textContent = text;

  el.classList.toggle("neg", !!neg);

  el.classList.add("show");

  if(perfPopTimer) clearTimeout(perfPopTimer);

  perfPopTimer = setTimeout(function(){ el.classList.remove("show"); }, 2600);

}

function renderPerf(){

  var P = state.perf; if(!P) return;

  perfSyncShift();

  var el = document.getElementById("perfScore");

  if(el) el.textContent = P.total;

  var sh = document.getElementById("perfShift");

  if(sh) sh.textContent = "SHIFT " + fmtPts(P.shiftTotal) + " \u00B7 " + perfShiftLabel(P.shift).split(" \u2014 ")[0].toUpperCase();

}

function awardScore(flagKey, action, pts, reason){

  var P = state.perf;

  perfSyncShift();

  if(flagKey){

    if(P.flags[flagKey]) return false;

    P.flags[flagKey] = true;

  }

  P.total += pts; P.shiftTotal += pts;

  P.history.push({ a:action, p:pts, r:reason, s:P.shift, sl:perfShiftLabel(P.shift), t:Date.now() });

  save(); renderPerf();

  scorePop(fmtPts(pts) + " \u00B7 " + action, pts < 0);

  return true;

}

/* --- the seven scored events --- */

function perfCheckReadiness(){

  perfSyncShift();

  for(var i = 0; i < RULES.readiness.length; i++){

    var r = RULES.readiness[i], w = state.gear.where[r.gear];

    if(r.gear === "uniform") w = state.uniform ? "equipped" : w;

    if(r.how === "equipped"){ if(w !== "equipped") return false; }

    else if(w === "locker") return false;

  }

  return awardScore("ready:" + state.perf.shift, "Shift readiness", RULES.score.readiness,

    "Shift-readiness checklist complete: " + RULES.readiness.map(function(x){ return x.label.toLowerCase(); }).join(", ") + ".");

}

function perfCheckShutdown(){

  perfSyncShift();

  if(car.locked && !car.engine && !car.doorOpen && !state.inCar){

    return awardScore("shut:" + state.perf.shift, "Vehicle secured", RULES.score.shutdown,

      "Vehicle shutdown/security checklist complete: " + RULES.shutdown.map(function(x){ return x.toLowerCase(); }).join(", ") + ".");

  }

  return false;

}

var perfLastCollisionAt = 0;

function perfCollision(impactSpeed){

  if(impactSpeed < RULES.collisionMinSpeed) return false;

  var now = Date.now();

  if(now - perfLastCollisionAt < RULES.collisionCooldownMs) return false;

  perfLastCollisionAt = now;

  perfSyncShift();

  var P = state.perf;

  P.total += RULES.score.collision; P.shiftTotal += RULES.score.collision;

  P.history.push({ a:"Vehicle collision", p:RULES.score.collision,

    r:"Avoidable collision while driving Unit 9 \u2014 no damage done, but it goes on the record.",

    s:P.shift, sl:perfShiftLabel(P.shift), t:now });

  save(); renderPerf();

  scorePop(RULES.score.collision + " \u00B7 Vehicle collision", true);

  return true;

}

/* --- history panel --- */

function perfTable(entries, withCtx){

  var tbl = document.createElement("table"); tbl.className = "perf-table";

  tbl.innerHTML = "<thead><tr><th>Action</th><th>Reason</th>" + (withCtx ? "<th class=\"ctx\">Mission / Shift</th>" : "") + "<th class=\"pts\">Points</th></tr></thead>";

  var tb = document.createElement("tbody");

  entries.forEach(function(h){

    var tr = document.createElement("tr");

    var tdA = document.createElement("td"); tdA.className = "act"; tdA.textContent = h.a;

    var tdR = document.createElement("td"); tdR.textContent = h.r;

    tr.appendChild(tdA); tr.appendChild(tdR);

    if(withCtx){

      var tdC = document.createElement("td"); tdC.className = "ctx"; tdC.textContent = h.sl || perfShiftLabel(h.s);

      tr.appendChild(tdC);

    }

    var tdP = document.createElement("td"); tdP.className = "pts " + (h.p < 0 ? "neg" : "pos"); tdP.textContent = fmtPts(h.p);

    tr.appendChild(tdP);

    tb.appendChild(tr);

  });

  tbl.appendChild(tb);

  return tbl;

}

function perfRulesText(){

  var S = RULES.score;

  return [

    "Complete the shift-readiness checklist (" + RULES.readiness.map(function(r){ return r.label.toLowerCase(); }).join(", ") + "): +" + S.readiness + ", once per shift.",

    "Record a required witness statement: +" + S.statement + ", once per statement.",

    "Collect and log required evidence: +" + S.evidence + ", once per item.",

    "Reach a supported case conclusion: +" + S.conclusion + ", once per case.",

    "Complete the vehicle shutdown/security checklist (" + RULES.shutdown.map(function(x){ return x.toLowerCase(); }).join(", ") + "): +" + S.shutdown + ", once per shift.",

    "Submit an unsupported accusation: " + S.unsupported + ", once per distinct accusation submitted (submitting the same one again costs nothing more).",

    "Cause an avoidable vehicle collision: " + S.collision + " per incident, with a " + Math.round(RULES.collisionCooldownMs / 1000) + "-second grace after each one so a single bump never costs twice. Creeping into something while parking doesn't count."

  ];

}

var perfOverlay = document.getElementById("perfOverlay");

function renderPerfHistory(){

  renderPerf();

  var P = state.perf;

  document.getElementById("perfTotalBig").textContent = P.total;

  document.getElementById("perfShiftBigK").textContent = "CURRENT SHIFT \u2014 " + perfShiftLabel(P.shift).toUpperCase();

  document.getElementById("perfShiftBig").textContent = fmtPts(P.shiftTotal);

  var host = document.getElementById("perfHistory");

  host.innerHTML = "";

  if(!P.history.length){

    var d = document.createElement("div"); d.className = "perf-empty";

    d.textContent = "No scored actions yet. Gear up at Locker 7 \u2014 uniform and badge equipped, patrol-car keys and police radio carried \u2014 to complete your first shift-readiness checklist.";

    host.appendChild(d);

  } else {

    host.appendChild(perfTable(P.history.slice().reverse(), true));

  }

  var rl = document.getElementById("perfRulesList");

  rl.innerHTML = "";

  perfRulesText().forEach(function(t){

    var li = document.createElement("li"); li.textContent = t; rl.appendChild(li);

  });

}

function openPerfHistory(){ renderPerfHistory(); perfOverlay.classList.add("show"); sndClick(); }

function closePerfHistory(){ perfOverlay.classList.remove("show"); }

document.getElementById("btnPerf").addEventListener("click", openPerfHistory);

document.getElementById("btnPerfClose").addEventListener("click", closePerfHistory);

document.getElementById("btnPerfBack").addEventListener("click", closePerfHistory);

perfOverlay.addEventListener("click", function(e){ if(e.target === perfOverlay) closePerfHistory(); });

/* --- end-of-shift summary --- */

var shiftOverlay = document.getElementById("shiftOverlay");

var shiftAfter = null;

function shiftFeedback(entries){

  var fb = [];

  function has(a){ return entries.some(function(h){ return h.a === a; }); }

  function count(a){ return entries.filter(function(h){ return h.a === a; }).length; }

  var nUns = count("Unsupported accusation"), nCol = count("Vehicle collision");

  if(has("Shift readiness")) fb.push("Readiness: checklist completed \u2014 uniform and badge on, keys and radio carried before you rolled out. That's the standard in the Officer Field Manual.");

  else fb.push("Readiness: the shift-readiness checklist never completed this shift. From Locker 7: equip the uniform and badge, and carry the patrol-car keys and police radio (" + fmtPts(RULES.score.readiness) + ").");

  var nSt = count("Witness statement"), nEv = count("Evidence logged");

  if(nSt || nEv) fb.push("Investigation: " + nEv + " evidence item" + (nEv === 1 ? "" : "s") + " logged and " + nSt + " witness statement" + (nSt === 1 ? "" : "s") + " recorded \u2014 the case was built on what could be shown, not guessed.");

  if(has("Vehicle secured")) fb.push("Vehicle: Unit 9 was shut down and secured by the book \u2014 engine off, stepped out, door closed, locked.");

  if(nUns) fb.push("Conclusions: " + nUns + " unsupported accusation" + (nUns === 1 ? " was" : "s were") + " submitted (" + RULES.score.unsupported + " each). Brooks explains every rejection \u2014 re-check the statements and the evidence before naming a conclusion.");

  if(nCol) fb.push("Driving: " + nCol + " avoidable collision" + (nCol === 1 ? "" : "s") + " (" + RULES.score.collision + " each). Brake earlier around traffic and walls; a slow parking nudge is never scored.");

  if(!nUns && !nCol && entries.length) fb.push("Clean sheet: no unsupported accusations and no collisions this shift.");

  fb.push("Performance is a record, not a gate \u2014 a low shift never blocks the next case, and promotions still follow case completions exactly as before.");

  return fb;

}

function endShift(endedId, afterFn){

  var P = state.perf;

  var entries = P.history.filter(function(h){ return h.s === endedId; });

  var total = entries.reduce(function(a, h){ return a + h.p; }, 0);

  document.getElementById("shiftTitle").textContent = "SHIFT SUMMARY \u2014 " + perfShiftLabel(endedId).toUpperCase();

  document.getElementById("shiftSub").textContent = "The case is closed, so the shift ends here. This is the shift's breakdown; your campaign score carries forward and the next shift starts from zero.";

  var host = document.getElementById("shiftBody");

  host.innerHTML = "";

  if(entries.length) host.appendChild(perfTable(entries, false));

  else {

    var d = document.createElement("div"); d.className = "perf-empty";

    d.textContent = "No scored actions were recorded this shift.";

    host.appendChild(d);

  }

  var tot = document.createElement("div"); tot.className = "perf-totals"; tot.style.marginTop = "12px";

  tot.innerHTML = "<div class=\"perf-total\"><div class=\"k\">SHIFT TOTAL</div><div class=\"v\"></div></div>" +

                  "<div class=\"perf-total\"><div class=\"k\">CAMPAIGN SCORE</div><div class=\"v\"></div></div>";

  tot.children[0].querySelector(".v").textContent = fmtPts(total);

  tot.children[1].querySelector(".v").textContent = P.total;

  host.appendChild(tot);

  var fbHost = document.getElementById("shiftFeedback");

  fbHost.innerHTML = "";

  shiftFeedback(entries).forEach(function(t){

    var li = document.createElement("li"); li.textContent = t; fbHost.appendChild(li);

  });

  document.getElementById("btnShiftNext").textContent =

    endedId === "m5" ? "See the Campaign Summary" : "Begin Next Shift";

  shiftAfter = (typeof afterFn === "function") ? afterFn : null;

  /* the next case is now the current shift: its total starts from zero */

  P.shift = perfShiftId(); P.shiftTotal = 0;

  save(); renderPerf();

  shiftOverlay.classList.add("show");

}

function closeShiftSummary(){

  shiftOverlay.classList.remove("show");

  var fn = shiftAfter; shiftAfter = null;

  if(fn) fn();

  /* the new shift has begun: if the readiness checklist already stands

     complete (Jay stayed geared up), it pays now — the same treatment a

     reload gives it, so the two paths can never disagree */

  perfCheckReadiness();

}

document.getElementById("btnShiftNext").addEventListener("click", closeShiftSummary);



/* ==================== STAGE B — CAR INTERIOR + GLOVE BOX ====================

   The interior is the parked, in-seat companion to the Stage A vehicle

   panel: same car states, no duplicates. Ignition routes through

   startEngine / stopEngine, lights and siren through the same toggles

   the driving keys use, and the glove box tracks its three items in

   state.glove.where ("glove" / "inv") exactly like the locker's

   one-place-only pattern. Open it from the vehicle panel's Interior

   button, or with I while seated and fully stopped. */

var GLOVE_DEFS = {

  vehmanual:   { name:"Patrol Vehicle Manual", short:"Vehicle Manual",

    desc:"Unit 9's own manual \u2014 five short chapters: unlocking, entering and starting; driving and parking controls; radio, emergency lights and siren; glove-compartment contents; and ending a shift and securing the vehicle. It describes this fictional game's rules exactly as implemented. Read it here, or take it with you and read it from the glove panel." },

  registration:{ name:"Vehicle Registration \u2014 Unit 9", short:"Registration",

    desc:"A fictional Harbor City registration document: Unit 9, patrol cruiser, registered to the Harbor City Police Department, Precinct 9 fleet. Kept in the glove box so it is with the car, not with an officer. Inspecting it changes nothing \u2014 it is proof of what the car is, in paper form." },

  forms:       { name:"Incident-Report Forms", short:"Report Forms",

    desc:"A pad of blank fictional incident-report forms and a stub of a pencil. In Harbor City, reports are completed by reporting your conclusion to Sgt. Brooks in person \u2014 these forms are the car's paper backup, kept stocked for the fiction of the job, and taking or returning them never gates a case." }

};

var GLOVE_ICONS = {

  vehmanual:'<svg viewBox="0 0 48 48" aria-hidden="true"><rect x="11" y="5" width="27" height="38" rx="2.5" fill="#8a2f2b"/><rect x="11" y="5" width="6" height="38" fill="#5f1d1a"/><path d="M20 20 h14 M20 26 h14 M20 32 h9" stroke="#e8dcc2" stroke-width="2.2"/><circle cx="27" cy="12" r="3.4" fill="#c9a227"/></svg>',

  registration:'<svg viewBox="0 0 48 48" aria-hidden="true"><rect x="9" y="7" width="30" height="34" rx="2.5" fill="#e8dfc8"/><path d="M14 15 h20 M14 21 h20 M14 27 h12" stroke="#8a7c5c" stroke-width="2.2"/><circle cx="31" cy="33" r="4.6" fill="none" stroke="#b3362b" stroke-width="2"/></svg>',

  forms:'<svg viewBox="0 0 48 48" aria-hidden="true"><rect x="12" y="6" width="25" height="34" rx="2" fill="#f2eee2"/><rect x="9" y="10" width="25" height="34" rx="2" fill="#ddd5bd"/><path d="M15 18 h14 M15 24 h14 M15 30 h9" stroke="#8a7c5c" stroke-width="2"/></svg>'

};

var intOverlay = document.getElementById("intOverlay");

var gloveOpen = false, gloveSel = null, intMsg = "", intMsgBad = false;

function gloveWhere(id){ return state.glove.where[id]; }

function intSay(msg, bad){ intMsg = msg; intMsgBad = !!bad; if(bad) sndBad(); }

function openInterior(){

  if(!isDriving()){ toast("Get into Unit 9 first \u2014 the interior view is from the driver's seat"); sndBad(); return false; }

  if(Math.abs(car.speed) > 6){ toast("Stop Unit 9 fully before opening the interior view"); sndBad(); return false; }

  if(intOverlay.classList.contains("show")) return true;

  intMsg = ""; intMsgBad = false;

  renderInterior();

  intOverlay.classList.add("show");

  sndDoor();

  save();

  return true;

}

function closeInterior(){

  if(!intOverlay.classList.contains("show")) return;

  intOverlay.classList.remove("show");

  sndClick();

  save();

}

function renderInterior(){

  var ig = document.getElementById("btnIntIgnition");

  ig.textContent = car.engine ? "Ignition \u2014 Engine ON" : "Ignition \u2014 Start Engine";

  ig.classList.toggle("on", !!car.engine);

  var li = document.getElementById("btnIntLights");

  li.textContent = car.lights ? "Lights \u2014 ON" : "Lights \u2014 Off";

  li.classList.toggle("on", !!car.lights);

  var si = document.getElementById("btnIntSiren");

  si.textContent = car.siren ? "Siren \u2014 ON" : "Siren \u2014 Off";

  si.classList.toggle("on", !!car.siren);

  var dl = document.getElementById("intDashLight");

  if(dl) dl.setAttribute("fill", car.engine ? "#57d992" : "#3a4a63");

  var msg = document.getElementById("intMsg");

  msg.textContent = intMsg || "";

  msg.className = "lk-msg int-radio-msg" + (intMsg ? " show" : "") + (intMsgBad ? " bad" : "");

  var gb = document.getElementById("btnGloveToggle");

  gb.textContent = gloveOpen ? "GLOVE COMPARTMENT \u2014 CLOSE" : "GLOVE COMPARTMENT \u2014 OPEN";

  gb.classList.toggle("open", gloveOpen);

  gb.setAttribute("aria-expanded", gloveOpen ? "true" : "false");

  document.getElementById("gloveWrap").classList.toggle("show", gloveOpen);

  renderGlove();

}

function renderGlove(){

  var host = document.getElementById("gloveItems");

  host.innerHTML = "";

  GLOVE_ITEMS.forEach(function(id){

    var d = GLOVE_DEFS[id];

    if(gloveWhere(id) === "glove"){

      var b = document.createElement("button");

      b.type = "button"; b.className = "glove-item" + (gloveSel === id ? " sel" : "");

      b.innerHTML = GLOVE_ICONS[id] + '<span><span class="g-name">' + d.name + '</span><br><span class="g-sub">IN GLOVE BOX</span></span>';

      b.setAttribute("aria-label", d.name + " \u2014 in glove compartment");

      b.addEventListener("click", function(){ gloveSel = id; intMsg = ""; intMsgBad = false; sndClick(); renderInterior(); });

      host.appendChild(b);

    } else {

      var g = document.createElement("div");

      g.className = "glove-item ghost";

      g.innerHTML = GLOVE_ICONS[id] + '<span><span class="g-name">' + d.short + '</span><br><span class="g-sub">CARRIED \u2014 NOT IN BOX</span></span>';

      host.appendChild(g);

    }

  });

  var invEl = document.getElementById("gloveInv");

  invEl.innerHTML = "";

  var carried = GLOVE_ITEMS.filter(function(id){ return gloveWhere(id) === "inv"; });

  if(!carried.length){

    invEl.innerHTML = '<p class="lk-none">Nothing carried from the car yet.</p>';

  } else {

    var wrap = document.createElement("div"); wrap.className = "lk-chiprow";

    carried.forEach(function(id){

      var chip = document.createElement("button");

      chip.type = "button"; chip.className = "lk-chip" + (gloveSel === id ? " sel" : "");

      chip.textContent = GLOVE_DEFS[id].name;

      chip.addEventListener("click", function(){ gloveSel = id; intMsg = ""; intMsgBad = false; sndClick(); renderInterior(); });

      wrap.appendChild(chip);

    });

    invEl.appendChild(wrap);

  }

  renderGloveDetail();

}

function renderGloveDetail(){

  var el = document.getElementById("gloveDetail");

  var html = "";

  if(!gloveSel || !GLOVE_DEFS[gloveSel]){

    html += "<h3>GLOVE COMPARTMENT</h3>" +

      '<span class="lk-status">TAP AN ITEM</span>' +

      "<p>Everything here belongs to Unit 9. <b>Take</b> moves an item into your inventory, <b>Return</b> puts it back in the box, and the Vehicle Manual can be <b>Read</b> from either place. An item is only ever in one place, so duplicates are impossible \u2014 and everything is saved.</p>";

    el.innerHTML = html; return;

  }

  var id = gloveSel, d = GLOVE_DEFS[id], w = gloveWhere(id);

  html += "<h3>" + d.name + "</h3>";

  html += '<span class="lk-status' + (w === "inv" ? " eq" : "") + '">' + (w === "inv" ? "IN YOUR INVENTORY" : "IN THE GLOVE BOX") + "</span>";

  html += "<p>" + d.desc + "</p>";

  var acts = "";

  if(w === "glove") acts += '<button type="button" class="dbtn gold" data-glvact="take">Take</button>';

  else acts += '<button type="button" class="dbtn gold" data-glvact="return">Return to Glove Box</button>';

  if(id === "vehmanual") acts += '<button type="button" class="dbtn" data-glvact="read">Read Manual</button>';

  html += '<div class="lk-actions">' + acts + "</div>";

  el.innerHTML = html;

  el.querySelectorAll("[data-glvact]").forEach(function(btn){

    btn.addEventListener("click", function(){ gloveAct(id, btn.getAttribute("data-glvact")); });

  });

}

function gloveAct(id, act){

  var d = GLOVE_DEFS[id];

  if(act === "read"){ openManual("vehicle", 0); return; }

  if(act === "take"){

    if(gloveWhere(id) !== "glove"){ intSay(d.name + " isn't in the glove box right now.", true); }

    else { state.glove.where[id] = "inv"; intSay("Taken: " + d.name + " is now in your inventory."); sndGood(); }

  } else if(act === "return"){

    if(gloveWhere(id) !== "inv"){ intSay(d.name + " is already in the glove box.", true); }

    else { state.glove.where[id] = "glove"; intSay("Returned: " + d.name + " is back in Unit 9's glove box."); sndClick(); }

  }

  save();

  renderInterior();

}

document.getElementById("btnGloveToggle").addEventListener("click", function(){ gloveOpen = !gloveOpen; sndClick(); renderInterior(); });

document.getElementById("btnIntClose").addEventListener("click", closeInterior);

document.getElementById("btnIntBack").addEventListener("click", closeInterior);

intOverlay.addEventListener("click", function(e){ if(e.target === intOverlay) closeInterior(); });

document.getElementById("btnIntIgnition").addEventListener("click", function(){

  ensureAudio();

  if(car.engine){ if(stopEngine()) intSay("Engine off. Unit 9 stays exactly as parked until you start her again."); }

  else { if(startEngine()) intSay("Engine running. Close the interior and drive \u2014 L lights, K siren, G engine, all without menus."); else intSay(vehMsg || "The engine won't start \u2014 check the vehicle panel message.", true); }

  renderInterior();

});

document.getElementById("btnIntLights").addEventListener("click", function(){

  ensureAudio(); car.lights = !car.lights; if(!car.lights) car.siren = false; sndClick(); updateDriveUI(); save();

  intSay(car.lights ? "Emergency lights ON \u2014 the light bar is flashing." : "Emergency lights OFF."); renderInterior();

});

document.getElementById("btnIntSiren").addEventListener("click", function(){

  ensureAudio(); car.siren = !car.siren; if(car.siren) car.lights = true; sndClick(); updateDriveUI(); save();

  intSay(car.siren ? "Siren ON \u2014 and the lights came on with it, as they do out on the road." : "Siren OFF."); renderInterior();

});

function doReception(){

  if(currentMission() === "m3" && state.camp.m3.brief && stGot("m3ana") && !stGot("m3hale")){

    showChoices("FRONT DESK \u2014 CALL EMMETT HALE", "Chen patches you through to a Portside number Ana gave you. Hale picks up on the second ring.", [

      {label:"\u201CMr. Hale, this is Officer Jay, Precinct 9. You're not in trouble \u2014 you're a witness. Tell me about the photo.\u201D", fn:function(){

        showLines([

          ["EMMETT HALE (PHONE)", STATEMENTS.m3hale.text],

          ["JAY", "Statement recorded, Mr. Hale \u2014 word for word. Stay with your sister until Sergeant Brooks clears you to come home. And thank you: the photo and the key may finish this."]

        ], function(){ recordStatement("m3hale"); });

      }},

      {label:"Demand he return to Harbor City immediately.", fn:function(){

        showLines([["EMMETT HALE (PHONE)", "\u2026I ran from a note under my door, Officer. Ask me straight and I'll tell you everything \u2014 threaten me and you'll get my sister's answering machine."]], function(){ doReception(); });

      }}

    ]);

    return;

  }

  showLines([

    ["OFFICER CHEN", "Front desk, Precinct 9. Looking for a room? Evidence, Records, Interview and Briefing are upstairs\u2014 north side. Operations and the Sergeant's office mid-floor. Intake, Holding and the Garage down here with the Lobby."],

    ["OFFICER CHEN", "Leaving the building? Main entrance is right here in the lobby; the garage door drops you straight into the parking lot. And the city map is on M if you get turned around out there."]

  ], null);

}

function doCells(){

  if(!state.camp || !state.camp.ferrisIn){

    showLines([

      ["HOLDING CELLS", "Three cells, all empty, bunks made, log signed. Cell 2's board reads: NO OCCUPANT. Harbor City's quieter nights look like this."],

      ["JAY", "Nothing to interview but the echo. Cases make occupants, and mine hasn't — yet."]

    ], null);

    return;

  }

  if(currentMission() === "m4" && !stGot("m4ferris")){

    if(!state.camp.m4.returned){

      showLines([

        ["DOYLE FERRIS", "So the ledger had my initials and suddenly I'm popular. Here's the thing, Officer \u2014 I talk when the evidence is on the record, not before. Bag the warehouse haul, log it in Evidence, then come back and I'll tell you whose ring it is."],

        ["JAY", "He wants the chain of custody clean before he talks. Smart, in its way. Evidence Room first, then this cell."]

      ], null);

      return;

    }

    showChoices("HOLDING CELL 2 \u2014 INTERVIEW: DOYLE FERRIS", "The warehouse evidence is logged and receipted in the Evidence Room. Ferris sits, cuffed to the table ring, watching you. Open with:", [

      {label:"Lay it out: Reyes named him, the ledger initials him, the crates convict someone. \u201CWhose operation is it, Doyle?\u201D", fn:function(){

        showLines([

          ["DOYLE FERRIS", "\u2026Reyes talked. Then the yard talked. Fine \u2014 everybody talks but the man who pays."],

          ["DOYLE FERRIS", STATEMENTS.m4ferris.text],

          ["JAY", "Statement recorded. That changes you from the whole case to a cooperating accomplice, Ferris \u2014 Brooks will hear exactly that, from me."]

        ], function(){ recordStatement("m4ferris"); });

      }},

      {label:"Tell Ferris he's the mastermind and this is his last chance.", fn:function(){

        showLines([["DOYLE FERRIS", "Mastermind? I drive a truck and lift crates for cash, Officer. Put the actual evidence in front of me and ask about the man on the letterhead \u2014 you'll get a statement. Theatre gets you nothing."]], function(){ doCells(); });

      }},

      {label:"Ask Ferris what the Gray Gull carries.", fn:function(){

        showLines([["DOYLE FERRIS", "Everything, eventually. Ask me the real question \u2014 whose ring it is \u2014 with the evidence on the table."]], function(){ doCells(); });

      }}

    ]);

    return;

  }

  if(stGot("m4ferris")){

    showLines([

      ["DOYLE FERRIS", "Statement's signed, coffee was terrible, conscience is\u2026 lighter. Whatever Brooks decides, I told the truth in there. Voss's shed, Voss's ship, Voss's ring. Go finish it."],

      ["JAY", "He stays in custody as a cooperating accomplice. The notebook has his words; the rest is Brooks' call \u2014 and then the waterfront."]

    ], null);

    return;

  }

  showLines([

    ["HOLDING CELL 2", "Doyle Ferris, Voss Import Parts' night driver, detained for questioning. He watches the corridor like a man deciding how much the truth is worth."],

    ["JAY", "He's secure and logged. The interview comes when the case is ready for it."]

  ], null);

}

