/* ============================== INTERACT DISPATCH ============================== */

function interact(){

  if(dlgOpen) return;

  if(typeof csActive !== "undefined" && csActive) return;

  if(isDriving()){

    /* E while in Unit 9 opens the vehicle panel (engine off / step out live

       there); while rolling it explains instead of ejecting Jay. */

    if(Math.abs(car.speed) > 6){ toast("Stop Unit 9 fully first \u2014 then E opens the vehicle panel"); sndBad(); return; }

    openVehPanel(); return;

  }

  if(!nearSpot){

    setDialogue("DISPATCH", "Nothing to examine here. Walk up to a gold-ringed, labeled marker \u2014 the pulsing beacon marks your current case objective, and press M for the city map if you're lost.", "");

    return;

  }

  var s = nearSpot;

  if(s.to){ sndDoor(); goTo(s.to.map, s.to.x, s.to.y); return; }

  sndClick();

  var id = s.id;

  if(id.indexOf("npc:") === 0){ var fn = TALKS[id.slice(4)]; if(fn) fn(); return; }

  if(id.indexOf("ped:") === 0){ talkPed(parseInt(id.slice(4), 10)); return; }

  if(id.indexOf("fig:") === 0){ talkFig(parseInt(id.slice(4), 10)); return; }

  switch(id){

    case "tag": return doTag();

    case "records": return doRecords();

    case "witness": return doWitness();

    case "drive": return doDrive();

    case "sergeant": return doSergeant();

    case "evshelf": return doEvShelf();

    case "database": return openDb();

    case "briefboard": return window.HARBOR.board.open();

    case "locker": return doLocker();

    case "reception": return doReception();

    case "cells": return doCells();

    case "cruiser": return doCruiser();

    case "patrolcar": return openVehPanel();

    case "flag": return doFlag();

    case "trafficStop": return startTrafficStop();

    case "tsDriver": return doTsDriver();

    case "tsCar": return doTsCar();

    case "tsRadio": return doTsRadio();

    case "lostBadge": return doLostBadge();

    case "atm": return doAtm();

    case "booksDoor": return doBooks();

    case "fountain": return doFountain();

    case "busstop": return doBusstop();

    case "storeCamera": return doStoreCamera();

    case "storeShelf": return doStoreShelf();

    case "storeRear": return doStoreRear();

    case "haleDoor": return doHaleDoor();

    case "haleNote": return doHaleNote();

    case "halePhoto": return doHalePhoto();

    case "haleKey": return doHaleKey();

    case "shedGoods": return doShedGoods();

    case "shedDesk": return doShedDesk();

    case "cafeMenu": return doCafeMenu();

    case "cafeTable": return doCafeTable();

    case "muniDirectory": return doMuniDirectory();

    case "muniDesk": return doMuniDesk();

    case "mailbox": return doMailbox();

    case "bigtree": return doBigtree();

    case "houseTV": return doHouseTV();

    case "houseFridge": return doHouseFridge();

    case "houseBed": return doHouseBed();

    case "coldDoor": return doColdDoor();

    case "yardCrates": return doYardCrates();

    case "whManifest": return doWhManifest();

    case "whCrates": return doWhCrates();

    case "whDock": return doWhDock();

    case "shed": return doShed();

    case "pier": return doPier();

    case "lighthouse": return doLighthouse();

    case "harborLog": return doHarborLog();

  }

}



/* ============================== PANELS ============================== */

function refreshPanels(){

  try{ renderPerf(); }catch(e){}

  var n = findingCount();

  document.getElementById("objCount").textContent = (n + (state.closed?1:0)) + " / 5";

  document.getElementById("nbCount").textContent = n + " / 4 FINDINGS";

  document.querySelectorAll("#objList li").forEach(function(li){

    var k = li.getAttribute("data-obj");

    var done = k==="sergeant" ? state.closed : !!state.findings[k];

    li.classList.toggle("done", done);

    li.querySelector(".box").textContent = done ? "\u2713" : "";

    var current = !done && ((k==="sergeant" && n===4) || (k!=="sergeant" && ORDER.indexOf(k)===n));

    li.classList.toggle("current", current);

    li.classList.toggle("locked", k==="sergeant" && n<4 && !state.closed);

  });

  var nb = document.getElementById("notebook");

  nb.innerHTML = "";

  ORDER.forEach(function(k, i){

    var div = document.createElement("div");

    if(state.findings[k]){

      div.className = "finding";

      div.innerHTML = "<h4>\uD83D\uDCD3 " + FINDINGS[k].title + "</h4>";

      var p = document.createElement("p"); p.textContent = FINDINGS[k].text; div.appendChild(p);

    } else {

      div.className = "finding empty";

      div.innerHTML = "<h4>Finding " + (i+1) + " \u2014 not yet collected</h4>";

      var p2 = document.createElement("p"); p2.textContent = "Keep investigating \u2014 it's inside Precinct 9."; div.appendChild(p2);

    }

    nb.appendChild(div);

  });

  /* Campaign panel + Evidence + Statements */

  try{

    var evHost=document.getElementById("evidenceList");

    if(evHost){

      evHost.innerHTML="";

      var anyEv=false, evTotal=0;

      if(state.findings.drive){ anyEv=true; evTotal++; var d0=document.createElement("div"); d0.className="ev-item"; d0.innerHTML="<h4>USB Drive EV-001 <span class='ev-tag returned'>RETURNED</span></h4>"; var pp=document.createElement("p"); pp.textContent="Case 001 \u2014 recovered from Intake Tray B, seal intact."; d0.appendChild(pp); evHost.appendChild(d0); }

      EVIDENCE_ORDER.forEach(function(k){

        if(evGot(k)){ anyEv=true; evTotal++; var E = EVIDENCE[k]; var ret = !!state.camp[E.m].returned; var d=document.createElement("div"); d.className="ev-item"; d.innerHTML="<h4>"+E.name+" <span class='ev-tag"+(ret?" returned":"")+"'>"+(ret?"RETURNED":"IN BAG")+"</span></h4>"; var pe=document.createElement("p"); pe.textContent=E.desc+" \u00b7 Case "+MISSIONS[E.m].num; d.appendChild(pe); evHost.appendChild(d); }

      });

      if(!anyEv){ evHost.innerHTML="<div class='finding empty'><h4>No evidence collected yet</h4><p>Inspect scenes and bag items \u2014 they will appear here with name, description and case.</p></div>"; }

      document.getElementById("evCount").textContent = evTotal+" ITEMS";

    }

    var stHost=document.getElementById("statements");

    if(stHost){

      var parts=[];

      if(state.findings.witness) parts.push({n:"Maya Torres \u2014 Case 001", t:FINDINGS.witness.text});

      STATEMENTS_ORDER.forEach(function(k){ if(stGot(k)) parts.push({n:STATEMENTS[k].name+" \u2014 Case "+MISSIONS[STATEMENTS[k].m].num, t:STATEMENTS[k].text}); });

      stHost.innerHTML = "";

      if(parts.length){

        var sh = document.createElement("h4"); sh.style.cssText = "margin:0 0 8px;font-size:14px;"; sh.textContent = "WITNESS STATEMENTS"; stHost.appendChild(sh);

        parts.forEach(function(pt){

          var d = document.createElement("div"); d.className = "finding";

          var hh = document.createElement("h4"); hh.textContent = "\uD83D\uDCD3 " + pt.n; d.appendChild(hh);

          var pp2 = document.createElement("p"); pp2.textContent = pt.t; d.appendChild(pp2);

          stHost.appendChild(d);

        });

      } else {

        stHost.innerHTML = "<p style='margin:0;font-size:13.5px;color:var(--ink2);'>No witness statements yet \u2014 interview people and choose questions; statements are recorded here.</p>";

      }

      var nbC=document.getElementById("nbCount"); if(nbC) nbC.textContent = findingCount()+" / 4 FINDINGS \u00b7 "+parts.length+" STATEMENTS";

    }

  }catch(e){}

  var rl = document.getElementById("rankLabel");

  rl.textContent = state.rank.toUpperCase();

  rl.classList.toggle("officer", state.rank === "Patrol Officer");

  rl.classList.toggle("detective", state.rank === "Detective");

  var cs = document.getElementById("caseStatus");

  var curM2 = currentMission();

  cs.textContent = campaignDone() ? "CAMPAIGN COMPLETE" : (state.closed ? "CASE " + MISSIONS[curM2].num + " OPEN" : "CASE OPEN");

  cs.classList.toggle("closed", campaignDone());

}



/* ============================== CITY MAP OVERLAY ==============================

   The map is the approved illustrated Harbor City artwork

   (assets/embedded/b4844e95de2621af6d74.webp). District labels and markers are HTML

   overlays positioned in stage percentages (ZONE_ART, x/y in % of the

   artwork). Every marker is offset from its district label — Jay below-left,

   Unit 9 below-right, the objective star above — so no marker ever sits on

   top of a district name (the old diagram stamped JAY over PRECINCT

   GROUNDS). The stage pans inside .mapview and zooms via .mapstage width. */

var ZONE_ART = { station:[52,12.5], northgate:[88.5,11], westfield:[30,13],

                 residential:[16.5,25], plaza:[74.7,29.5],

                 southbay:[40,75], midtown:[67.5,43], downtown:[49.3,49.4],

                 waterfront:[18.4,63.8], eastside:[63,66.5], industrial:[86.5,75] };

var ZONE_NAMES = { station:"PRECINCT 9", northgate:"NORTHGATE", westfield:"WESTFIELD",

                   residential:"RESIDENTIAL", plaza:"PRECINCT GROUNDS", southbay:"SOUTHBAY",

                   midtown:"MIDTOWN", downtown:"DOWNTOWN", waterfront:"WATERFRONT",

                   eastside:"EASTSIDE", industrial:"INDUSTRIAL" };

var mapOverlay = document.getElementById("mapOverlay");

var mapView = document.getElementById("mapView");

var mapStage = document.getElementById("mapStage");

var mapZoom = 1;

(function buildZoneLabels(){

  var host = document.getElementById("mapZones");

  Object.keys(ZONE_ART).forEach(function(z){

    var el = document.createElement("div");

    el.className = "zlabel"; el.setAttribute("data-zone", z);

    el.textContent = ZONE_NAMES[z];

    el.style.left = ZONE_ART[z][0] + "%"; el.style.top = ZONE_ART[z][1] + "%";

    host.appendChild(el);

  });

})();

function setMapZoom(z){

  /* keep the point at the centre of the viewport centred across the zoom */

  var fx = mapView.clientWidth ? (mapView.scrollLeft + mapView.clientWidth/2) / mapStage.offsetWidth : .5;

  var fy = mapView.clientHeight ? (mapView.scrollTop + mapView.clientHeight/2) / mapStage.offsetHeight : .5;

  mapZoom = Math.max(1, Math.min(3, z));

  mapStage.style.width = (mapZoom * 100) + "%";

  document.getElementById("mapZoomPct").textContent = Math.round(mapZoom * 100) + "%";

  mapView.scrollLeft = fx * mapStage.offsetWidth - mapView.clientWidth/2;

  mapView.scrollTop = fy * mapStage.offsetHeight - mapView.clientHeight/2;

}

function centerMapOn(xPct, yPct){

  requestAnimationFrame(function(){

    mapView.scrollLeft = mapStage.offsetWidth * xPct/100 - mapView.clientWidth/2;

    mapView.scrollTop = mapStage.offsetHeight * yPct/100 - mapView.clientHeight/2;

  });

}

document.getElementById("mapZoomIn").addEventListener("click", function(){ setMapZoom(mapZoom * 1.3); });

document.getElementById("mapZoomOut").addEventListener("click", function(){ setMapZoom(mapZoom / 1.3); });

document.getElementById("mapZoomPct").addEventListener("click", function(){ setMapZoom(1); });

/* drag-to-pan with the mouse (touch pans natively via the scroll viewport);

   markers and labels are pointer-events:none, so the drag works anywhere */

(function(){

  var drag = null;

  mapView.addEventListener("pointerdown", function(e){

    if(e.pointerType !== "mouse") return;

    drag = { x:e.clientX, y:e.clientY, l:mapView.scrollLeft, t:mapView.scrollTop };

    mapView.classList.add("dragging");

  });

  window.addEventListener("pointermove", function(e){

    if(!drag) return;

    mapView.scrollLeft = drag.l - (e.clientX - drag.x);

    mapView.scrollTop = drag.t - (e.clientY - drag.y);

  });

  window.addEventListener("pointerup", function(){ drag = null; mapView.classList.remove("dragging"); });

})();

function placeMark(el, xPct, yPct){ el.style.left = xPct + "%"; el.style.top = yPct + "%"; }

function openMap(){

  var here = locById(state.map);

  var zone = here ? here.zone : "station";

  document.querySelectorAll("#mapZones .zlabel").forEach(function(z){

    z.classList.toggle("here", z.getAttribute("data-zone") === zone);

  });

  var a = ZONE_ART[zone] || ZONE_ART.station;

  var you = document.getElementById("mapYou");

  placeMark(you, a[0] - 5.4, a[1] + 6.2); /* below-left of the district label */

  var yt = document.getElementById("mapYouTxt");

  yt.textContent = isDriving() ? "JAY \u00B7 IN UNIT 9" : "JAY";

  /* Patrol car marker (blue) in its own district, below-right of its label;

     hidden while Jay is driving it — his tag already says so */

  var carG = document.getElementById("mapCar");

  var carLoc = locById(car.map);

  var carZone = carLoc ? carLoc.zone : "plaza";

  var ca = ZONE_ART[carZone] || ZONE_ART.plaza;

  if(isDriving()) carG.style.display = "none";

  else { carG.style.display = ""; placeMark(carG, ca[0] + 5.4, ca[1] + 6.2); }

  var dest = document.getElementById("mapDest");

  var tgt = currentTargetId();

  var tgtDest2 = targetDest(tgt);

  if(tgt && tgtDest2){

    var dz = locById(tgtDest2.map).zone;

    var da = ZONE_ART[dz] || a;

    placeMark(dest, da[0], da[1] - 6.4); /* above the district label */

    dest.style.display = "";

  } else dest.style.display = "none";

  var carHere = locById(car.map);

  document.getElementById("mapSub").innerHTML = (tgt && tgtDest2

    ? "You are at <b>" + (here ? here.name : curMap().name) + "</b>. Objective: <b>" + tgtDest2.text + "</b> \u2014 " + tgtDest2.where + " (green star)."

    : "You are at <b>" + (here ? here.name : curMap().name) + "</b>. All cases closed \u2014 Harbor City is yours to explore.")

    + " <b>Unit 9 (blue)</b> is at <b>" + (carHere ? carHere.name : car.map) + "</b>" + (isDriving() ? " \u2014 you are driving it." : ".");

  var list = document.getElementById("locList");

  list.innerHTML = "";

  LOCATIONS.forEach(function(L){

    var li = document.createElement("li");

    var nm = document.createElement("span"); nm.textContent = L.name; li.appendChild(nm);

    if(L.id === state.map){

      var tg = document.createElement("span"); tg.className = "tag here"; tg.textContent = "YOU ARE HERE"; li.appendChild(tg);

    } else if(tgt && tgtDest2 && L.id === tgtDest2.map){

      var tg2 = document.createElement("span"); tg2.className = "tag dest"; tg2.textContent = "OBJECTIVE"; li.appendChild(tg2);

    }

    list.appendChild(li);

  });

  mapOverlay.classList.add("show");

  /* Phones open zoomed in so the district labels stay legible, centred on

     Jay; desktops open on the whole city. */

  setMapZoom(mapView.clientWidth && mapView.clientWidth < 560 ? 1.9 : 1);

  centerMapOn(a[0], a[1]);

}

