/* ============================== DATABASE OVERLAY ============================== */

var dbOverlay = document.getElementById("dbOverlay");

function renderDb(q){

  var rawQ = (q || "").trim();

  q = rawQ.toLowerCase();

  if(currentMission() === "m2" && state.camp.m2.brief && !state.camp.m2.db && rawQ){

    if(q.indexOf("voss")>=0 || q.indexOf("4417")>=0 || q.indexOf("hbr")>=0){

      state.camp.m2.db = true; save(); refreshPanels();

      toast("Evidence match: HBR-4417 is the Voss night-delivery truck! The pickle cannot drive it.");

    }

  }

  var rows = DB_RECORDS.filter(function(r){

    if(!q) return true;

    return (r.name + " " + r.badge + " " + r.role + " " + r.detail).toLowerCase().indexOf(q) >= 0;

  });

  document.getElementById("dbCount").textContent = rows.length + " record" + (rows.length===1?"":"s") + (q ? " matching \u201C" + q + "\u201D" : " on file");

  var host = document.getElementById("dbResults");

  host.innerHTML = "";

  if(!rows.length){

    var d = document.createElement("div"); d.className = "db-none";

    d.textContent = "No records match. Check the spelling, or search a badge number, name or assignment.";

    host.appendChild(d); return;

  }

  var tbl = document.createElement("table"); tbl.className = "db-table";

  tbl.innerHTML = "<tr><th>Badge</th><th>Name</th><th>Assignment</th><th>Record</th></tr>";

  rows.forEach(function(r){

    var tr = document.createElement("tr");

    var td1 = document.createElement("td"); td1.className = "mono"; td1.textContent = r.badge;

    var td2 = document.createElement("td"); td2.textContent = r.name;

    var td3 = document.createElement("td"); td3.textContent = r.role;

    var td4 = document.createElement("td"); td4.textContent = r.detail;

    tr.appendChild(td1); tr.appendChild(td2); tr.appendChild(td3); tr.appendChild(td4);

    tbl.appendChild(tr);

  });

  host.appendChild(tbl);

}

function openDb(){

  renderDb("");

  document.getElementById("dbQuery").value = "";

  dbOverlay.classList.add("show");

  setTimeout(function(){ document.getElementById("dbQuery").focus(); }, 60);

}

