function overlayOpen(){ return mapOverlay.classList.contains("show") || dbOverlay.classList.contains("show") || (document.getElementById("menuPage") && document.getElementById("menuPage").classList.contains("show")) || (document.getElementById("invPage") && document.getElementById("invPage").classList.contains("show")) || (document.getElementById("tutorialOverlay") && document.getElementById("tutorialOverlay").classList.contains("show")) || (document.getElementById("endOverlay") && document.getElementById("endOverlay").classList.contains("show")) || (document.getElementById("lockerOverlay") && document.getElementById("lockerOverlay").classList.contains("show")) || (document.getElementById("vehOverlay") && document.getElementById("vehOverlay").classList.contains("show")) || (document.getElementById("intOverlay") && document.getElementById("intOverlay").classList.contains("show")) || (document.getElementById("manualOverlay") && document.getElementById("manualOverlay").classList.contains("show")); }



/* ============================== INPUT ============================== */

var KEYMAP = { ArrowUp:"up", KeyW:"up", ArrowDown:"down", KeyS:"down",

               ArrowLeft:"left", KeyA:"left", ArrowRight:"right", KeyD:"right" };

document.addEventListener("pointerdown", ensureAudio);

document.addEventListener("keydown", function(e){

  ensureAudio();

  if(e.code === "KeyM"){

    e.preventDefault();

    if(lockerOverlay.classList.contains("show")) return;

    if(vehOverlay.classList.contains("show")) return;

    if(document.getElementById("intOverlay").classList.contains("show")) return;

    if(document.getElementById("manualOverlay").classList.contains("show")) return;

    if(dbOverlay.classList.contains("show")) closeDb();

    if(mapOverlay.classList.contains("show")) closeMap(); else openMap();

    return;

  }

  if(e.code === "Escape"){

    /* close only the topmost Stage B layer first, so Esc in a manual

       returns to the locker / interior it was opened from */

    if(document.getElementById("manualOverlay").classList.contains("show")){ closeManual(); return; }

    if(document.getElementById("intOverlay").classList.contains("show")){ closeInterior(); return; }

    /* Esc on the menu page itself (no overlay or modal stacked above it)

       closes just the menu and returns to the unchanged game. */

    var mpEsc = document.getElementById("menuPage");

    if(mpEsc && mpEsc.classList.contains("show") && !document.querySelector(".overlay-back.show") && !document.querySelector(".modal-back.show")){ closeMenuPage(); return; }

    /* Same for the inventory page: Esc closes just it, back to the

       unchanged game. */

    var ipEsc = document.getElementById("invPage");

    if(ipEsc && ipEsc.classList.contains("show") && !document.querySelector(".overlay-back.show") && !document.querySelector(".modal-back.show")){ closeInvPage(); return; }

    closeMap(); closeDb(); closeLocker(); closeVehPanel(); try{ closeTutorial(); }catch(err){} var eo = document.getElementById("endOverlay"); if(eo) eo.classList.remove("show"); return;

  }

  if(overlayOpen()) return;

  if(e.code === "Equal" || e.code === "NumpadAdd"){ e.preventDefault(); if(!e.repeat) sndClick(); zoomBy(1.25); return; }

  if(e.code === "Minus" || e.code === "NumpadSubtract"){ e.preventDefault(); if(!e.repeat) sndClick(); zoomBy(1 / 1.25); return; }

  if(dlgOpen && (e.code === "Enter" || e.code === "Space")){

    var ae = document.activeElement;

    var focusOnDlgBtn = ae && dlgActions.contains(ae);

    if(!focusOnDlgBtn){

      var nb = document.getElementById("dlgNext");

      if(nb){ e.preventDefault(); nb.click(); return; }

    }

  }

  if(dlgOpen && /^Digit[1-4]$/.test(e.code)){

    var ci = parseInt(e.code.slice(5), 10) - 1;

    var choices = dlgActions.querySelectorAll(".choice-btn");

    if(choices[ci]){ e.preventDefault(); choices[ci].click(); return; }

  }

  if(isDriving() && !dlgOpen){

    if(e.code === "KeyL"){ e.preventDefault(); car.lights = !car.lights; if(!car.lights) car.siren = false; sndClick(); updateDriveUI(); save(); toast(car.lights ? "Emergency lights ON" : "Emergency lights OFF"); return; }

    if(e.code === "KeyK"){ e.preventDefault(); car.siren = !car.siren; if(car.siren) car.lights = true; sndClick(); updateDriveUI(); save(); toast(car.siren ? "Siren ON" : "Siren OFF"); return; }

    if(e.code === "KeyG"){ e.preventDefault(); toggleEngine(); return; }

    if(e.code === "KeyI"){ e.preventDefault(); if(Math.abs(car.speed) > 6){ toast("Stop Unit 9 fully first \u2014 then I opens the interior view"); sndBad(); } else openInterior(); return; }

    if(e.code === "KeyF"){ e.preventDefault(); if(Math.abs(car.speed) > 6){ toast("Stop Unit 9 fully first \u2014 then F opens the vehicle panel"); sndBad(); } else openVehPanel(); return; }

    if(e.code === "Space"){ window.__carSpace = true; e.preventDefault(); return; }

  }

  if(dlgOpen||csActive)return;

  if(KEYMAP[e.code]){

    /* FLUIDITY PASS: key events only record held state. The old handler

       also blipped the pedals / wheel and stepped Jay by a fixed 0.024s

       on every keydown — including OS key-repeats — so a tap's effect

       depended on the device's repeat rate. The loop's time-based

       simulation now owns all motion; a short tap still registers

       because the key is held until keyup and integrated per frame. */

    keys[KEYMAP[e.code]] = true; e.preventDefault();

  }

  else if(e.code === "KeyE"){ e.preventDefault(); interact(); }

});

document.addEventListener("keyup", function(e){

  if(e.code === "Space"){ window.__carSpace = false; }

  if(KEYMAP[e.code]){ keys[KEYMAP[e.code]] = false; e.preventDefault(); }

});

/* FLUIDITY PASS — focus loss clears every held input. If the window

   loses focus (or the tab is hidden) while a direction, pedal or the

   brake is held, the matching keyup/pointerup may never arrive and

   Jay or Unit 9 would drive on alone; on return, all held state is

   cleared and the touch buttons' held styling is reset. */

var heldInputResets=[];

function clearHeldInputs(){

  (heldInputResets||[]).forEach(function(reset){reset();});

  keys.up = keys.down = keys.left = keys.right = false;

  driveKeys.up = driveKeys.down = driveKeys.left = driveKeys.right = driveKeys.brake = false;

  window.__carSpace = false;

  document.querySelectorAll(".held").forEach(function(el){ el.classList.remove("held"); });

}

window.addEventListener("blur", clearHeldInputs);

window.addEventListener("pagehide", clearHeldInputs);

document.addEventListener("visibilitychange", function(){ if(document.hidden) clearHeldInputs(); });

/* FLUIDITY PASS — touch pads use pointer capture with per-pointer

   tracking: a held direction no longer drops when the finger slides a

   few pixels off the button (the old pointerleave release), a second

   finger resting on the same pad doesn't cancel the first, and two

   pads held at once (diagonal walking) both stay live until each

   finger actually lifts. */

function bindHoldButton(btn, setHeld){

  var active = {};

  heldInputResets.push(function(){active={};setHeld(false);btn.classList.remove("held");});

  function refresh(){

    var any = false; for(var k in active) if(active[k]) any = true;

    setHeld(any);

    btn.classList.toggle("held", any);

  }

  btn.addEventListener("pointerdown", function(e){

    e.preventDefault();if(dlgOpen||csActive||overlayOpen())return;ensureAudio();

    active[e.pointerId] = true;

    try{ btn.setPointerCapture(e.pointerId); }catch(err){}

    refresh();

  });

  function release(e){

    if(e && typeof e.pointerId !== "undefined") delete active[e.pointerId];

    refresh();

  }

  btn.addEventListener("pointerup", release);

  btn.addEventListener("pointercancel", release);

  btn.addEventListener("lostpointercapture", release);

  function clearHeld(){ active = {}; refresh(); }

  window.addEventListener("blur", clearHeld);

  document.addEventListener("visibilitychange", function(){ if(document.hidden) clearHeld(); });

  btn.addEventListener("contextmenu", function(e){ e.preventDefault(); });

}

document.querySelectorAll(".dbtn-pad[data-dir]").forEach(function(btn){

  var dir = btn.getAttribute("data-dir");

  bindHoldButton(btn, function(held){ keys[dir] = held; });

});

