/* Pinch-to-zoom on the game canvas: a two-finger spread/pinch scales the

   world view. The camera stays locked on Jay at every level, so no focal

   point math is needed; touch-action:none (canvas CSS) keeps the browser

   from hijacking the gesture. */

(function(){

  var pinchD = 0;

  function tDist(ts){

    var dx = ts[0].clientX - ts[1].clientX, dy = ts[0].clientY - ts[1].clientY;

    return Math.sqrt(dx * dx + dy * dy);

  }

  canvas.addEventListener("touchstart", function(e){

    if(e.touches.length === 2){ pinchD = tDist(e.touches); e.preventDefault(); }

  }, { passive:false });

  canvas.addEventListener("touchmove", function(e){

    if(e.touches.length === 2 && pinchD > 0){

      e.preventDefault();

      var d = tDist(e.touches);

      if(d > 0){ setZoom(worldZoom * (d / pinchD)); pinchD = d; }

    }

  }, { passive:false });

  canvas.addEventListener("touchend", function(e){ if(e.touches.length < 2) pinchD = 0; });

  canvas.addEventListener("touchcancel", function(){ pinchD = 0; });

})();



/* Driving touch controls (separate from the walking pad). Same

   pointer-capture hold handling as the walking pad, and — like the

   keyboard — a press now only records held state: the old instant

   +30 speed blip made a tap's strength depend on event timing

   instead of the time-based acceleration in updateCar(). */

document.querySelectorAll("[data-drive]").forEach(function(btn){

  var dir = btn.getAttribute("data-drive");

  bindHoldButton(btn, function(held){

    driveKeys[dir] = held;

    if(held && dir === "up" && isDriving() && !car.engine){ toast("Engine is OFF \u2014 start it with G or the ENGINE button"); sndBad(); }

  });

});

