/* ============================== MENU PAGE ==============================

   The top bar's action buttons and the Audio & Captions / Field Guide

   side panels are MOVED (not duplicated) into the full-screen menu

   page, so the game screen keeps only the canvas, the touch controls

   and the gameplay panels (Objectives / Dialogue; the Notebook,

   Campaign board and Evidence Inventory live on the inventory page —

   see INVENTORY PAGE below). Every moved node keeps its id and its

   already-bound handlers — only its home in the DOM changes. While the

   menu page is open, overlayOpen() reports true, so the game loop holds

   the world exactly as it was; closing the page resumes play unchanged. */

var menuPageEl = document.getElementById("menuPage");

function openMenuPage(){

  if(!menuPageEl || menuPageEl.classList.contains("show")) return;

  /* Drop any held movement keys so Jay doesn't drift on return. */

  keys.up = keys.down = keys.left = keys.right = false;

  driveKeys.up = driveKeys.down = driveKeys.left = driveKeys.right = false;

  menuPageEl.classList.add("show");

  menuPageEl.scrollTop = 0; /* after .show: a display:none element ignores scroll resets */

  document.body.style.overflow = "hidden";

  try{ ensureAudio(); sndClick(); }catch(e){}

  var c = document.getElementById("btnMenuClose"); if(c) c.focus();

}

function closeMenuPage(){

  if(!menuPageEl || !menuPageEl.classList.contains("show")) return;

  menuPageEl.classList.remove("show");

  document.body.style.overflow = "";

  var b = document.getElementById("btnMenu"); if(b) b.focus();

}

(function buildMenuPage(){

  var actions = document.getElementById("menuActions");

  var options = document.getElementById("menuOptions");

  var avSlot = document.getElementById("menuAvSlot");

  var guideSlot = document.getElementById("menuGuideSlot");

  if(!actions || !options) return;

  function move(id, host){ var el = document.getElementById(id); if(el && host) host.appendChild(el); return el; }

  /* MENU section — in brief order, with the two other former top-bar

     game actions (City Map, Return Patrol Car) kept alongside. */

  move("btnTutorial", actions);

  move("btnReplayIntro", actions);

  move("btnMap", actions);

  move("btnReturnCar", actions);

  move("btnReset", actions);

  /* OPTIONS section — Sound toggle, Traffic density, How to Play. */

  move("btnSound", options);

  var trafficLabel = document.querySelector(".traffic-sel");

  if(trafficLabel) options.appendChild(trafficLabel);

  move("btnHelp", options);

  /* The Audio & Captions panel (volumes + captions) is options too. */

  move("avPanel", avSlot);

  /* FIELD GUIDE section — the whole guide panel, unchanged. */

  move("howtoPanel", guideSlot);

  /* The old top-bar button row is now empty chrome — remove it. */

  var row = document.querySelector(".topbar .hbtns");

  if(row && !row.children.length) row.remove();

  var bm = document.getElementById("btnMenu"); if(bm) bm.addEventListener("click", openMenuPage);

  var bc = document.getElementById("btnMenuClose"); if(bc) bc.addEventListener("click", closeMenuPage);

  var bb = document.getElementById("btnMenuBack"); if(bb) bb.addEventListener("click", closeMenuPage);

  /* Replay Intro and a confirmed Reset both start play on the game

     screen, so they close the menu page as they fire. */

  var br = document.getElementById("btnReplayIntro"); if(br) br.addEventListener("click", closeMenuPage);

  var brc = document.getElementById("btnResetConfirm"); if(brc) brc.addEventListener("click", closeMenuPage);

})();



/* ============================== INVENTORY PAGE ==============================

   The Notebook (findings + witness statements), the Campaign board

   and the Evidence Inventory are MOVED (not duplicated) from the side

   column into the full-screen inventory page, so the game screen keeps

   only the canvas, the touch controls and the objective line (prompt

   bar). On portrait phones the Objectives panel joins them here too

   (placeObjectives() above). Every moved node keeps

   its id, and refreshPanels() keeps rendering the real current

   content into it wherever it lives — findings, statements, campaign

   lock state and evidence items are always live. While the page is

   open, overlayOpen() reports true, so the game loop holds the world

   exactly as it was; closing the page resumes play unchanged, exactly

   like the menu page. */

var invPageEl = document.getElementById("invPage");

function openInvPage(){

  if(!invPageEl || invPageEl.classList.contains("show")) return;

  /* Drop any held movement keys so Jay doesn't drift on return. */

  keys.up = keys.down = keys.left = keys.right = false;

  driveKeys.up = driveKeys.down = driveKeys.left = driveKeys.right = false;

  try{ refreshPanels(); }catch(e){}

  invPageEl.classList.add("show");

  invPageEl.scrollTop = 0; /* after .show: a display:none element ignores scroll resets */

  document.body.style.overflow = "hidden";

  try{ ensureAudio(); sndClick(); }catch(e){}

  var c = document.getElementById("btnInvClose"); if(c) c.focus();

}

function closeInvPage(){

  if(!invPageEl || !invPageEl.classList.contains("show")) return;

  invPageEl.classList.remove("show");

  document.body.style.overflow = "";

  var b = document.getElementById("btnInv"); if(b) b.focus();

}

(function buildInvPage(){

  var nbSlot = document.getElementById("invNotebookSlot");

  var campSlot = document.getElementById("invCampSlot");

  var evSlot = document.getElementById("invEvidenceSlot");

  if(!nbSlot || !campSlot || !evSlot) return;

  function move(id, host){ var el = document.getElementById(id); if(el && host) host.appendChild(el); return el; }

  move("nbPanel", nbSlot);      /* Notebook: findings + witness statements */

  /* Assignments have one home: the precinct assignment board. */

  move("evPanel", evSlot);      /* Evidence Inventory */

  var bi = document.getElementById("btnInv"); if(bi) bi.addEventListener("click", openInvPage);

  var bc = document.getElementById("btnInvClose"); if(bc) bc.addEventListener("click", closeInvPage);

  var bb = document.getElementById("btnInvBack"); if(bb) bb.addEventListener("click", closeInvPage);

})();



/* ============================== LOOP / START ==============================

   FLUIDITY PASS (2026-10-14): the simulation is time-based and substepped.

   dt is the real elapsed time (clamped to 100ms so a long stall can never

   teleport anything), split into steps of at most 1/60s, so walking,

   driving, traffic and pedestrians advance by the same amount per real

   second at 30, 60, 120 or 144Hz, and no single step can tunnel through

   a wall or a car. simDt carries the current frame's dt to updateCam()

   (draw calls it without arguments) so camera smoothing is time-based

   too. Frame times are recorded in a ring buffer for ROOKIE.perfStats()

   and the build report — real measurements, not estimates. */

var lastT = 0;

var simDt = 1 / 60;

var perfRing = [], perfLongFrames = 0, perfFramesTotal = 0;

var frameFailure=null,frameFailureCount=0;

function loop(t){

  // Queue the next frame even if a district painter fails during asset decoding.

  requestAnimationFrame(loop);

  if(document.hidden){lastT=0;simDt=0;return;}
/* authoritative connected campaign */ if(window.ROOKIE_MAIN_CITY_ACTIVE&&window.HARBOR?.seamlessCampusV115?.isOpen()&&!window.HARBOR.academy.active()&&!window.HARBOR.outbreak.active()){lastT=0;simDt=0;return;}
  if(window.HARBOR?.seamlessCampusV115?.isOpen() && !window.ROOKIE_JAY?.excluded()){lastT=0;simDt=0;return;}

  try {

  if(!lastT) lastT = t;

  var rawDt = (t - lastT) / 1000;

  lastT = t;

  var dt = Math.max(0, Math.min(0.1, rawDt || 0));

  simDt = dt;

  if(rawDt > 0 && rawDt < 1){

    perfRing.push(rawDt * 1000);

    if(perfRing.length > 600) perfRing.shift();

    perfFramesTotal++;

    if(rawDt * 1000 > 34) perfLongFrames++;

  }

  var anyModal = document.querySelector(".modal-back.show");

  var csOn2 = (typeof csActive !== "undefined" && csActive);

  if(frameFailureCount<3 && !dlgOpen && !overlayOpen() && !anyModal && !csOn2){

    var steps = Math.max(1, Math.min(6, Math.ceil(dt / (1 / 60))));

    var sdt = dt / steps;

    for(var si = 0; si < steps; si++){

      if(isDriving()) updateCar(sdt, t); else movePlayer(sdt);

      if(typeof checkTsPullOver === "function") checkTsPullOver(sdt);

      if(!(typeof tsClosureActive === "function" && tsClosureActive())){

        updateTraffic(sdt);

        updatePeds(sdt);

        pushPlayerFromTraffic();

      }

      /* a substep may have opened a dialogue (traffic stop, exit into a

         scripted spot): stop simulating this frame if so */

      if(dlgOpen) break;

    }

  } else if(isDriving()){ /* paused: hold position, kill speed gently */ car.speed = 0; syncPlayerToCar(); }

  if(typeof updateCutscene === "function") updateCutscene(dt);

  draw(t);

  if(frameFailureCount){frameFailureCount=0;frameFailure=null;var recovered=document.getElementById("worldRecovery");if(recovered)recovered.style.display="none";}

  } catch(error){

    frameFailureCount++;frameFailure=String(error&&error.message||error);

    fadeEl.classList.remove("on");clearHeldInputs();

    if(typeof car!=="undefined")car.speed=0;

    if(frameFailureCount===1)console.error("World frame failed",state.map,error);

    if(frameFailureCount>=3){var card=document.getElementById("worldRecovery");if(!card){card=document.createElement("div");card.id="worldRecovery";card.setAttribute("role","alert");card.style.cssText="position:absolute;inset:20% 8% auto;z-index:40;background:#14233b;color:white;padding:20px;border:2px solid #d1b454;border-radius:12px";card.innerHTML='<p>The scene could not draw. Your saved progress is safe.</p><button id="worldRetry" type="button">Try scene again</button>';document.querySelector(".canvas-wrap").appendChild(card);document.getElementById("worldRetry").onclick=function(){warmGameAssets(state.map);frameFailureCount=0;card.style.display="none";};}card.style.display="block";}

  }

}

refreshPanels();

perfCheckReadiness();

updateLocLabel();

updateDriveUI();

updateCam();

var hereLoc = locById(state.map);

if(state.closed){

  var cmNow = currentMission();

  setDialogue("SGT. BROOKS", campaignDone()

    ? "Welcome back, Detective Jay. The campaign is complete and Harbor City is open \u2014 you're currently at: " + (hereLoc ? hereLoc.name : curMap().name) + ". Talk to me any time to see the campaign summary again."

    : "Welcome back, " + state.rank + " Jay. Case 001 is closed; the campaign continues with Case " + MISSIONS[cmNow].num + " \u2014 " + MISSIONS[cmNow].name + ". You're currently at: " + (hereLoc ? hereLoc.name : curMap().name) + ". Follow the beacon, or check the campaign board in INVENTORY.", "");

} else if(hadSave && findingCount() > 0){

  setDialogue("DISPATCH", "Welcome back, Cadet Jay. Progress restored: " + findingCount() + " of 4 findings in your notebook. You're at: " + (hereLoc ? hereLoc.name : curMap().name) + ". Pick up where you left off.", "");

} else if(hadSave){

  setDialogue("DISPATCH", "Welcome back, Cadet Jay. Your post was saved at: " + (hereLoc ? hereLoc.name : curMap().name) + ". Case 001 waits inside Precinct 9 \u2014 start with the evidence tag in the Evidence Room.", "");

} else if(state.intro && !state.intro.done) {

  /* Fresh campaign: the opening cutscene (started in the cutscene section

     below) takes over from here — no dispatch dialogue competes with it. */

} else {

  try{ if(!localStorage.getItem("rookie-hc-tut-seen")) setTimeout(openTutorial, 400); }catch(e){}

  showLines([

    ["DISPATCH", "Morning, Cadet Jay. Sergeant Brooks has a job for you: evidence drive EV-001 vanished from the Evidence Room at Precinct 9 this morning. New here? Tap TUTORIAL up top — 60 seconds, covers walking, interacting, notebook, map and driving."],

    ["DISPATCH", "Work the station: inspect the evidence tag, check the access computer in Records, interview the witness, and search Intake. Fill your notebook, then report your conclusion to Sergeant Brooks."],

    ["DISPATCH", "Beyond the lobby doors is all of Harbor City \u2014 downtown, Maple Court, the industrial district and the waterfront. Press M any time for the city map. Move with WASD / arrow keys / the pad \u2014 interact with E or the round INTERACT button."]

  ], null);

}

requestAnimationFrame(loop);



/* ================= FIDELITY PASS — MATCHING THE REFERENCE BOARDS =================

   Generated sprite-sheet test (run before this pass): the image pipeline

   returned a 1600x1600 RGB sheet with NO alpha channel, inconsistent frame

   sizes/positions and side-profile views mixed into a top-down set — it

   cannot be sliced into transparent, consistently-scaled animation frames,

   so generated sheets are NOT used. Everything below is hand-drawn

   procedural pixel art, rebuilt to the boards' actual art direction:

   - palette: warm terracotta brick, cream stone trim, teal awnings/roofs,

     lush saturated greens, sun-bleached concrete, bright teal water

   - buildings are ROOF-DOMINANT top-down like the boards (flat gravel roofs

     with parapets, AC units, vents, skylights; pitched shingle roofs on

     houses), with only a short south facade strip carrying windows,

     flower boxes, teal striped awnings, hanging signs and doors

   - characters are chibi like the boards (large head, short legs); Jay has

     dark spiky hair and a gold badge, fellow officers keep navy caps

   - Unit 9 is the boards' overhead car: navy body, white roof panel with

     its unit number, red/blue roof light bar — rotated whole for E/W

   These are function-declaration overrides: they replace the earlier

   renderers for every frame. Gameplay, collision and saves are untouched. */

function warmGroundColor(c){

  var map = {

    "#79a862":"#6fb457", "#8aa873":"#74b85e", "#7fae6a":"#6fb457", "#86a860":"#6fae52",

    "#8f8a7d":"#9a927f", "#b9bec4":"#d9d0be", "#c9cdd2":"#ded6c6", "#3d4148":"#45484f",

    "#43474e":"#4a4c50", "#c2b8a4":"#dccfb2", "#a9c48d":"#a8cc8a", "#9cc184":"#8fc573",

    "#b39b78":"#c2a878", "#a08c68":"#b09a74", "#9d988c":"#aba28f", "#a9a49a":"#cfc6b2",

    "#2e6da8":"#1f8fa8"

  };

  return map[(c || "").toLowerCase()] || c;

}

function boardAC(x, y, w, seed){

  pxRect(x+2, y+3, w, 12, "rgba(10,16,26,.22)");

  pxRect(x, y, w, 12, "#8f8c85"); pxRect(x, y, w, 3, "#b3b0a8");

  ctx.strokeStyle="#5d5a53"; ctx.lineWidth=2;

  ctx.beginPath(); ctx.arc(x+w/2, y+6, 4, 0, 7); ctx.stroke();

  pxRect(x+w/2-1, y+2, 2, 8, "#5d5a53");

  if(seed > 0.5){ pxRect(x+3, y+14, 3, 3, "#6e6a61"); }

}

function boardVent(x, y, seed){

  pxRect(x, y, 10, 8, "#7d7a72"); pxRect(x-1, y-3, 12, 3, "#a3a099");

  pxRect(x+3, y+2, 4, 2, "rgba(0,0,0,.3)");

}

function flowerBox(x, y, w, seed){

  pxRect(x, y, w, 5, "#6e4630");

  ctx.fillStyle="#2e7d4f"; ctx.fillRect(x+1, y-2, w-2, 3);

  for(var fx=x+2; fx<x+w-2; fx+=5){

    ctx.fillStyle = ["#e87a9e","#d94f4f","#f2c14e"][(pxHash(fx, seed*91)*3)|0];

    ctx.fillRect(fx, y-4, 3, 3);

  }

}

function drawPlazaGround(t){

  /* lush lawn bands with flower speckle */

  speckleRect({x:0,y:0,w:1500,h:296}, ["#5d9a48","#8fd07a","#6fb457"], 26, .55);

  speckleRect({x:0,y:863,w:1500,h:137}, ["#5d9a48","#8fd07a","#6fb457"], 26, .55);

  speckleRect({x:0,y:296,w:116,h:344}, ["#5d9a48","#8fd07a"], 26, .5);

  speckleRect({x:836,y:296,w:110,h:344}, ["#5d9a48","#8fd07a"], 26, .5);

  ctx.fillStyle="#e87a9e";

  for(var fi=0; fi<26; fi++){ var fx2=pxHash(fi,3)*1480, fy2=pxHash(fi,7)*270; ctx.fillRect(fx2, fy2, 3, 3); }

  ctx.fillStyle="rgba(255,255,255,.05)";

  for(var mx=0; mx<1500; mx+=92){ if((mx/92)%2===0) ctx.fillRect(mx, 863, 92, 137); }

  /* sun-bleached concrete plaza + station path */

  var conc = [{x:560,y:544,w:480,h:180},{x:744,y:544,w:112,h:536}];

  conc.forEach(function(r){

    speckleRect(r, ["#c9bda6","#e6dcc8","#b3a78d"], 24, .55);

    ctx.strokeStyle="rgba(96,84,62,.4)"; ctx.lineWidth=2;

    for(var jx=r.x+70; jx<r.x+r.w; jx+=70){ ctx.beginPath(); ctx.moveTo(jx, r.y+3); ctx.lineTo(jx, r.y+r.h-3); ctx.stroke(); }

    for(var jy=r.y+66; jy<r.y+r.h; jy+=66){ ctx.beginPath(); ctx.moveTo(r.x+3, jy); ctx.lineTo(r.x+r.w-3, jy); ctx.stroke(); }

    ctx.fillStyle="rgba(255,255,255,.4)"; ctx.fillRect(r.x, r.y, r.w, 3);

  });

  /* parking asphalt: warm dark, speckle, cracks, oil, disabled bay paint */

  var park = {x:1180,y:300,w:580,h:780};

  speckleRect(park, ["#3a3d42","#54575c","#2e3034"], 22, .6);

  ctx.strokeStyle="rgba(12,14,18,.5)"; ctx.lineWidth=1.6;

  for(var ci=0; ci<7; ci++){

    var cx0=park.x+30+pxHash(ci,7)*(park.w-90), cy0=park.y+26+pxHash(ci,13)*(park.h-60);

    ctx.beginPath(); ctx.moveTo(cx0, cy0); ctx.lineTo(cx0+14+pxHash(ci,3)*16, cy0+5); ctx.lineTo(cx0+26+pxHash(ci,5)*14, cy0+1); ctx.stroke();

  }

  ctx.fillStyle="rgba(8,10,14,.20)";

  [[1290,520],[1520,880],[1690,480]].forEach(function(o){ ctx.beginPath(); ctx.ellipse(o[0], o[1], 26, 10, 0, 0, 7); ctx.fill(); });

  pxRect(1680, 404, 34, 26, "rgba(43,107,176,.55)");

  ctx.fillStyle="rgba(255,255,255,.85)"; ctx.font="700 17px 'Barlow', sans-serif"; ctx.textAlign="center"; ctx.fillText("\u267F", 1697, 424);

  /* Harbor Ave asphalt + warm concrete sidewalks */

  var road = {x:0,y:1120,w:1920,h:128};

  speckleRect(road, ["#3a3d42","#54575c","#2e3034"], 22, .6);

  ctx.fillStyle="rgba(246,240,226,.8)"; ctx.fillRect(0, 1124, 1920, 4); ctx.fillRect(0, 1240, 1920, 4);

  ctx.fillStyle="#5a6068"; ctx.beginPath(); ctx.arc(430, 1184, 13, 0, 7); ctx.fill();

  ctx.fillStyle="#454a52"; ctx.beginPath(); ctx.arc(430, 1184, 9, 0, 7); ctx.fill();

  [{x:0,y:1080,w:1920,h:40},{x:0,y:1248,w:1920,h:32}].forEach(function(r){

    speckleRect(r, ["#c9bda6","#e6dcc8"], 24, .5);

    ctx.strokeStyle="rgba(96,84,62,.4)"; ctx.lineWidth=2;

    for(var jx2=46; jx2<r.x+r.w; jx2+=62){ ctx.beginPath(); ctx.moveTo(jx2, r.y+3); ctx.lineTo(jx2, r.y+r.h-3); ctx.stroke(); }

    ctx.fillStyle="rgba(255,255,255,.45)"; ctx.fillRect(r.x, r.y, r.w, 3);

    ctx.fillStyle="rgba(80,66,44,.3)"; ctx.fillRect(r.x, r.y+r.h-3, r.w, 3);

  });

}

function drawCityGround(t){

  var m = curMap();

  var gx0=Math.max(0, Math.floor(cam.x/44)*44), gx1=Math.min(m.w, cam.x+viewW()+44);

  var gy0=Math.max(0, Math.floor(cam.y/44)*44), gy1=Math.min(m.h, cam.y+viewH()+44);

  for(var sx=gx0; sx<gx1; sx+=44){

    for(var sy=gy0; sy<gy1; sy+=44){

      var hh=pxHash(sx, sy);

      if(hh < 0.45) continue;

      ctx.fillStyle = hh > 0.8 ? "rgba(255,255,220,.07)" : "rgba(24,60,20,.08)";

      ctx.fillRect(sx+(hh*977%30), sy+(hh*613%30), 6, 3);

      if(hh > 0.62) ctx.fillRect(sx+(hh*389%34), sy+(hh*521%36), 4, 2);

      if(hh > 0.93){ ctx.fillStyle="#e87a9e"; ctx.fillRect(sx+(hh*211%36), sy+(hh*307%36), 3, 3); }

      if(hh > 0.88 && hh <= 0.93){ ctx.fillStyle="#f2c14e"; ctx.fillRect(sx+(hh*211%36), sy+(hh*307%36), 3, 3); }

    }

  }

  (m.ground || []).forEach(function(g){

    if(g.x+g.w < cam.x-10 || g.x > cam.x+viewW()+10 || g.y+g.h < cam.y-10 || g.y > cam.y+viewH()+10) return;

    var c=(g.c || "").toLowerCase();

    if(c==="#3d4148" || c==="#43474e"){

      speckleRect(g, ["#33373d","#54575c","#2b2f35"], 24, .5);

      ctx.fillStyle="rgba(246,240,226,.45)";

      if(g.w >= g.h){ ctx.fillRect(g.x, g.y+2, g.w, 2); ctx.fillRect(g.x, g.y+g.h-4, g.w, 2); }

    } else if(c==="#b9bec4" || c==="#a9a49a" || c==="#c9cdd2"){

      speckleRect(g, ["#c9bda6","#e6dcc8","#b3a78d"], 26, .45);

      ctx.strokeStyle="rgba(96,84,62,.35)"; ctx.lineWidth=2;

      if(g.w >= g.h && g.h <= 60){ for(var jx=g.x+62; jx<g.x+g.w; jx+=62){ ctx.beginPath(); ctx.moveTo(jx, g.y+3); ctx.lineTo(jx, g.y+g.h-3); ctx.stroke(); } }

      if(g.h > g.w && g.w <= 60){ for(var jy=g.y+62; jy<g.y+g.h; jy+=62){ ctx.beginPath(); ctx.moveTo(g.x+3, jy); ctx.lineTo(g.x+g.w-3, jy); ctx.stroke(); } }

      ctx.fillStyle="rgba(255,255,255,.4)"; ctx.fillRect(g.x, g.y, g.w, 2);

    } else if(c==="#b39b78" || c==="#a08c68"){

      ctx.strokeStyle="rgba(70,50,26,.45)"; ctx.lineWidth=2;

      for(var px2=g.x+22; px2<g.x+g.w; px2+=22){ ctx.beginPath(); ctx.moveTo(px2, g.y+2); ctx.lineTo(px2, g.y+g.h-2); ctx.stroke(); }

      speckleRect(g, ["#8a6f4c","#d8bc8e"], 28, .4);

      ctx.fillStyle="rgba(60,42,20,.5)";

      for(var nx2=g.x+8; nx2<g.x+g.w; nx2+=44){ ctx.fillRect(nx2, g.y+8, 3, 3); ctx.fillRect(nx2+18, g.y+g.h-11, 3, 3); }

    } else if(c==="#c2b8a4" || c==="#9d988c" || c==="#a9c48d" || c==="#9cc184"){

      speckleRect(g, ["rgba(0,0,0,.10)","rgba(255,255,255,.12)"], 28, .5);

      if(c==="#9cc184" || c==="#a9c48d"){

        ctx.fillStyle="rgba(255,255,255,.05)";

        for(var mx2=g.x; mx2<g.x+g.w; mx2+=84){ if(((mx2/84)|0)%2===0) ctx.fillRect(mx2, g.y, 84, g.h); }

      }

      if(c==="#c2b8a4"){ speckleRect(g, ["#c9bda6","#e6dcc8"], 30, .35); }

    }

  });

  if(m.water || state.map === "southbay"){

    ctx.fillStyle="rgba(255,255,255,.4)";

    for(var wx2=gx0; wx2<gx1; wx2+=58){

      for(var wy2=gy0; wy2<gy1; wy2+=46){

        var inWater=false;

        (m.ground || []).forEach(function(g){ if((g.c||"").toLowerCase()==="#2e6da8" && wx2>g.x && wx2<g.x+g.w && wy2>g.y && wy2<g.y+g.h) inWater=true; });

        if(!inWater) continue;

        var tw2=pxHash(wx2, wy2);

        if(Math.sin(t/700 + tw2*9) > 0.55) ctx.fillRect(wx2+tw2*22, wy2+tw2*14, 9, 2);

      }

    }

  }

}

function drawPrecinctBldg(d, t){

  ctx.save();

  var fade = (!isDriving() && player.y + player.h < d.y + 58 && player.x > d.x - 46 && player.x < d.x + d.w + 46) ? 0.42 : 1;

  ctx.globalAlpha = fade;

  var FH = 58, roofBot = d.y + d.h - FH;

  pxRect(d.x + 6, d.y + d.h - 2, d.w, 12, "rgba(10,16,26,.28)");

  /* ---- flat roof (dominant, like the top-down board): warm grey gravel,

     stone parapet, AC units, vents, skylights, hatch, antenna ---- */

  pxRect(d.x, d.y, d.w, roofBot - d.y, "#a49d90");

  speckleRect({x:d.x+8, y:d.y+8, w:d.w-16, h:roofBot-d.y-16}, ["#98917f","#bcb5a4","#8a8474"], 26, .5);

  ctx.globalAlpha = fade;

  pxRect(d.x, d.y, d.w, 9, "#ede0c8"); pxRect(d.x, roofBot - 9, d.w, 9, "#ede0c8");

  pxRect(d.x, d.y, 9, roofBot - d.y, "#ede0c8"); pxRect(d.x + d.w - 9, d.y, 9, roofBot - d.y, "#ede0c8");

  pxRect(d.x, d.y + 9, d.w, 3, "rgba(90,70,40,.35)"); pxRect(d.x, roofBot - 12, d.w, 3, "rgba(90,70,40,.35)");

  boardAC(d.x + 120, d.y + 34, 52, .2); boardAC(d.x + 330, d.y + 58, 44, .7); boardAC(d.x + d.w - 260, d.y + 30, 58, .4); boardAC(d.x + d.w - 150, d.y + 64, 40, .9);

  boardVent(d.x + 520, d.y + 40, .3); boardVent(d.x + 700, d.y + 66, .6); boardVent(d.x + 230, d.y + 74, .8);

  [240, 880].forEach(function(off){

    pxRect(d.x + off, d.y + 96, 64, 22, "#5d5648"); pxRect(d.x + off + 3, d.y + 99, 58, 16, "#79c4ce"); pxRect(d.x + off + 3, d.y + 99, 58, 6, "#bfe6ec");

  });

  pxRect(d.x + 430, d.y + 92, 46, 26, "#7d7a72"); pxRect(d.x + 430, d.y + 92, 46, 4, "#a3a099");

  pxRect(d.x + d.w - 60, d.y + 18, 5, 30, "#57687f");

  var blink = (Math.sin(t / 420) > 0.4);

  pxRect(d.x + d.w - 62, d.y + 14, 9, 5, blink ? "#ff5040" : "#7a2a24");

  /* ---- south facade: terracotta brick, cream stone trim ---- */

  pxRect(d.x, roofBot, d.w, FH, "#c06848");

  for(var ry = roofBot + 6; ry < d.y + d.h - 4; ry += 6){ ctx.fillStyle = "rgba(90,40,20,.16)"; ctx.fillRect(d.x, ry, d.w, 1.6); }

  speckleRect({x:d.x, y:roofBot + 2, w:d.w, h:FH - 4}, ["#a85438", "#d98a66", "#9a4e32"], 30, .5);

  ctx.globalAlpha = fade;

  pxRect(d.x, roofBot, d.w, 6, "#ede0c8");

  pxRect(d.x, d.y + d.h - 10, d.w, 10, "#8a4630"); pxRect(d.x, d.y + d.h - 12, d.w, 2.4, "#ede0c8");

  pxRect(d.x, roofBot, 9, FH, "#ede0c8"); pxRect(d.x + d.w - 9, roofBot, 9, FH, "#ede0c8");

  var dx = d.doorX;

  for(var wx = d.x + 40; wx < d.x + d.w - 60; wx += 86){

    if(Math.abs(wx + 18 - dx) < 120) continue;

    var lit = pxHash(wx, 31) > 0.7;

    pxRect(wx - 3, roofBot + 14, 42, 30, "#ede0c8");

    pxRect(wx, roofBot + 17, 36, 24, lit ? "#f2c96b" : "#3d5a66");

    pxRect(wx, roofBot + 17, 36, 9, lit ? "#ffd98a" : "#79a8b5");

    pxRect(wx + 16, roofBot + 17, 4, 24, "#ede0c8"); pxRect(wx, roofBot + 27, 36, 3, "#ede0c8");

    flowerBox(wx - 2, roofBot + 46, 40, wx);

  }

  /* ---- entrance: navy HARBOR CITY POLICE sign, striped awning, glass doors ---- */

  pxRect(dx - 105, roofBot - 4, 210, 24, "#162f52"); pxRect(dx - 105, roofBot - 4, 210, 3, "#c9a227");

  ctx.fillStyle = "#c9a227"; ctx.beginPath(); ctx.arc(dx - 84, roofBot + 8, 7, 0, 7); ctx.fill();

  ctx.fillStyle = "#162f52"; ctx.font = "700 8px 'Barlow Condensed', sans-serif"; ctx.textAlign = "center"; ctx.fillText("PD", dx - 84, roofBot + 11);

  ctx.fillStyle = "#ffffff"; ctx.font = "700 15px 'Barlow Condensed', sans-serif";

  ctx.fillText("HARBOR CITY POLICE", dx + 12, roofBot + 9);

  ctx.fillStyle = "#e8c95a"; ctx.font = "700 8.5px 'Barlow Condensed', sans-serif";

  ctx.fillText("P R E C I N C T   9", dx + 12, roofBot + 18);

  var awW = 120;

  for(var asx = 0; asx < awW; asx += 12){ pxRect(dx - awW/2 + asx, roofBot + 20, 6, 9, "#5b84ae"); pxRect(dx - awW/2 + asx + 6, roofBot + 20, 6, 9, "#eef2ec"); }

  pxRect(dx - awW/2, roofBot + 29, awW, 2.6, "rgba(10,16,26,.35)");

  pxRect(dx - 24, roofBot + 31, 48, FH - 31, "#22314d");

  pxRect(dx - 20, roofBot + 34, 17, FH - 37, "#79a8b5"); pxRect(dx + 3, roofBot + 34, 17, FH - 37, "#79a8b5");

  pxRect(dx - 20, roofBot + 34, 17, 12, "#bfe6ec"); pxRect(dx + 3, roofBot + 34, 17, 12, "#bfe6ec");

  pxRect(dx - 2, roofBot + 31, 4, FH - 31, "#162f52");

  pxRect(dx - 7, d.y + d.h - 16, 3, 7, "#e8c95a"); pxRect(dx + 4, d.y + d.h - 16, 3, 7, "#e8c95a");

  pxRect(dx - 30, d.y + d.h, 60, 4, "#cfc6b2"); pxRect(dx - 38, d.y + d.h + 4, 76, 4, "#bcb29a");

  var glow = 0.16 + 0.05 * Math.sin(t / 700);

  [-72, 66].forEach(function(off){

    ctx.fillStyle = "rgba(255,220,130," + glow.toFixed(3) + ")";

    ctx.beginPath(); ctx.arc(dx + off, roofBot + 36, 12, 0, 7); ctx.fill();

    pxRect(dx + off - 3, roofBot + 32, 6, 9, "#ffe9a3"); pxRect(dx + off - 4, roofBot + 30, 8, 3, "#31435f");

  });

  /* continuous flower bed along the facade (board density), gap at the door */

  [[d.x + 14, dx - 108], [dx + 108, d.x + d.w - 14]].forEach(function(seg){

    if(seg[1] - seg[0] < 30) return;

    pxRect(seg[0], d.y + d.h - 9, seg[1] - seg[0], 9, "#5e4630");

    for(var fbx = seg[0] + 4; fbx < seg[1] - 4; fbx += 10){

      ctx.fillStyle = pxHash(fbx, 5) > 0.5 ? "#3e8a4c" : "#2e7d4f";

      ctx.beginPath(); ctx.arc(fbx + 3, d.y + d.h - 6, 6, 0, 7); ctx.fill();

      ctx.fillStyle = ["#e87a9e", "#d94f4f", "#f2c14e", "#ffffff"][(pxHash(fbx, 9) * 4 | 0) % 4];

      ctx.fillRect(fbx + 1, d.y + d.h - 11, 3, 3); ctx.fillRect(fbx + 6, d.y + d.h - 5, 3, 3);

    }

  });

  ctx.restore();

}

function drawPixelBuilding(d, t){

  var doorX = (typeof d.doorX === "number") ? d.doorX : d.x + d.w / 2;

  var seed = pxHash(d.x, d.y);

  var FH = d.t === "house" ? 42 : (d.t === "shed" ? 38 : 50);

  var roofBot = d.y + d.h - FH;

  ctx.fillStyle = "rgba(0,0,0,.20)"; rr(d.x + 5, d.y + d.h - 3, d.w, 10, 5); ctx.fill();

  /* ================= ROOF (dominant, top-down board style) ================= */

  if(d.t === "house"){

    pxRect(d.x - 6, d.y - 8, d.w + 12, roofBot - d.y + 14, d.roof);

    var midY = d.y + (roofBot - d.y) / 2;

    ctx.fillStyle = "rgba(255,255,255,.13)"; ctx.fillRect(d.x - 6, d.y - 8, d.w + 12, midY - d.y);

    ctx.fillStyle = "rgba(10,16,26,.16)"; ctx.fillRect(d.x - 6, midY + 6, d.w + 12, roofBot - midY);

    ctx.fillStyle = "rgba(10,16,26,.22)";

    for(var shy = d.y; shy < roofBot; shy += 9) ctx.fillRect(d.x - 4, shy, d.w + 8, 1.8);

    for(var shx = d.x + 6; shx < d.x + d.w; shx += 16) ctx.fillRect(shx, d.y - 6, 1.8, roofBot - d.y + 10);

    pxRect(d.x - 8, midY - 3, d.w + 16, 6, "rgba(255,255,255,.28)");

    var chx = d.x + 26 + seed * (d.w - 80);

    pxRect(chx, d.y + 8, 16, 20, "#9a4e32"); pxRect(chx - 2, d.y + 5, 20, 4, "#ede0c8");

    if(Math.sin(t / 800 + d.x) > 0.2){ ctx.fillStyle = "rgba(246,240,226,.35)"; ctx.beginPath(); ctx.arc(chx + 8, d.y - ((t / 60 + d.x) % 14), 4 + ((t / 60 + d.x) % 14) * 0.3, 0, 7); ctx.fill(); }

    boardVent(d.x + d.w - 42, midY + 12, seed);

  } else if(d.t === "shed"){

    pxRect(d.x - 4, d.y - 6, d.w + 8, roofBot - d.y + 10, "#8a8474");

    ctx.fillStyle = "rgba(255,255,255,.10)"; ctx.fillRect(d.x - 4, d.y - 6, d.w + 8, 8);

    ctx.fillStyle = "rgba(10,16,26,.20)";

    for(var cx9 = d.x + 4; cx9 < d.x + d.w; cx9 += 11) ctx.fillRect(cx9, d.y - 4, 2, roofBot - d.y + 6);

    speckleRect({x:d.x, y:d.y, w:d.w, h:roofBot - d.y}, ["#a85f3c", "#7d7468"], 44, .3);

    boardVent(d.x + d.w - 36, d.y + 16, seed);

  } else {

    var tealRoof = seed > 0.76;

    pxRect(d.x, d.y, d.w, roofBot - d.y, tealRoof ? "#2e8c86" : "#a49d90");

    if(tealRoof){

      ctx.fillStyle = "rgba(255,255,255,.10)";

      for(var tp = d.x + 14; tp < d.x + d.w; tp += 22) ctx.fillRect(tp, d.y + 4, 2.4, roofBot - d.y - 8);

      speckleRect({x:d.x + 6, y:d.y + 6, w:d.w - 12, h:roofBot - d.y - 12}, ["#25746f", "#3aa99f"], 34, .4);

    } else {

      speckleRect({x:d.x + 8, y:d.y + 8, w:d.w - 16, h:roofBot - d.y - 16}, ["#98917f", "#bcb5a4", "#8a8474"], 26, .5);

    }

    pxRect(d.x, d.y, d.w, 7, "#ede0c8"); pxRect(d.x, roofBot - 7, d.w, 7, "#ede0c8");

    pxRect(d.x, d.y, 7, roofBot - d.y, "#ede0c8"); pxRect(d.x + d.w - 7, d.y, 7, roofBot - d.y, "#ede0c8");

    pxRect(d.x, d.y + 7, d.w, 2.4, "rgba(90,70,40,.3)"); pxRect(d.x, roofBot - 10, d.w, 2.4, "rgba(90,70,40,.3)");

    boardAC(d.x + 18 + seed * 30, d.y + 18, 40 + seed * 14, seed);

    if(d.w > 240) boardAC(d.x + d.w - 84 - seed * 20, d.y + 22, 44, seed + .3);

    if(d.w > 380) boardAC(d.x + d.w / 2 - 20, d.y + roofBot - d.y - 44, 42, seed + .6);

    boardVent(d.x + d.w - 40, d.y + roofBot - d.y - 34, seed);

    if(seed > 0.3){ pxRect(d.x + 60 + seed * 60, d.y + 20, 52, 18, "#5d5648"); pxRect(d.x + 63 + seed * 60, d.y + 23, 46, 12, "#79c4ce"); }

    if(seed > 0.55){ pxRect(d.x + d.w - 130, d.y + 16, 34, 22, "#7d7a72"); pxRect(d.x + d.w - 130, d.y + 16, 34, 4, "#a3a099"); }

  }

  /* ================= FACADE (short south strip) ================= */

  if(d.t === "bldg"){

    pxRect(d.x, roofBot, d.w, FH, "#c06848");

    for(var ry2 = roofBot + 6; ry2 < d.y + d.h - 4; ry2 += 6){ ctx.fillStyle = "rgba(90,40,20,.15)"; ctx.fillRect(d.x, ry2, d.w, 1.6); }

    speckleRect({x:d.x, y:roofBot + 2, w:d.w, h:FH - 4}, ["#a85438", "#d98a66"], 32, .45);

    pxRect(d.x, roofBot, d.w, 5, "#ede0c8"); pxRect(d.x, roofBot, 7, FH, "#ede0c8"); pxRect(d.x + d.w - 7, roofBot, 7, FH, "#ede0c8");

    pxRect(d.x, d.y + d.h - 8, d.w, 8, "#8a4630");

  } else if(d.t === "house"){

    pxRect(d.x, roofBot, d.w, FH, d.c);

    ctx.fillStyle = "rgba(255,255,255,.14)";

    for(var sy3 = roofBot + 7; sy3 < d.y + d.h - 3; sy3 += 7) ctx.fillRect(d.x, sy3, d.w, 1.6);

    pxRect(d.x, roofBot, d.w, 5, "#ede0c8"); pxRect(d.x, roofBot, 6, FH, "#ede0c8"); pxRect(d.x + d.w - 6, roofBot, 6, FH, "#ede0c8");

    pxRect(d.x, d.y + d.h - 7, d.w, 7, "rgba(10,16,26,.20)");

  } else {

    pxRect(d.x, roofBot, d.w, FH, "#7a5c40");

    ctx.fillStyle = "rgba(0,0,0,.20)";

    for(var px9 = d.x + 9; px9 < d.x + d.w; px9 += 11) ctx.fillRect(px9, roofBot + 2, 1.8, FH - 4);

    pxRect(d.x, roofBot, d.w, 4, "#5e4630"); pxRect(d.x, d.y + d.h - 6, d.w, 6, "rgba(0,0,0,.25)");

  }

  /* windows on the facade, with flower boxes */

  var cols = Math.max(2, Math.floor(d.w / 58));

  for(var wi = 0; wi < cols; wi++){

    var wx = d.x + 15 + wi * ((d.w - 30) / Math.max(1, cols));

    if(Math.abs(wx + 11 - doorX) <= 34) continue;

    var lit = pxHash(wx, d.y) > 0.66;

    pxRect(wx - 2, roofBot + 12, 26, 24, "#ede0c8");

    pxRect(wx, roofBot + 14, 22, 20, lit ? "#f2c96b" : "#3d5a66");

    pxRect(wx, roofBot + 14, 22, 8, lit ? "#ffd98a" : "#79a8b5");

    pxRect(wx + 10, roofBot + 14, 2, 20, "#ede0c8"); pxRect(wx, roofBot + 23, 22, 2, "#ede0c8");

    if(d.t !== "shed") flowerBox(wx - 2, roofBot + 38, 26, wx);

  }

  /* TEAL striped shop awning (the boards' signature) over door + frontage */

  if(d.t === "bldg" && d.sign){

    var aw = Math.min(150, d.w - 26), awY = d.y + d.h - 34;

    for(var asx2 = 0; asx2 < aw; asx2 += 12){ pxRect(doorX - aw / 2 + asx2, awY, 6, 10, "#1e7a74"); pxRect(doorX - aw / 2 + asx2 + 6, awY, 6, 10, "#eef2ec"); }

    pxRect(doorX - aw / 2, awY + 10, aw, 2.6, "rgba(10,16,26,.32)");

    for(var sc = 0; sc < aw; sc += 12) pxRect(doorX - aw / 2 + sc + 2, awY + 12, 3, 2, "#145a56");

  }

  /* door: stone frame, glass top, gold knob, lit step */

  pxRect(doorX - 14, d.y + d.h - 38, 28, 38, "#ede0c8");

  pxRect(doorX - 11, d.y + d.h - 35, 22, 35, d.t === "shed" ? "#4c3a26" : "#2c2118");

  pxRect(doorX - 8, d.y + d.h - 32, 16, 13, "#79a8b5"); pxRect(doorX - 8, d.y + d.h - 32, 16, 5, "#bfe6ec");

  pxRect(doorX - 8, d.y + d.h - 15, 16, 12, "rgba(0,0,0,.25)");

  pxRect(doorX + 5, d.y + d.h - 18, 3.4, 3.4, "#e8c95a");

  pxRect(doorX - 17, d.y + d.h - 1, 34, 3.4, "#cfc6b2");

  ctx.fillStyle = "rgba(232,201,90,.9)"; ctx.fillRect(doorX - 14, d.y + d.h - 1, 28, 2.6);

  /* hanging sign perpendicular beside the door */

  if(d.sign){

    pxRect(doorX + 18, d.y + d.h - 42, 8, 2.4, "#31435f");

    pxRect(doorX + 22, d.y + d.h - 40, 20, 17, "#162f52"); pxRect(doorX + 22, d.y + d.h - 40, 20, 2.6, "#c9a227");

    ctx.fillStyle = "#fff"; ctx.font = "700 11px 'Barlow', sans-serif"; ctx.textAlign = "center";

    ctx.fillText(d.sign, doorX + 32, d.y + d.h - 27);

  }

  if(d.tower){

    ctx.fillStyle = "#c06848"; ctx.fillRect(doorX - 24, d.y + 6, 48, 44);

    speckleRect({x:doorX - 24, y:d.y + 6, w:48, h:44}, ["#a85438", "#d98a66"], 14, .5);

    ctx.fillStyle = "#37424c"; ctx.beginPath(); ctx.moveTo(doorX - 30, d.y + 8); ctx.lineTo(doorX, d.y - 22); ctx.lineTo(doorX + 30, d.y + 8); ctx.closePath(); ctx.fill();

    ctx.fillStyle = "#ede0c8"; ctx.beginPath(); ctx.arc(doorX, d.y + 28, 12, 0, 7); ctx.fill();

    ctx.strokeStyle = "#162f52"; ctx.lineWidth = 2;

    ctx.beginPath(); ctx.moveTo(doorX, d.y + 28); ctx.lineTo(doorX, d.y + 20); ctx.stroke();

    ctx.beginPath(); ctx.moveTo(doorX, d.y + 28); ctx.lineTo(doorX + 6, d.y + 31); ctx.stroke();

    ctx.strokeStyle = "#c9a227"; ctx.lineWidth = 1.6; ctx.beginPath(); ctx.arc(doorX, d.y + 28, 12, 0, 7); ctx.stroke();

  }

  labelPill(d.label, d.x + d.w / 2, d.y + 4, 13);

}

/* ---- ground shadow for characters: a broad soft radial-gradient

   ellipse plus a denser contact core right under the feet, offset

   slightly down-right (light comes from the upper-left). Deliberately

   strong — dark and wide enough to read at a glance at normal play

   resolution on grass, plaza, asphalt, sidewalk and interior floors,

   so characters sit on the ground instead of floating. Drawn before

   the sprite body in every character renderer, so it always sits

   beneath the character in the depth pass and tracks it frame to

   frame. Purely visual. ---- */

/* Shared foot contact texture. Build once; preserve the original two-gradient profile. */

var charShadowTexture=null;

function charGroundShadow(cx, cy){

  if(!charShadowTexture){

    charShadowTexture=document.createElement('canvas');

    charShadowTexture.width=60;charShadowTexture.height=28;

    var g=charShadowTexture.getContext('2d');

    g.translate(30,14);g.scale(1,.38);

    var rim=g.createRadialGradient(0,0,1,0,0,27);

    rim.addColorStop(0,'rgba(5,8,14,.68)');rim.addColorStop(.5,'rgba(5,8,14,.5)');

    rim.addColorStop(.8,'rgba(5,8,14,.22)');rim.addColorStop(1,'rgba(5,8,14,0)');

    g.fillStyle=rim;g.beginPath();g.arc(0,0,27,0,7);g.fill();

    var core=g.createRadialGradient(0,0,.5,0,0,12.5);

    core.addColorStop(0,'rgba(5,8,14,.55)');core.addColorStop(1,'rgba(5,8,14,0)');

    g.fillStyle=core;g.beginPath();g.arc(0,0,12.5,0,7);g.fill();

  }

  ctx.drawImage(charShadowTexture,cx-29,cy-12);

}

/* ---- chibi character renderer (boards' proportions: big head, short legs) ---- */

function chibiSprite(o){

  ctx.save();

  ctx.translate(Math.round(o.x), Math.round(o.y + (o.bob || 0)));

  charGroundShadow(0, -(o.bob || 0)); /* shadow stays on the ground line while the body bobs */

  function R(u, v, w, h, c){ ctx.fillStyle = c; ctx.fillRect(u * 2, v * 2, w * 2, h * 2); }

  var frame = (typeof o.phase === "number") ? (Math.floor(o.phase * 0.85) % 4) : 0;

  var stepL = (frame === 1) ? -1 : (frame === 3) ? 1 : 0;

  var liftL = (frame === 1 || frame === 3) ? 1 : 0;

  var swing = (frame === 1) ? 1 : (frame === 3) ? -1 : 0;

  if(o.dress){

    R(-7, -10, 14, 4, o.shirt);

    R(-4 + stepL, -6, 3, 5 - liftL, o.skin); R(1 - stepL, -6, 3, 5 - (1 - liftL), o.skin);

    R(-4 + stepL, -2 - liftL, 3, 2, "#3a2c20"); R(1 - stepL, -2 - (1 - liftL), 3, 2, "#3a2c20");

  } else {

    R(-5 + stepL, -7, 4, 6 - liftL, o.pants); R(1 - stepL, -7, 4, 6 - (1 - liftL), o.pants);

    R(-5 + stepL, -2 - liftL, 4, 2, "#10141d"); R(1 - stepL, -2 - (1 - liftL), 4, 2, "#10141d");

  }

  R(-10, -18 + swing, 3, 9, o.shirt); R(7, -18 - swing, 3, 9, o.shirt);

  R(-10, -11 + swing, 3, 2, o.skin); R(7, -11 - swing, 3, 2, o.skin);

  R(-7, -19, 14, o.dress ? 10 : 12, o.shirt);

  R(-7, -19, 14, 2, o.shade);

  if(!o.dress){ R(-7, -9, 14, 2, "#141a26"); R(-1, -9, 2, 2, o.police ? "#e8c95a" : "#8a939e"); }

  if(o.police && o.dir === "down"){ R(3, -16, 2, 2, "#e8c95a"); R(-1, -19, 2, 5, "#0e2140"); }

  if(o.police && o.dir === "left") R(-7, -16, 2, 2, "#e8c95a");

  if(o.police && o.dir === "right") R(5, -16, 2, 2, "#e8c95a");

  if(o.police && o.dir === "up") R(-4, -14, 8, 2, "#e8c95a");

  /* big chibi head */

  R(-6, -30, 12, 11, o.skin);

  R(-7, -26, 1, 4, o.skin); R(6, -26, 1, 4, o.skin);

  if(o.capStyle === "hair"){

    R(-6, -33, 12, 4, o.hair); R(-6, -30, 2, 4, o.hair); R(4, -30, 2, 4, o.hair);

    R(-5, -34, 2, 1, o.hair); R(-1, -35, 3, 2, o.hair); R(3, -34, 2, 1, o.hair);

    if(o.dir === "up") R(-6, -31, 12, 10, o.hair);

  } else if(o.capStyle === "cap"){

    R(-7, -32, 14, 4, "#162f52"); R(-7, -29, 14, 1, "#c9a227");

    if(o.dir === "down") R(-7, -28, 14, 1, "#162f52");

    if(o.dir === "left") R(-9, -28, 5, 1, "#162f52");

    if(o.dir === "right") R(4, -28, 5, 1, "#162f52");

    if(o.dir === "up") R(-6, -30, 12, 10, "#162f52");

  } else if(o.capStyle === "colouredcap"){

    R(-7, -32, 14, 4, o.hair);

    if(o.dir === "down") R(-7, -28, 14, 1, o.hair);

    if(o.dir === "left") R(-9, -28, 5, 1, o.hair);

    if(o.dir === "right") R(4, -28, 5, 1, o.hair);

    if(o.dir === "up") R(-6, -30, 12, 10, o.hair);

  } else {

    R(-6, -33, 12, 4, o.hair); R(-6, -30, 2, 5, o.hair); R(4, -30, 2, 5, o.hair);

    if(o.longHair){ R(-7, -29, 1, 9, o.hair); R(6, -29, 1, 9, o.hair); }

    if(o.bun) R(-1, -35, 3, 2, o.hair);

    if(o.dir === "up") R(-6, -31, 12, 10, o.hair);

  }

  if(o.dir === "down"){ R(-3, -24, 1, 2, "#1c2733"); R(2, -24, 1, 2, "#1c2733"); R(-1, -20, 2, 1, "#b06a4a"); }

  if(o.dir === "left") R(-5, -24, 1, 2, "#1c2733");

  if(o.dir === "right") R(4, -24, 1, 2, "#1c2733");

  ctx.restore();

}

function drawPerson(x, y, color, hat, name, dir, isPlayer, hideName, bob, phase){

  if(hideName) name = null;

  chibiSprite({

    x: x, y: y, bob: bob, phase: phase, dir: dir,

    shirt: isPlayer ? "#16345e" : color, shade: isPlayer ? "#1f4476" : shadeOf(color),

    pants: isPlayer ? "#1d2c47" : "#2c3242", skin: "#eebd93",

    hair: "#26202b", capStyle: isPlayer ? "hair" : (hat ? "cap" : "hair"),

    police: !!isPlayer, dress: false

  });

  if(name && !isPlayer){

    ctx.save();

    ctx.font = "700 11px 'Barlow', sans-serif"; ctx.textAlign = "center"; ctx.textBaseline = "alphabetic";

    var label = isPlayer ? (name + " \u00B7 " + state.rank.toUpperCase()) : name;

    var tw = ctx.measureText(label).width + 10;

    ctx.fillStyle = "rgba(11,25,48,.82)"; rr(x - tw / 2, y - 50 + (bob || 0), tw, 15, 7); ctx.fill();

    ctx.fillStyle = "#fff"; ctx.fillText(label, x, y - 39 + (bob || 0));

    ctx.restore();

  }

}

function drawPedFigure(x, y, app, name, dir, bob, phase, showLabel){

  var police = app.cap === "police";

  chibiSprite({

    x: x, y: y, bob: bob, phase: phase, dir: dir,

    shirt: app.shirt, shade: shadeOf(app.shirt), pants: app.pants || "#2c3242",

    skin: app.skin, hair: app.hair || "#3a2c20",

    capStyle: police ? "cap" : (app.cap ? "colouredcap" : "hair"),

    longHair: app.hairStyle === 1, bun: app.hairStyle === 2,

    police: police, dress: !!(app.dress && !police)

  });

  if(showLabel && name) labelPill(name, x, y - 50 + (bob || 0), 11);

}

/* ---- Unit 9: the boards' overhead patrol car (navy body, white roof

   panel with unit number, red/blue roof bar). Drawn pointing +x and

   rotated whole, so E/W are true overhead views, never side profiles. ---- */

function drawCar(t){

  if(car.map !== state.map) return;

  ctx.save();

  ctx.translate(car.x, car.y);

  ctx.rotate(car.angle);

  ctx.fillStyle = "rgba(255,240,170,.18)";

  ctx.beginPath(); ctx.moveTo(CAR_LEN/2, -14); ctx.lineTo(CAR_LEN/2+62, -26); ctx.lineTo(CAR_LEN/2+62, -2); ctx.closePath(); ctx.fill();

  ctx.beginPath(); ctx.moveTo(CAR_LEN/2, 14); ctx.lineTo(CAR_LEN/2+62, 2); ctx.lineTo(CAR_LEN/2+62, 26); ctx.closePath(); ctx.fill();

  ctx.fillStyle = "rgba(0,0,0,.28)"; rr(-CAR_LEN/2+3, -CAR_WID/2+5, CAR_LEN, CAR_WID, 10); ctx.fill();

  ctx.fillStyle = "#182f52"; rr(-CAR_LEN/2, -CAR_WID/2, CAR_LEN, CAR_WID, 10); ctx.fill();

  ctx.fillStyle = "#f2f4f6"; ctx.fillRect(-CAR_LEN/2+7, -CAR_WID/2, 7, CAR_WID); ctx.fillRect(CAR_LEN/2-14, -CAR_WID/2, 7, CAR_WID);

  ctx.fillStyle = "#ffffff"; ctx.font = "700 10px 'Barlow Condensed', sans-serif"; ctx.textAlign = "center";

  ctx.save(); ctx.translate(-4, -CAR_WID/2+13); ctx.fillText("POLICE", 0, 0); ctx.restore();

  ctx.save(); ctx.translate(-4, CAR_WID/2-4); ctx.fillText("POLICE", 0, 0); ctx.restore();

  ctx.fillStyle = "#2e4a7a"; rr(14, -CAR_WID/2+6, 15, CAR_WID-12, 4); ctx.fill();

  ctx.fillStyle = "#79a8b5"; rr(16, -CAR_WID/2+8, 11, CAR_WID-16, 3); ctx.fill();

  ctx.fillStyle = "#f2f4f6"; rr(-13, -CAR_WID/2+5, 24, CAR_WID-10, 5); ctx.fill();

  ctx.fillStyle = "#182f52"; ctx.font = "700 19px 'Barlow Condensed', sans-serif"; ctx.textAlign = "center";

  ctx.fillText("9", 0, 7);

  ctx.fillStyle = "#c9a227"; ctx.font = "700 6.5px 'Barlow Condensed', sans-serif"; ctx.fillText("UNIT", -7, -9);

  ctx.fillStyle = "#2e4a7a"; rr(-27, -CAR_WID/2+6, 11, CAR_WID-12, 4); ctx.fill();

  ctx.fillStyle = "#79a8b5"; rr(-25, -CAR_WID/2+8, 7, CAR_WID-16, 3); ctx.fill();

  ctx.strokeStyle = "rgba(255,255,255,.35)"; ctx.lineWidth = 1.2;

  ctx.beginPath(); ctx.moveTo(11, -CAR_WID/2+3); ctx.lineTo(11, CAR_WID/2-3); ctx.stroke();

  ctx.beginPath(); ctx.moveTo(-16, -CAR_WID/2+3); ctx.lineTo(-16, CAR_WID/2-3); ctx.stroke();

  ctx.fillStyle = "#182f52"; ctx.fillRect(24, -CAR_WID/2-4, 6, 4); ctx.fillRect(24, CAR_WID/2, 6, 4);

  ctx.fillStyle = "#f4f6fa"; ctx.fillRect(-CAR_LEN/2+0.5, -5, 3.4, 10);

  ctx.fillStyle = "#ffe9a3"; ctx.fillRect(CAR_LEN/2-5, -CAR_WID/2+5, 4, 7); ctx.fillRect(CAR_LEN/2-5, CAR_WID/2-12, 4, 7);

  var brakingNow = keys.down || driveKeys.down || !!window.__carSpace;

  if(brakingNow && car.speed > 4){ ctx.fillStyle = "rgba(255,70,50,.35)"; ctx.beginPath(); ctx.arc(-CAR_LEN/2+2, -CAR_WID/2+8, 10, 0, 7); ctx.fill(); ctx.beginPath(); ctx.arc(-CAR_LEN/2+2, CAR_WID/2-8, 10, 0, 7); ctx.fill(); }

  ctx.fillStyle = brakingNow ? "#ff5040" : "#b3362b"; ctx.fillRect(-CAR_LEN/2+1, -CAR_WID/2+5, 4, 7); ctx.fillRect(-CAR_LEN/2+1, CAR_WID/2-12, 4, 7);

  if(car.speed < -6){ ctx.fillStyle = "#fdfdf4"; ctx.fillRect(-CAR_LEN/2+1, -3, 3.4, 6); }

  [[38,-CAR_WID/2-3],[38,CAR_WID/2-4],[-38,-CAR_WID/2-3],[-38,CAR_WID/2-4]].forEach(function(wp){

    ctx.fillStyle = "#14181f"; rr(wp[0]-6, wp[1], 13, 7, 3); ctx.fill();

    var wcx = wp[0] + 0.5, wcy = wp[1] + 3.5, wa = (car.wheelPhase || 0);

    ctx.strokeStyle = "#cfd6dd"; ctx.lineWidth = 1.6;

    ctx.beginPath();

    ctx.moveTo(wcx + Math.cos(wa)*4.4, wcy + Math.sin(wa)*2.2); ctx.lineTo(wcx - Math.cos(wa)*4.4, wcy - Math.sin(wa)*2.2);

    ctx.moveTo(wcx + Math.cos(wa+1.57)*4.4, wcy + Math.sin(wa+1.57)*2.2); ctx.lineTo(wcx - Math.cos(wa+1.57)*4.4, wcy - Math.sin(wa+1.57)*2.2);

    ctx.stroke();

    ctx.fillStyle = "#8a939e"; ctx.fillRect(wcx-1.4, wcy-1.4, 2.8, 2.8);

  });

  var flash = Math.floor(t/280) % 2 === 0;

  if(car.lights){

    ctx.fillStyle = flash ? "rgba(255,60,50,.32)" : "rgba(60,120,255,.32)";

    ctx.beginPath(); ctx.arc(-1, 0, 38, 0, 7); ctx.fill();

  }

  ctx.fillStyle = "#22262e"; rr(-11, -8, 22, 16, 4); ctx.fill();

  ctx.fillStyle = car.lights ? (flash ? "#ff3b30" : "#5a1a16") : "#7a2a24"; rr(-11, -8, 11, 16, 3); ctx.fill();

  ctx.fillStyle = car.lights ? (!flash ? "#3b82f6" : "#162c5a") : "#2c4a7a"; rr(0, -8, 11, 16, 3); ctx.fill();

  if(isDriving()){

    ctx.fillStyle = "#eebd93"; ctx.beginPath(); ctx.arc(-6, 0, 5.4, 0, 7); ctx.fill();

    ctx.fillStyle = "#26202b"; ctx.beginPath(); ctx.arc(-6, -1.4, 5.4, Math.PI, 0); ctx.fill();

  }

  ctx.restore();

  if(!isDriving()){

    var dd2 = driverDoorPos();

    var pulse = 3 + Math.sin(t/280)*1.6;

    ctx.save();

    ctx.strokeStyle = "rgba(201,162,39,.95)"; ctx.lineWidth = 2.5;

    ctx.beginPath(); ctx.arc(dd2.x, dd2.y, 11+pulse, 0, 7); ctx.stroke();

    ctx.fillStyle = "#c9a227"; ctx.beginPath(); ctx.arc(dd2.x, dd2.y, 5, 0, 7); ctx.fill();

    ctx.restore();

    if(nearSpot && nearSpot.id === "patrolcar") labelPill("UNIT 9 \u2014 DRIVER'S DOOR \u00B7 E FOR VEHICLE PANEL", car.x, car.y - (CAR_LEN/2 + 14), 12);

    else if(state.map === "plaza") labelPill("UNIT 9 \u2014 PATROL CAR", car.x, car.y - (CAR_LEN/2 + 14), 11);

  }

}

/* ---- interiors warmed to the boards (cream/slate tile, warm wood) ---- */

function drawRoom(r){

  ctx.fillStyle = r.fill; ctx.fillRect(r.x, r.y, r.w, r.h);

  ctx.fillStyle = "rgba(232,201,130,.07)"; ctx.fillRect(r.x, r.y, r.w, r.h);

  var L = (r.label || "").toUpperCase();

  var wood = /LIVING|KITCHEN|BEDROOM|CAF|HALE|JAY/.test(L);

  var conc = /GARAGE|WAREHOUSE|HOLDING|BOAT SHED/.test(L);

  if(wood){

    for(var py2 = r.y + 6; py2 < r.y + r.h - 4; py2 += 16){

      ctx.fillStyle = ((py2 / 16) | 0) % 2 ? "rgba(140,95,45,.13)" : "rgba(255,240,205,.12)";

      ctx.fillRect(r.x + 3, py2, r.w - 6, 7);

      var seam = r.x + 20 + (pxHash(py2, 7) * (r.w - 60));

      ctx.fillStyle = "rgba(110,70,35,.3)"; ctx.fillRect(seam, py2, 2, 14);

    }

    ctx.strokeStyle = "rgba(110,70,35,.18)"; ctx.lineWidth = 1;

    for(var wy = r.y + 16; wy < r.y + r.h; wy += 16){ ctx.beginPath(); ctx.moveTo(r.x, wy); ctx.lineTo(r.x + r.w, wy); ctx.stroke(); }

  } else if(conc){

    speckleRect(r, ["#9aa0a6", "#b5babf", "#878d94"], 32, .35);

    ctx.strokeStyle = "rgba(30,36,46,.2)"; ctx.lineWidth = 2;

    for(var cx3 = r.x + 64; cx3 < r.x + r.w; cx3 += 64){ ctx.beginPath(); ctx.moveTo(cx3, r.y + 2); ctx.lineTo(cx3, r.y + r.h - 2); ctx.stroke(); }

    for(var cy3 = r.y + 64; cy3 < r.y + r.h; cy3 += 64){ ctx.beginPath(); ctx.moveTo(r.x + 2, cy3); ctx.lineTo(r.x + r.w - 2, cy3); ctx.stroke(); }

    ctx.fillStyle = "rgba(240,200,60,.35)"; ctx.fillRect(r.x + 10, r.y + r.h - 16, Math.min(120, r.w - 20), 4);

  } else {

    for(var tx2 = r.x; tx2 < r.x + r.w; tx2 += 48){

      for(var ty2 = r.y; ty2 < r.y + r.h; ty2 += 48){

        if((((tx2 / 48) | 0) + ((ty2 / 48) | 0)) % 2 === 0){ ctx.fillStyle = "rgba(255,252,240,.14)"; ctx.fillRect(tx2, ty2, 48, 48); }

        else { ctx.fillStyle = "rgba(90,80,60,.06)"; ctx.fillRect(tx2, ty2, 48, 48); }

        if(pxHash(tx2, ty2) > 0.78){ ctx.fillStyle = "rgba(90,80,60,.07)"; ctx.fillRect(tx2 + 9, ty2 + 13, 7, 4); }

      }

    }

    ctx.strokeStyle = "rgba(90,80,60,.10)"; ctx.lineWidth = 1;

    for(var gx = r.x + 24; gx < r.x + r.w; gx += 24){ ctx.beginPath(); ctx.moveTo(gx, r.y); ctx.lineTo(gx, r.y + r.h); ctx.stroke(); }

    for(var gy = r.y + 24; gy < r.y + r.h; gy += 24){ ctx.beginPath(); ctx.moveTo(r.x, gy); ctx.lineTo(r.x + r.w, gy); ctx.stroke(); }

  }

  if(wood && r.w > 260 && r.h > 200){

    var rugX = r.x + r.w / 2 - 62, rugY = r.y + r.h / 2 - 34;

    ctx.fillStyle = "#8c3f3a"; ctx.fillRect(rugX, rugY, 124, 68);

    ctx.fillStyle = "#a85a50"; ctx.fillRect(rugX + 6, rugY + 6, 112, 56);

    ctx.fillStyle = "#e3c98a"; ctx.fillRect(rugX + 16, rugY + 16, 92, 36);

    ctx.fillStyle = "#8c3f3a"; ctx.fillRect(rugX + 26, rugY + 24, 72, 20);

  }

  ctx.fillStyle = "rgba(60,45,25,.20)"; ctx.fillRect(r.x, r.y + r.h - 5, r.w, 5);

  ctx.fillStyle = "rgba(255,255,255,.35)"; ctx.fillRect(r.x, r.y, r.w, 3);

  ctx.font = "700 15px 'Barlow Condensed', sans-serif";

  ctx.fillStyle = "rgba(70,55,35,.5)"; ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";

  ctx.fillText(r.label, r.lx, r.ly);

}

/* ---- board-density props injected beside existing anchors (visual only:

   added after solids were computed, so they can never block a door, gate,

   evidence spot or mission step) ---- */

(function injectBoardProps(){

  Object.keys(MAPS).forEach(function(id){

    var m = MAPS[id]; if(m.indoor) return;

    var add = [];

    (m.decors || []).slice().forEach(function(d){

      if((d.t === "bldg" || d.t === "house") && typeof d.doorX === "number"){

        add.push({t:"flowerbed", x:d.doorX - 92, y:d.y + d.h - 2, w:58, h:14});

        add.push({t:"flowerbed", x:d.doorX + 34, y:d.y + d.h - 2, w:58, h:14});

        add.push({t:"planter", x:d.doorX - 34, y:d.y + d.h + 1});

        add.push({t:"planter", x:d.doorX + 24, y:d.y + d.h + 1});

      }

    });

    var li = 0;

    (m.decors || []).forEach(function(d){

      if(d.t === "lamp"){ li++; if(li % 2 === 0) add.push({t:"hydrant", x:d.x + 17, y:d.y + 7}); if(li % 3 === 0) add.push({t:"trash", x:d.x - 19, y:d.y + 7}); }

      if(d.t === "busstop"){ add.push({t:"trash", x:d.x + 21, y:d.y + 5}); add.push({t:"planter", x:d.x - 28, y:d.y + 3}); }

    });

    m.decors = (m.decors || []).concat(add);

  });

  if(MAPS.downtown) MAPS.downtown.decors.push({t:"umbrella", x:498, y:394}, {t:"umbrella", x:624, y:394}, {t:"flowerbed", x:908, y:684, w:144, h:15}, {t:"flowerbed", x:908, y:884, w:144, h:15});

  if(MAPS.plaza) MAPS.plaza.decors.push({t:"flowerbed", x:330, y:560, w:190, h:15}, {t:"flowerbed", x:1420, y:262, w:190, h:15}); /* exterior rebuild: clear of the shed / garage footprints */

})();



