/* ================================================================

   SERGEANT BROOKS ART — original artwork by Jay (player-provided),

   integrated 2026-10-14. His PNGs live in assets/brooks/ as files,

   copied byte-for-byte from his pack (sha256 values recorded in

   data:application/json;base64,, verified identical on import):

     brooks.webp          128x208 sheet — 4 directions x 4 frames of

                         32x52; rows south/north/west/east top to

                         bottom; column 0 is idle; feet anchor (16,51)

     portrait_brooks.webp 144x144 dialogue portrait, transparent

   The sheet's frame geometry and row order are exactly Jay's, so the

   drawPerson override below renders Brooks through the same slicing,

   the same 44x72 dest rect and the same feet depth anchor as Jay —

   identical world scale by construction. Art swap only: her NPC

   record, interaction spot and range, talk target, mission state and

   every line of dialogue are untouched. If a PNG has not decoded

   yet, the previous procedural painter runs for that piece, so no

   frame is ever blank.

   ================================================================ */

var BROOKS_SRC = {

  portrait: "assets/embedded/e69077082c525c90def5.webp"

};

var BROOKS = {};

Object.keys(BROOKS_SRC).forEach(function(k){ var im = new Image(); assignGameAsset(im,BROOKS_SRC[k]); BROOKS[k] = im; });



/* ---- Jay: the player's own sprite sheet (rows down/up/left/right,

   columns = walk frames 1-4, column 0 doubles as idle). Movement,

   collision box and depth sorting are exactly as before; NPCs and

   pedestrians keep their existing renderers until Batch 3. ---- */

/* ---- Unit 9: Jay's overhead views. The sheet's frames are used at

   the four headings; between headings the nearest view is rotated by

   the residual angle (at most 45 degrees) so the body always lines

   up with the driving physics. Siren flash, brake/reverse lights,

   headlight beams and the door marker work exactly as before. ---- */

var drawCarB1Prev = drawCar;

/* measured artwork boxes [x, y, w, h] inside each 64x44 sheet cell,

   in sheet order N, E, S, W (alpha > 30 scan of Jay's patrol_car.webp) */

var B1_CAR_BODY = [[20, 2, 23, 40], [12, 10, 40, 22], [20, 2, 23, 40], [12, 11, 40, 22]];

drawCar = function(t){

  if(car.map !== state.map) return;

  if(!b1Ok(B1.car)){ drawCarB1Prev(t); return; }

  ctx.save();

  ctx.translate(car.x, car.y);

  ctx.save();

  ctx.rotate(car.angle);

  ctx.fillStyle = "rgba(255,240,170,.18)";

  ctx.beginPath(); ctx.moveTo(CAR_LEN / 2, -14); ctx.lineTo(CAR_LEN / 2 + 62, -26); ctx.lineTo(CAR_LEN / 2 + 62, -2); ctx.closePath(); ctx.fill();

  ctx.beginPath(); ctx.moveTo(CAR_LEN / 2, 14); ctx.lineTo(CAR_LEN / 2 + 62, 2); ctx.lineTo(CAR_LEN / 2 + 62, 26); ctx.closePath(); ctx.fill();

  ctx.fillStyle = "rgba(0,0,0,.28)"; rr(-CAR_LEN / 2 + 3, -CAR_WID / 2 + 5, CAR_LEN, CAR_WID, 10); ctx.fill();

  ctx.restore();

  var twoPi = Math.PI * 2;

  var an = ((car.angle % twoPi) + twoPi) % twoPi;

  var quad = Math.round(an / (Math.PI / 2)) % 4;           /* 0 E, 1 S, 2 W, 3 N */

  var frame = [1, 2, 3, 0][quad];                          /* sheet order: N E S W */

  var res = an - Math.round(an / (Math.PI / 2)) * (Math.PI / 2);

  ctx.save();

  ctx.rotate(res);

  /* The sheet's 64x44 cells carry generous transparent margins — the

     actual car body is only ~40x22 (E/W) or ~23x40 (N/S) inside each

     cell, so drawing the whole cell made Unit 9 render far smaller

     than the civilian cars. Crop to the measured body box of each

     frame and scale so the drawn body matches the car's real

     footprint (CAR_LEN long): drawn ~96x53 E/W, ~55x96 N/S. */

  var bb = B1_CAR_BODY[frame];

  var bs = CAR_LEN / 40;                    /* E/W body is 40px long in the sheet */

  var bcx = (bb[0] + bb[2] / 2 - 32) * bs, bcy = (bb[1] + bb[3] / 2 - 22) * bs;

  ctx.drawImage(B1.car, frame * 64 + bb[0], bb[1], bb[2], bb[3],

    bcx - bb[2] * bs / 2, bcy - bb[3] * bs / 2, bb[2] * bs, bb[3] * bs);

  ctx.restore();

  ctx.save();

  ctx.rotate(car.angle);

  var flash = Math.floor(t / 280) % 2 === 0;

  if(car.lights){

    ctx.fillStyle = flash ? "rgba(255,60,50,.32)" : "rgba(60,120,255,.32)";

    ctx.beginPath(); ctx.arc(-1, 0, 38, 0, 7); ctx.fill();

    ctx.fillStyle = flash ? "rgba(255,80,60,.85)" : "rgba(255,80,60,.25)"; ctx.fillRect(-13, -18, 10, 18);

    ctx.fillStyle = !flash ? "rgba(90,150,255,.85)" : "rgba(90,150,255,.25)"; ctx.fillRect(-13, 0, 10, 18);

  }

  var brakingNow = keys.down || driveKeys.down || !!window.__carSpace;

  if(brakingNow && car.speed > 4){

    ctx.fillStyle = "rgba(255,70,50,.35)";

    ctx.beginPath(); ctx.arc(-CAR_LEN / 2 + 2, -CAR_WID / 2 + 8, 10, 0, 7); ctx.fill();

    ctx.beginPath(); ctx.arc(-CAR_LEN / 2 + 2, CAR_WID / 2 - 8, 10, 0, 7); ctx.fill();

    ctx.fillStyle = "#ff5040"; ctx.fillRect(-CAR_LEN / 2 + 1, -CAR_WID / 2 + 5, 4, 7); ctx.fillRect(-CAR_LEN / 2 + 1, CAR_WID / 2 - 12, 4, 7);

  }

  if(car.speed < -6){ ctx.fillStyle = "#fdfdf4"; ctx.fillRect(-CAR_LEN / 2 + 1, -3, 3.4, 6); }

  ctx.restore();

  ctx.restore();

  if(!isDriving()){

    var dd2 = driverDoorPos();

    var pulse = 3 + Math.sin(t / 280) * 1.6;

    ctx.save();

    ctx.strokeStyle = "rgba(201,162,39,.95)"; ctx.lineWidth = 2.5;

    ctx.beginPath(); ctx.arc(dd2.x, dd2.y, 11 + pulse, 0, 7); ctx.stroke();

    ctx.fillStyle = "#c9a227"; ctx.beginPath(); ctx.arc(dd2.x, dd2.y, 5, 0, 7); ctx.fill();

    ctx.restore();

    if(nearSpot && nearSpot.id === "patrolcar") labelPill("UNIT 9 \u2014 DRIVER'S DOOR \u00B7 E FOR VEHICLE PANEL", car.x, car.y - (CAR_LEN/2 + 14), 12);

    else if(state.map === "plaza") labelPill("UNIT 9 \u2014 PATROL CAR", car.x, car.y - (CAR_LEN/2 + 14), 11);

  }

};



/* ---- props & crosswalk overlays from Batch 1 ---- */

var B1_PALM_MAPS = {plaza: 1, waterfront: 1, southbay: 1, downtown: 1, midtown: 1};

function b1CrosswalkTile(d){

  ctx.save();

  ctx.beginPath(); ctx.rect(d.x, d.y, d.w, d.h); ctx.clip();

  var rot = d.t === "crosswalk";

  for(var ty = Math.floor(d.y / 32) * 32; ty < d.y + d.h; ty += 32){

    for(var tx = Math.floor(d.x / 32) * 32; tx < d.x + d.w; tx += 32){

      if(rot){

        ctx.save(); ctx.translate(tx + 16, ty + 16); ctx.rotate(Math.PI / 2);

        ctx.drawImage(B1.crosswalk, -16, -16, 32, 32); ctx.restore();

      } else ctx.drawImage(B1.crosswalk, tx, ty, 32, 32);

    }

  }

  ctx.restore();

  return true;

}

var drawDecorB1Prev = drawDecor;

drawDecor = function(d, t){

  if(d.t === "crosswalk" || d.t === "crosswalkV"){

    if(b1Ok(B1.crosswalk) && b1CrosswalkTile(d)) return;

  } else if(d.t === "lamp"){

    if(b1Ok(B1.lamp)){

      ctx.save();

      ctx.fillStyle = "rgba(0,0,0,.18)"; ctx.beginPath(); ctx.ellipse(d.x, d.y + 4, 8, 3, 0, 0, 7); ctx.fill();

      ctx.drawImage(B1.lamp, d.x - 8, d.y + 4 - 48, 16, 48);

      var gl = 0.10 + 0.05 * Math.sin(t / 900 + d.x);

      ctx.fillStyle = "rgba(255,230,150," + gl.toFixed(3) + ")";

      ctx.beginPath(); ctx.arc(d.x, d.y - 40, 9, 0, 7); ctx.fill();

      ctx.restore(); return;

    }

  } else if(d.t === "hydrant"){

    if(b1Ok(B1.hydrant)){

      ctx.save();

      ctx.fillStyle = "rgba(0,0,0,.18)"; ctx.beginPath(); ctx.ellipse(d.x, d.y + 2, 8, 3, 0, 0, 7); ctx.fill();

      ctx.drawImage(B1.hydrant, d.x - 10, d.y + 2 - 28, 20, 28);

      ctx.restore(); return;

    }

  } else if(d.t === "trash"){

    if(b1Ok(B1.trash)){

      ctx.save();

      ctx.fillStyle = "rgba(0,0,0,.16)"; ctx.beginPath(); ctx.ellipse(d.x, d.y + 2, 9, 3, 0, 0, 7); ctx.fill();

      ctx.drawImage(B1.trash, d.x - 12, d.y + 2 - 32, 24, 32);

      ctx.restore(); return;

    }

  } else if(d.t === "planter"){

    if(b1Ok(B1.planter)){

      ctx.save();

      ctx.fillStyle = "rgba(0,0,0,.16)"; ctx.beginPath(); ctx.ellipse(d.x + 11, d.y + 15, 15, 4, 0, 0, 7); ctx.fill();

      ctx.drawImage(B1.planter, d.x - 9, d.y + 16 - 28, 40, 28);

      ctx.restore(); return;

    }

  } else if(d.t === "bench"){

    if(b1Ok(B1.bench)){

      ctx.save();

      var bw = Math.max(46, d.w || 46), bh = bw * 28 / 48;

      ctx.fillStyle = "rgba(0,0,0,.16)"; ctx.fillRect(d.x + 2, d.y + (d.h || 20) - 2, d.w || bw, 5);

      ctx.drawImage(B1.bench, d.x + (d.w || bw) / 2 - bw / 2, d.y + (d.h || 20) - bh, bw, bh);

      ctx.restore(); return;

    }

  } else if((d.t === "tree" || d.t === "bigtree") && B1_PALM_MAPS[state.map]){

    if(b1Ok(B1.palm)){

      ctx.save();

      var ps = d.t === "bigtree" ? 1.3 : 1, pw = 48 * ps, ph = 64 * ps;

      ctx.fillStyle = "rgba(0,0,0,.16)"; ctx.beginPath(); ctx.ellipse(d.x + 3, d.y + 9, 16 * ps, 5 * ps, 0, 0, 7); ctx.fill();

      ctx.drawImage(B1.palm, d.x - pw / 2, d.y + 10 - ph, pw, ph);

      ctx.restore(); return;

    }

  }

  drawDecorB1Prev(d, t);

};



/* ---- Batch 1 prop placement & collision ----

   Lamp posts already line the streets (79 of them) and hydrants,

   bins and planters were placed beside lamps, bus stops and doors

   by the board-density pass; they all pick up Jay's art above.

   This pass adds the collision the spec asks for (small boxes at

   the bases of planters; hydrants on the precinct grounds) and two

   benches on the station plaza. Benches and bins stay non-blocking. */

(function b1PlaceProps(){

  Object.keys(MAPS).forEach(function(id){

    var m = MAPS[id]; if(m.indoor) return;

    (m.decors || []).forEach(function(d){

      if(d.t === "planter") m.solids.push({x: d.x + 3, y: d.y + 9, w: 16, h: 7});

    });

  });

  var pz = MAPS.plaza;

  if(pz){

    [[250, 660], [1080, 660], [250, 836], [1150, 1000]].forEach(function(p){

      pz.decors.push({t: "hydrant", x: p[0], y: p[1]});

      pz.solids.push({x: p[0] - 5, y: p[1] - 3, w: 10, h: 8});

    });

    pz.decors.push({t: "bench", x: 300, y: 470, w: 52, h: 22});

    pz.decors.push({t: "bench", x: 380, y: 560, w: 52, h: 22}); /* exterior rebuild: was inside the new precinct footprint */

  }

})();





