/* ================================================================

   BATCH 2 PLAYER ART — original artwork by Jay (player-provided),

   integrated 2026-10-13. All 17 Batch 2 PNGs are inlined above as

   base64 data URIs (B2_SRC; no external files are loaded):

     precinct.webp        320x240 — Precinct 9 building (doors centred

                         at x=160, content bottom = the door step)

     floor_checker_coarse.webp 32x32 — precinct floors (scale derivative

                         of Jay's floor_checker.webp, rebuilt 2026-10-13 at

                         his request: 2x2 checks of 16px in the original's

                         colours; the original file stays untouched on disk)

     floor_wood.webp      32x32 — homes, café, offices

     floor_concrete.webp  32x32 — warehouse, garage, boat shed

     wall_segment.webp    64x48 — interior divider-wall skin

     bulletin_board.webp  48x48 — briefing / operations / city hall boards

     computer_terminal.webp 48x48 — computer desks (Records, City Hall,

                         Jay's house)

     counter.webp         96x48 — front-desk + service counters

     evidence_shelf.webp  64x64 — Evidence Room shelves

     file_cabinet.webp    24x48 — records / office cabinets

     holding_cell_bars.webp 96x48 — barred front of the holding cells

     interior_door.webp   32x48 — interior doorways (the gold strips)

     interview_table.webp 80x64 — Interview Room table

     lobby_bench.webp     72x40 — lobby / waiting benches

     locker_row.webp      96x64 — locker room banks

     office_chair.webp    24x32 — chairs tucked at desks (non-blocking)

     desk.webp            64x48 — office desks

   Recorded in the project asset attribution log (assets/ATTRIBUTION.md)

   as player-provided original artwork by Jay.

   PRECINCT REFRESH (2026-10-14, Jay's zipped re-upload — original

   bytes with real alpha, sha256-verified against his manifest; the

   pack also lives on disk under assets/precinct-refresh/): the twelve

   furniture payloads above were replaced byte-for-byte with the

   originals (the first integration carried flattened-upload damage),

   and four pieces were added — floor_stone / floor_office_wood /

   floor_evidence_concrete (32x32; the station's floors by room, see

   b2FloorKind) and wall_horizontal (96x40; the station's horizontal

   divider skin, see b2WallSkin). wall_vertical and wall_corner from

   the same pack were reviewed against the wall geometry and not

   used — the reasons are recorded at b2WallSkin.

   How it integrates — same rule as Batch 1: the painters below swap

   ART ONLY. Every furniture box, solid, spot, NPC, doorway and

   mission trigger keeps its exact position and behaviour; a piece of

   art is anchored to the base of the furniture box it replaces, and

   if an image has not decoded yet the previous painter runs, so no

   frame is ever blank.

   ================================================================ */

var B2 = {};

Object.keys(B2_SRC).forEach(function(k){ var im = new Image(); assignGameAsset(im,B2_SRC[k]); B2[k] = im; });

function b2Ok(im){ return !!(im && im.complete && im.naturalWidth > 0); }

var B2_PAT = {};

function b2Pattern(key){

  if(B2_PAT[key]) return B2_PAT[key];

  if(!b2Ok(B2[key])) return null;

  var p = ctx.createPattern(B2[key], "repeat");

  if(p) B2_PAT[key] = p;

  return p;

}

function b2HitsAny(r, arr){ for(var i = 0; i < arr.length; i++) if(overlaps(r, arr[i])) return true; return false; }



/* ---- floors: Jay's tiles laid over the room fills (the previous

   floor treatment stays underneath as the fallback) ---- */

function b2FloorKind(r){

  var L = (r.label || "").toUpperCase();

  if(state.map === "station"){

    /* Precinct refresh floors (Jay's tiles, laid as natural 32x32

       patterns): calm stone for the public rooms (Lobby, Intake,

       Locker Room), muted wood for the offices (Records, Interview,

       Briefing, Operations, Sgt. Brooks), quiet concrete for Evidence

       and Holding. The Garage keeps the Batch 2 concrete. The dense

       checker (floorCheck) is retired inside the station. */

    if(/EVIDENCE|HOLDING/.test(L)) return "floorEvidence";

    if(/RECORDS|INTERVIEW|BRIEFING|OPERATIONS|SGT/.test(L)) return "floorOffice";

    if(/GARAGE/.test(L)) return "floorConc";

    return "floorStone";

  }

  if(/WAREHOUSE|GARAGE|BOAT SHED/.test(L)) return "floorConc";

  if(/LIVING|KITCHEN|BEDROOM|CAF|OFFICE/.test(L)) return "floorWood";

  return null;

}

var drawRoomB2Prev = drawRoom;

drawRoom = function(r){

  drawRoomB2Prev(r);

  var kind = b2FloorKind(r);

  if(!kind) return;

  var pat = b2Pattern(kind);

  if(!pat) return;

  ctx.save();

  ctx.beginPath(); ctx.rect(r.x + 2, r.y + 2, r.w - 4, r.h - 4); ctx.clip();

  ctx.globalAlpha = (kind === "floorStone" || kind === "floorOffice" || kind === "floorEvidence") ? 1 : 0.92;

  ctx.fillStyle = pat; ctx.fillRect(r.x, r.y, r.w, r.h);

  ctx.restore();

  ctx.font = "700 15px 'Barlow Condensed', sans-serif";

  ctx.fillStyle = "rgba(16,35,63,.45)"; ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";

  ctx.fillText(r.label, r.lx, r.ly);

};



/* ---- furniture: which of Jay's pieces replaces a furniture box,

   and at what size. Every rect is anchored to the box's base line

   (f.y + f.h) — the same line its collision uses. ---- */

function b2IsTerminalDesk(f){

  if(state.map === "station") return f.x === 430 && f.y === 56;      /* Records — the Access Computer desk */

  if(state.map === "municipal") return f.x === 900 && f.y === 300;   /* clerk's desk */

  if(state.map === "house" || state.map === "hale") return f.x === 700 && f.y === 500;

  return false;

}

function b2FurnArt(f){

  var cx = f.x + f.w / 2, base = f.y + f.h + 2, w, h;

  switch(f.type){

    case "reception":

      if(!b2Ok(B2.counter)) return null;

      w = Math.max(f.w + 24, 180); h = Math.min(w * 0.5, base - 16);

      return {im: B2.counter, cx: cx, base: base, w: w, h: h};

    case "counter":

      if(!b2Ok(B2.counter)) return null;

      w = Math.max(f.w, 120); h = Math.min(w * 0.5, 120, base - 16);

      if(h < 30) return null;

      return {im: B2.counter, cx: cx, base: base, w: w, h: h};

    case "desk":

      if(b2IsTerminalDesk(f) && b2Ok(B2.terminal)) return {im: B2.terminal, cx: cx, base: base, w: 86, h: 86};

      if(!b2Ok(B2.desk)) return null;

      w = Math.min(Math.max(f.w, 96), 150);

      return {im: B2.desk, cx: cx, base: base, w: w, h: w * 0.75};

    case "table":

      /* only the Interview Room table — café / home tables keep theirs */

      if(state.map === "station" && f.w >= 120 && b2Ok(B2.interview))

        return {im: B2.interview, cx: cx, base: base, w: 150, h: 120};

      return null;

    case "shelf":

      /* only the Evidence Room shelves (top row of the station) */

      if(state.map === "station" && f.y < 300 && b2Ok(B2.evidence)){

        w = f.w + 8; h = Math.min(w, base - 2);

        return {im: B2.evidence, cx: cx, base: base, w: w, h: h};

      }

      return null;

    case "cabinet":

      if(!b2Ok(B2.cabinet)) return null;

      return {im: B2.cabinet, cx: cx, base: base, w: 54, h: 108};

    case "locker":

      if(!b2Ok(B2.lockers)) return null;

      w = Math.min(Math.max(f.w, 130), Math.max(60, (base - 14) * 1.5));

      return {im: B2.lockers, cx: cx, base: base, w: w, h: w * 2 / 3};

    case "bench":

      if(!b2Ok(B2.bench)) return null;

      w = Math.max(f.w, 110); h = Math.min(w * 40 / 72, base - 14);

      return {im: B2.bench, cx: cx, base: base, w: w, h: h};

    case "board":

      if(!b2Ok(B2.board)) return null;

      return {im: B2.board, cx: cx, base: f.y + 62, w: 84, h: 84};

  }

  return null;

}

function b2DeskExtras(f){

  if(f.type !== "desk") return;

  /* office chair tucked at the south side of the desk (non-blocking) */

  if(state.map === "station" && (f.y > 850 || f.x > 1400)) return;   /* intake / holding / briefing desks */

  if(b2Ok(B2.chair)) ctx.drawImage(B2.chair, Math.round(f.x + f.w / 2 - 15), Math.round(f.y + f.h + 1), 30, 40);

}

/* Furniture Jay is standing BEHIND (north of its base) is repainted

   after his sprite by the draw wrapper below, so tall pieces occlude

   him exactly the way the precinct frontage does outside. */

var B2_FRONT = [];

var drawFurnB2Prev = drawFurn;

drawFurn = function(f){

  var m = curMap();

  if(!m.indoor){ drawFurnB2Prev(f); return; }

  var art = b2FurnArt(f);

  if(!art){ drawFurnB2Prev(f); b2DeskExtras(f); return; }

  if(f.solid){ ctx.fillStyle = "rgba(10,16,26,.14)"; rr(f.x + 3, f.y + f.h - 2, f.w, 5, 3); ctx.fill(); }

  var rect = {x: art.cx - art.w / 2, y: art.base - art.h, w: art.w, h: art.h};

  var pb = player.y + player.h;

  var behind = !(state.map === 'station' && window.HARBOR && window.HARBOR.precinctLighting) && !isDriving() && pb <= art.base + 1 && pb > rect.y &&

               player.x + player.w > rect.x + 4 && player.x < rect.x + rect.w - 4;

  if(behind) B2_FRONT.push({im: art.im, x: rect.x, y: rect.y, w: rect.w, h: rect.h});

  else ctx.drawImage(art.im, Math.round(rect.x), Math.round(rect.y), Math.round(rect.w), Math.round(rect.h));

  b2DeskExtras(f);

};



/* ---- interior divider walls: Jay's wall segment skinned over the

   flat wall bars. Skips tiles at door gaps and behind tall furniture

   (a counter against a wall keeps its top). Outer walls keep the

   existing flat treatment; the holding-cell front is never skinned —

   the bars live there. Drawn from the first decor call of the frame,

   which the indoor pass makes after walls and before spots/people. */

var B2_SKIN_STAMP = "";

function b2WallSkin(m){

  var gaps = [], arts = [];

  (m.decors || []).forEach(function(d){ if(d.t === "strip") gaps.push({x: d.x - 12, y: d.y - 12, w: d.w + 24, h: d.h + 24}); });

  (m.furn || []).forEach(function(f){ var a = b2FurnArt(f); if(a) arts.push({x: a.cx - a.w / 2 - 2, y: a.base - a.h - 2, w: a.w + 4, h: a.h + 4}); });

  (m.walls || []).forEach(function(w){

    var horiz = w.w >= 100 && w.h <= 8, vert = w.h >= 100 && w.w <= 8;

    if((!horiz && !vert) || w.x <= 0 || w.y <= 0 || w.x + w.w >= m.w || w.y + w.h >= m.h) return;

    var cellBlock = false;

    (m.decors || []).forEach(function(d){ if(d.t === "cells" && overlaps(w, d)) cellBlock = true; });

    if(cellBlock) return;

    var x, y, r;

    /* Each tile sits on a deep-navy underlay a few px larger than the art

       (heavier along the floor side): Jay's cream upper panel no longer

       blends into the pale checker floors, and the tiles merge into one

       continuous dark-edged wall line. Same skip rules as the art. */

    ctx.fillStyle = "#0a1830";

    if(horiz){

      /* Precinct refresh: the station's horizontal dividers wear Jay's

         wall_horizontal.webp at natural size (96x40; its left and right

         edge columns are identical, so it tiles seamlessly along a

         run). Same underlay and skip rules as the Batch 2 segment.

         The pack's other two wall pieces were reviewed and NOT used:

         wall_vertical.webp is 92% transparent with its only opaque

         fragment in the bottom 26 rows — an end cap, not a runnable

         strip — so vertical dividers keep the rotated Batch 2

         segment; wall_corner.webp is an L-corner, but every divider

         junction in the station is a T or a cross, so it has nowhere

         clean to sit. Neither piece touches a door opening. */

      var useH = (state.map === "station" && b2Ok(B2.wallH));

      var tw = useH ? 96 : 64, th = useH ? 40 : 36, tim = useH ? B2.wallH : B2.wall;

      for(x = w.x; x < w.x + w.w; x += tw){

        r = {x: x, y: w.y + w.h / 2 - th / 2, w: tw, h: th};

        if(b2HitsAny(r, gaps) || b2HitsAny(r, arts)) continue;

        ctx.fillRect(Math.round(x) - 1, Math.round(r.y) - 2, tw + 2, th + 5);

        ctx.drawImage(tim, Math.round(x), Math.round(r.y), tw, th);

      }

    } else {

      for(y = w.y; y < w.y + w.h; y += 64){

        r = {x: w.x + w.w / 2 - 18, y: y, w: 36, h: 64};

        if(b2HitsAny(r, gaps) || b2HitsAny(r, arts)) continue;

        ctx.save();

        ctx.translate(Math.round(w.x + w.w / 2), Math.round(y + 32));

        ctx.rotate(Math.PI / 2);

        ctx.fillRect(-33, -20, 66, 41);

        ctx.drawImage(B2.wall, -32, -18, 64, 36);

        ctx.restore();

      }

    }

  });

}

function b2DrawCells(d){

  ctx.save();

  /* Jay's bars tiled across the cell front, on the barred wall line

     (y = d.y + 88), with a rail top and bottom to carry the run */

  var frontY = d.y + 88;

  ctx.save();

  ctx.beginPath(); ctx.rect(d.x, frontY - 24, d.w, 48); ctx.clip();

  for(var x = d.x - 12; x < d.x + d.w; x += 96) ctx.drawImage(B2.bars, x, frontY - 24, 96, 48);

  ctx.restore();

  ctx.fillStyle = "#2c3644";

  ctx.fillRect(d.x, frontY - 25, d.w, 4); ctx.fillRect(d.x, frontY + 21, d.w, 4);

  ctx.fillStyle = "rgba(16,35,63,.5)"; ctx.font = "700 11px 'Barlow Condensed'"; ctx.textAlign = "center";

  ctx.fillText("CELL 1", d.x + 60, d.y + 22); ctx.fillText("CELL 2", d.x + 180, d.y + 22); ctx.fillText("CELL 3", d.x + 300, d.y + 22);

  ctx.restore();

}

var drawDecorB2Prev = drawDecor;

drawDecor = function(d, t){

  var m = curMap();

  if(m.indoor && b2Ok(B2.wall)){

    var stamp = state.map + "@" + t;

    if(B2_SKIN_STAMP !== stamp){ B2_SKIN_STAMP = stamp; b2WallSkin(m); }

  }

  if(m.indoor && d.t === "strip" && b2Ok(B2.door)){

    /* Jay's door leaf centred on the doorway strip (non-blocking:

       the decor pass runs under spots, NPCs and Jay) */

    ctx.save();

    ctx.drawImage(B2.door, Math.round(d.x + d.w / 2 - 22), Math.round(d.y + d.h / 2 - 33), 44, 66);

    ctx.restore();

    return;

  }

  if(state.map === "station" && d.t === "cells" && b2Ok(B2.bars)){ b2DrawCells(d); return; }

  drawDecorB2Prev(d, t);

};



/* ---- Precinct 9 exterior: Jay's building on the grounds. The art's

   content (320x240 frame, building occupies y 30..232, doors centred

   at x=160, door step at the content bottom) is placed at natural

   size with the step on the existing footprint's south edge, so the

   entrance spot, the door marker, the collision footprint and the

   walk-behind fade all line up with the doors as before. ---- */

var drawPrecinctBldgB2Prev = drawPrecinctBldg;

drawPrecinctBldg = function(d, t){

  if(state.map !== "plaza" || !b2Ok(B2.precinct)){ drawPrecinctBldgB2Prev(d, t); return; }

  ctx.save();

  var fade = (!isDriving() && player.y + player.h < d.y + 58 && player.x > d.x - 46 && player.x < d.x + d.w + 46) ? 0.42 : 1;

  ctx.globalAlpha = fade;

  ctx.fillStyle = "rgba(10,16,26,.28)";

  ctx.fillRect(d.doorX - 154, d.y + d.h - 4, 320, 12);

  ctx.drawImage(B2.precinct, Math.round(d.doorX - 160), -21, 320, 240);

  ctx.restore();

};



/* ---- deferred front-pass for furniture Jay stands behind ---- */

var drawB2Prev = draw;

draw = function(t){

  B2_FRONT.length = 0;

  drawB2Prev(t);

  if(B2_FRONT.length){

    ctx.save();

    if(!(typeof csCam !== "undefined" && csCam && csCam.on) && effZoom() !== 1) ctx.scale(effZoom(), effZoom());

    ctx.translate(-cam.x, -cam.y);

    B2_FRONT.forEach(function(a){ ctx.drawImage(a.im, Math.round(a.x), Math.round(a.y), Math.round(a.w), Math.round(a.h)); });

    ctx.restore();

    B2_FRONT.length = 0;

  }

};



/* ================================================================

   PRECINCT 9 WALLS & DOORS REBUILD (2026-10-14) — Jay's illustrated

   tileset (assets/precinct-tileset/, copied byte-for-byte from his

   staged pack, sha256-verified against his manifest), matched to

   his cream/navy reference illustration.

   GEOMETRY (MAPS.station above): Jay's collision body is 26px wide.

   Ordinary doorway gaps are 52px (2x body); lobby and briefing-room

   entrances are 72px double doors; the main and garage entrances

   are 72px. Walkable widths were derived from the door art's alpha

   silhouette, measured on the staged PNGs (rows above the bottom

   threshold plate, columns >85% transparent): door_open_single.webp

   (80px art) has a ~42px clear passage at art x≈25..67 (centre ≈46 —

   the open leaf rides the left jamb); door_open_double.webp (128px

   art) has a ~68px clear passage at art x≈31..99 (centre ≈65). The

   art is placed by its PASSAGE centre and never rescaled, so frames

   and open leaves sit outside the walking path while the collision

   gap itself (52 / 72) is what Jay walks through. Collision solids

   are precomputed from the same wall rects, so art and collision

   cannot drift apart. Every widened gap keeps its old centre and

   contains its old 44px gap, so no saved position is trapped;

   unstickPlayer() remains as a backstop.

   BOLD-WALLS PASS (2026-10-14 — Jay's explicit override of the

   earlier no-stretch call, which had left wall_vertical, the

   corners and wall_t unused): every tileset wall piece is now

   used, stretched to fit, so the dividers read thick and

   prominent like his reference illustration. wall_horizontal.webp

   (96x48 — cream cap rail and face over navy panelled wainscot)

   still tiles the horizontal runs at native size, clipped to each

   run, with wall_end.webp capping the gap-side ends (mirrored for

   left-hand ends). wall_vertical.webp (24x96: two finished edge

   slivers — cap rail, cream face, navy base — around a

   transparent middle) is tiled from its uniform cream band

   (source rows 12..60) and stretched 24->32px wide over a body

   painted in the same sampled cream/navy split, so the art's own

   shaded edges finish both sides of a continuous 32px wall.

   Junctions are dressed from the pieces: wall_t.webp stretched to

   112x64 — its 48px arm lands exactly on the horizontal band and

   its stem on the vertical band — at the two T junctions (384,304)

   and (384,644), doubled stem-to-stem at the four crossings; the

   four 64x64 corners sit at 32x32 with their elbows on each

   crossing's centre, arms inside the bands, so every crossing

   reads as one connected joint. Collision was thickened to the

   skins' footprints in MAPS.station (see there): perpendicular

   only, so all 18 doorway gaps keep their widths and centres.

   ================================================================ */

var P9_SRC = {

  wallH: "assets/embedded/3e51f6e8a7251a8413e9.webp",

  wallEnd: "assets/embedded/7b28b690742bf799093c.webp",

  wallV: "assets/embedded/dbce2ae433521b249f90.webp",

  wallT: "assets/embedded/235cff28d66f40c6c49b.webp",

  cornerNW: "assets/embedded/cdf3c1a87b6803371b9d.webp",

  cornerNE: "assets/embedded/42935474c90208fbf131.webp",

  cornerSW: "assets/embedded/e5e14a5a0ef55363e74b.webp",

  cornerSE: "assets/embedded/f3bbcdf5e208ea415cbe.webp",

  doorS: "assets/embedded/5fce43a435d58933a09c.webp",

  doorD: "assets/embedded/e93c7fb2c0a7ff27ffd6.webp",

  thresh: "assets/embedded/923ff1b663b0a5f4c90c.webp",

  rug: "assets/embedded/f3a56bbad7631b96a25e.webp"

};

var P9 = {};

Object.keys(P9_SRC).forEach(function(k){ var im = new Image(); assignGameAsset(im,P9_SRC[k]); P9[k] = im; });

function p9Ok(im){ return !!(im && im.complete && im.naturalWidth > 0); }

/* Doorway table — centres match the widened gaps in MAPS.station.

   axis "h": doorway in a horizontal wall (passage runs north-south);

   axis "v": in a vertical wall. kind "d" = double door (72px gap).

   entry: a south-wall entrance (art base sits on the map edge). */

var P9_DOORS = [

  {cx:172, cy:304, axis:"h", kind:"s"}, {cx:582, cy:304, axis:"h", kind:"s"},

  {cx:962, cy:304, axis:"h", kind:"s"}, {cx:1352, cy:304, axis:"h", kind:"d"},

  {cx:172, cy:644, axis:"h", kind:"s"}, {cx:582, cy:644, axis:"h", kind:"d"},

  {cx:962, cy:644, axis:"h", kind:"s"}, {cx:1329, cy:644, axis:"h", kind:"s"},

  {cx:384, cy:168, axis:"v", kind:"s"}, {cx:384, cy:828, axis:"v", kind:"d"},

  {cx:768, cy:168, axis:"v", kind:"s"}, {cx:768, cy:474, axis:"v", kind:"s"},

  {cx:768, cy:828, axis:"v", kind:"d"},

  {cx:1152, cy:168, axis:"v", kind:"d"}, {cx:1152, cy:474, axis:"v", kind:"s"},

  {cx:568, cy:1034, axis:"h", kind:"d", entry:true}

];

function p9DoorAt(d){

  var cx = d.x + d.w / 2, cy = d.y + d.h / 2, best = null, bd = 1e9;

  for(var i = 0; i < P9_DOORS.length; i++){

    var p = P9_DOORS[i], dd = Math.abs(p.cx - cx) + Math.abs(p.cy - cy);

    if(dd < bd){ bd = dd; best = p; }

  }

  return bd <= 10 ? best : null;

}

/* palette sampled from wall_horizontal.webp */

var P9_CREAM = "#cfc3a8", P9_CREAM_HI = "#e7ddc6", P9_RAIL = "#8f8474",

    P9_NAVY = "#16283f", P9_NAVY_DK = "#0e1c30";

var P9_FRONT = [];

function p9Post(x, y, w, h){ /* finished end post: cream over navy */

  ctx.fillStyle = P9_NAVY_DK; ctx.fillRect(x - 1, y - 1, w + 2, h + 2);

  ctx.fillStyle = P9_CREAM; ctx.fillRect(x, y, w, Math.round(h * 0.66));

  ctx.fillStyle = P9_CREAM_HI; ctx.fillRect(x, y, w, Math.min(4, h));

  ctx.fillStyle = P9_RAIL; ctx.fillRect(x, y + Math.round(h * 0.66) - 3, w, 3);

  ctx.fillStyle = P9_NAVY; ctx.fillRect(x, y + Math.round(h * 0.66), w, h - Math.round(h * 0.66));

}

function p9WallPaint(m){

  P9_FRONT.length = 0;

  var cellBlock = [];

  (m.decors || []).forEach(function(d){ if(d.t === "cells") cellBlock.push(d); });

  var pb = player.y + player.h;

  (m.walls || []).forEach(function(w){

    var horiz = w.w >= 100 && w.h <= 32, vert = w.h >= 100 && w.w <= 24;

    if((!horiz && !vert) || w.x <= 0 || w.y <= 0 || w.x + w.w >= m.w || w.y + w.h >= m.h) return;

    /* the cells test runs on the wall's centre line, not the thickened

       rect: the y=644 divider's band overlaps the cell block's apron,

       but the barred front (y=736) is the only wall inside it */

    if(b2HitsAny({x: w.x, y: w.y + w.h / 2 - 4, w: w.w, h: 8}, cellBlock)) return;

    var cy = w.y + w.h / 2, cx = w.x + w.w / 2, x, y;

    if(horiz){

      var top = cy - 24;

      var leftCap = w.x > 12, rightCap = (w.x + w.w) < (m.w - 12);

      ctx.save();

      ctx.beginPath(); ctx.rect(w.x, top, w.w, 48); ctx.clip();

      for(x = w.x; x < w.x + w.w; x += 96)

        ctx.drawImage(P9.wallH, 0, 0, Math.min(96, w.x + w.w - x), 48, Math.round(x), Math.round(top), Math.min(96, w.x + w.w - x), 48);

      if(leftCap && w.w >= 260 && p9Ok(P9.wallEnd)){

        ctx.save(); ctx.translate(Math.round(w.x + 96), Math.round(top)); ctx.scale(-1, 1);

        ctx.drawImage(P9.wallEnd, 0, 0); ctx.restore();

      }

      if(rightCap && w.w >= 96 && p9Ok(P9.wallEnd))

        ctx.drawImage(P9.wallEnd, Math.round(w.x + w.w - 96), Math.round(top));

      ctx.restore();

      if(leftCap && w.w < 260) p9Post(w.x - 5, top, 10, 48);

      if(rightCap && w.w < 96) p9Post(w.x + w.w - 5, top, 10, 48);

      /* Jay behind this wall (north side, feet at the wall line):

         queue the tiles he overlaps for the faded front-pass */

      if(!isDriving() && pb <= w.y + w.h + 2 && pb > w.y - 24 &&

         player.x + player.w > w.x && player.x < w.x + w.w){

        for(x = w.x; x < w.x + w.w; x += 96){

          if(x + 96 > player.x - 24 && x < player.x + player.w + 24)

            P9_FRONT.push({im: P9.wallH, dx: x, dy: top, sw: Math.min(96, w.x + w.w - x)});

        }

      }

    } else {

      /* vertical divider: wall_vertical.webp stretched over a palette

         body (bold-walls pass — see header). The body keeps the

         established cream-west / navy-east split; the art is tiled

         from the piece's uniform cream band (source rows 12..60,

         where both edge slivers run unbroken) and stretched across

         the 32px width, so its cap shading and panel strokes finish

         both edges of the wall. */

      var lx = cx - 16;

      ctx.fillStyle = P9_NAVY_DK; ctx.fillRect(lx - 2, w.y, 36, w.h);

      ctx.fillStyle = P9_CREAM; ctx.fillRect(lx, w.y, 17, w.h);

      ctx.fillStyle = P9_CREAM_HI; ctx.fillRect(lx, w.y, 3, w.h);

      ctx.fillStyle = P9_RAIL; ctx.fillRect(lx + 15, w.y, 2, w.h);

      ctx.fillStyle = P9_NAVY; ctx.fillRect(lx + 17, w.y, 15, w.h);

      if(p9Ok(P9.wallV)){

        for(y = w.y; y < w.y + w.h; y += 48)

          ctx.drawImage(P9.wallV, 0, 12, 24, 48, Math.round(lx), Math.round(y), 32, Math.min(48, w.y + w.h - y));

      }

      ctx.fillStyle = "rgba(0,0,0,.28)";

      for(y = w.y + 47; y < w.y + w.h - 4; y += 48) ctx.fillRect(lx + 1, y, 30, 2);

      /* cap posts on gap-side ends only (ends butting a horizontal

         divider or the outer wall need none) */

      if(w.y !== 12 && w.y !== 308 && w.y !== 648) p9Post(cx - 16, w.y - 5, 32, 10);

      if((w.y + w.h) !== 300 && (w.y + w.h) !== 640 && (w.y + w.h) !== 1028) p9Post(cx - 16, w.y + w.h - 5, 32, 10);

    }

  });

  p9Junctions(m);

}

/* Junction dressing (bold-walls pass): wall_t.webp at T junctions —

   stretched to 112x64 so its 48px arm lands exactly on the horizontal

   band and its stem on the vertical band — doubled stem-to-stem at

   crossings, with the four 64x64 corner pieces at 32x32, elbows on

   the crossing centre and arms inside the bands, finishing each

   crossing as one connected joint. Arms are detected from the wall

   rects themselves, so the dressing cannot drift from the collision.

   Corner sources are cropped to rows 0..62: the bottom row of the

   south pieces carries a stray floor-coloured line. */

function p9Junctions(m){

  function armV(cx, y){

    for(var i = 0; i < m.walls.length; i++){ var w = m.walls[i];

      if(w.w <= 24 && w.h >= 100 && Math.abs(w.x + w.w / 2 - cx) <= 2 && y >= w.y && y < w.y + w.h) return true; }

    return false;

  }

  function armH(x, cy){

    for(var i = 0; i < m.walls.length; i++){ var w = m.walls[i];

      if(w.h <= 32 && w.w >= 100 && Math.abs(w.y + w.h / 2 - cy) <= 2 && x >= w.x && x < w.x + w.w) return true; }

    return false;

  }

  [304, 644].forEach(function(cy){

    [384, 768, 1152].forEach(function(cx){

      var N = armV(cx, cy - 40), S = armV(cx, cy + 40),

          W = armH(cx - 40, cy), E = armH(cx + 40, cy);

      if(W && E && N && S){

        if(p9Ok(P9.wallT)){

          ctx.drawImage(P9.wallT, cx - 56, cy - 40, 112, 64);

          ctx.save(); ctx.translate(cx, cy); ctx.scale(1, -1);

          ctx.drawImage(P9.wallT, -56, -40, 112, 64); ctx.restore();

        }

        if(p9Ok(P9.cornerSE)) ctx.drawImage(P9.cornerSE, 0, 0, 64, 63, cx - 32, cy - 32, 32, 32);

        if(p9Ok(P9.cornerSW)) ctx.drawImage(P9.cornerSW, 0, 0, 64, 63, cx, cy - 32, 32, 32);

        if(p9Ok(P9.cornerNE)) ctx.drawImage(P9.cornerNE, 0, 0, 64, 63, cx - 32, cy, 32, 32);

        if(p9Ok(P9.cornerNW)) ctx.drawImage(P9.cornerNW, 0, 0, 64, 63, cx, cy, 32, 32);

      } else if(W && E && N !== S && p9Ok(P9.wallT)){

        if(N) ctx.drawImage(P9.wallT, cx - 56, cy - 40, 112, 64);

        else { ctx.save(); ctx.translate(cx, cy); ctx.scale(1, -1);

               ctx.drawImage(P9.wallT, -56, -40, 112, 64); ctx.restore(); }

      }

    });

  });

}

var p9PrevWallSkin = b2WallSkin;

b2WallSkin = function(m){

  if(state.map === "station" && p9Ok(P9.wallH)){ p9WallPaint(m); return; }

  p9PrevWallSkin(m);

};

function p9DrawDoor(door){

  var im = door.kind === "d" ? P9.doorD : P9.doorS;

  if(door.axis === "v"){

    /* Vertical doorway: the front-facing door art does not rotate

       cleanly (its dark passage becomes a slot across the walkway),

       so the doorway is built from parts — the threshold plate

       rotated into the wall plane, plus the art's own open leaf

       (a 1:1 source crop, never rescaled) swung flat against the

       wall segment beside the gap, outside the walking path. Double

       doors get the double art's second leaf on the far side. */

    ctx.save();

    ctx.translate(Math.round(door.cx), Math.round(door.cy));

    ctx.rotate(-Math.PI / 2);

    if(p9Ok(P9.thresh)) ctx.drawImage(P9.thresh, -40, -6);

    ctx.restore();

    var gh = door.kind === "d" ? 36 : 26;

    ctx.drawImage(im, 6, 4, 26, 72, Math.round(door.cx - 13), Math.round(door.cy - gh - 70), 26, 72);

    if(door.kind === "d")

      ctx.drawImage(im, 96, 4, 26, 72, Math.round(door.cx - 13), Math.round(door.cy + gh - 2), 26, 72);

    return;

  }

  var pc = door.kind === "d" ? 65 : 46; /* passage centre in art coords */

  var base = door.entry ? 6 : 28;       /* art base below the wall line */

  ctx.save();

  ctx.translate(Math.round(door.cx), Math.round(door.cy));

  if(p9Ok(P9.thresh)) ctx.drawImage(P9.thresh, -40, -6);

  ctx.drawImage(im, -pc, base - 80);

  ctx.restore();

}

var drawDecorP9Prev = drawDecor;

drawDecor = function(d, t){

  if(state.map === "station" && d.t === "rug9"){

    if(p9Ok(P9.rug)) ctx.drawImage(P9.rug, d.x, d.y);

    return;

  }

  if(state.map === "station" && d.t === "strip"){

    var m = curMap();

    var stamp = state.map + "@" + t;

    if(B2_SKIN_STAMP !== stamp){ B2_SKIN_STAMP = stamp; b2WallSkin(m); }

    var door = p9DoorAt(d);

    var dim = door ? (door.kind === "d" ? P9.doorD : P9.doorS) : null;

    if(door && p9Ok(dim)){ p9DrawDoor(door); return; }

  }

  drawDecorP9Prev(d, t);

};

/* ---- faded front-pass: wall tiles Jay stands behind ---- */

var drawP9Prev = draw;

draw = function(t){

  drawP9Prev(t);

  if(P9_FRONT.length && state.map === "station"){

    ctx.save();

    if(!(typeof csCam !== "undefined" && csCam && csCam.on) && effZoom() !== 1) ctx.scale(effZoom(), effZoom());

    ctx.translate(-cam.x, -cam.y);

    ctx.globalAlpha = 0.45;

    P9_FRONT.forEach(function(a){

      ctx.drawImage(a.im, 0, 0, a.sw, 48, Math.round(a.dx), Math.round(a.dy), a.sw, 48);

    });

    ctx.restore();

    P9_FRONT.length = 0;

  }

};



