/* ---- save migration: a save written on the old street can leave

   Jay or Unit 9 inside a new house footprint or fence line ---- */

function mcMigrateSave(){

  try{

    if(car.map === "residential" && carCollidesAt(car.x, car.y, car.angle, "residential")){

      /* The grounds pass further down this file EXTENDS this map's

         south edge (h 1000 -> 1160) after this migration has already

         run, so a car legitimately parked in the new southern strip

         (e.g. south of the Maple Court bottom row) is condemned here

         by carCollidesAt's boundary clause alone and would be hauled

         back to the road on every reload. Only relocate when the car

         is condemned by something other than that not-yet-extended

         south edge: the other three boundaries, or a real solid. */

      var mR = MAPS.residential, halfL = CAR_LEN / 2, condemned = true;

      if(car.y > mR.h - halfL && car.y <= 1160 - halfL && car.x >= halfL && car.x <= mR.w - halfL && car.y >= halfL){

        condemned = false;

        for(var si = 0; si < mR.solids.length; si++){

          if(obbHitsRect(car.x, car.y, car.angle, mR.solids[si])){ condemned = true; break; }

        }

      }

      if(condemned){ car.x = 750; car.y = 524; car.angle = 0; car.speed = 0; }

    }

    if(state.map === "residential" && !isDriving() && playerBoxHits(player.x, player.y)){

      var cand = [[737,378],[737,470],[227,378],[1247,378],[737,650]];

      for(var i = 0; i < cand.length; i++){

        if(!playerBoxHits(cand[i][0], cand[i][1])){ player.x = cand[i][0]; player.y = cand[i][1]; break; }

      }

    }

  }catch(e){}

}

mcMigrateSave();



