function mtPlaque(cx, y, text, fs){

  ctx.save();

  ctx.font = "700 " + (fs || 19) + "px 'Barlow Condensed', sans-serif";

  var w = Math.ceil(ctx.measureText(text).width) + 26;

  ctx.fillStyle = "#16283f"; rr(cx - w / 2, y - 13, w, 26, 5); ctx.fill();

  ctx.strokeStyle = "#c9a227"; ctx.lineWidth = 1.6; rr(cx - w / 2, y - 13, w, 26, 5); ctx.stroke();

  ctx.fillStyle = "#f4e9c8"; ctx.textAlign = "center"; ctx.textBaseline = "middle";

  ctx.fillText(text, cx, y + 1);

  ctx.textBaseline = "alphabetic";

  ctx.restore();

}



/* ---- painter: pack buildings, patio, props, motel sign, fences -- */

var drawDecorMTPrev = drawDecor;

drawDecor = function(d, t){

  if(state.map === "midtown"){

    if(d.t === "mtbldg"){

      var im = MT_IMG[d.img];

      ctx.save();

      if(mtReady(im)){

        if(!d.__raster){var cv=document.createElement('canvas');cv.width=Math.ceil(d.dw);cv.height=Math.ceil(d.dh);var g=cv.getContext('2d');g.drawImage(im,0,0,cv.width,cv.height);d.__raster=cv;}

        var B=MT_BODY[d.img],scale=d.bw/B.bw;

        ctx.drawImage(d.__raster,Math.round(d.dx),Math.round(d.btop-B.by*scale));

      }

      ctx.restore();

      if(d.img !== "motel") mtPlaque(d.cx, d.btop + d.bh * (d.flip ? 0.46 : 0.56), d.name);

      return;

    }

    if(d.t === "mtpatio"){

      var pim2 = MT_IMG.patio;

      if(mtReady(pim2)){ ctx.save(); ctx.drawImage(pim2, Math.round(d.dx), Math.round(d.dyTop), Math.round(d.dw), Math.round(d.dh)); ctx.restore(); }

      return;

    }

    if(d.t === "mtprop"){

      var pim = MT_EXT[d.img];

      if(pim && mtReady(pim)){ ctx.save(); ctx.drawImage(pim, Math.round(d.x), Math.round(d.y)); ctx.restore(); }

      return;

    }

    if(d.t === "mtfence"){

      var fim = MT_EXT.fenceH;

      if(fim && mtReady(fim)){

        ctx.save();

        ctx.beginPath(); ctx.rect(d.x, d.y, d.w, 32); ctx.clip();

        for(var fx = d.x - 25; fx < d.x + d.w; fx += 48) ctx.drawImage(fim, fx, d.y);

        ctx.restore();

      }

      return;

    }

    if(d.t === "mtsign"){

      ctx.save();

      ctx.fillStyle = "#5e4630"; ctx.fillRect(d.x - 64, d.y + 24, 6, 26); ctx.fillRect(d.x + 58, d.y + 24, 6, 26);

      ctx.fillStyle = "#16283f"; rr(d.x - 78, d.y, 156, 28, 5); ctx.fill();

      ctx.strokeStyle = "#c9a227"; ctx.lineWidth = 1.8; rr(d.x - 78, d.y, 156, 28, 5); ctx.stroke();

      ctx.fillStyle = "#f4e9c8"; ctx.font = "700 16px 'Barlow Condensed', sans-serif"; ctx.textAlign = "center"; ctx.textBaseline = "middle";

      ctx.fillText("MIDTOWN MOTEL", d.x, d.y + 15);

      ctx.textBaseline = "alphabetic";

      ctx.restore();

      return;

    }

  }

  return drawDecorMTPrev(d, t);

};



