/* ---- save migration: a save written on the old street can leave

   Jay or Unit 9 inside a new building footprint or lot line ---- */

function mtMigrateSave(){

  try{

    if(car.map === "midtown" && carCollidesAt(car.x, car.y, car.angle, "midtown")){

      car.x = 400; car.y = 638; car.angle = 0; car.speed = 0;

    }

    if(state.map === "midtown" && !isDriving() && playerBoxHits(player.x, player.y)){

      var cand = [[300,462],[584,362],[1080,462],[400,718],[1700,718]];

      for(var i = 0; i < cand.length; i++){

        if(!playerBoxHits(cand[i][0], cand[i][1])){ player.x = cand[i][0]; player.y = cand[i][1]; break; }

      }

    }

  }catch(e){}

}

mtMigrateSave();



