/* ================================================================

   FLUIDITY PASS — asset warm-up + transition warming + perf stats

   (2026-10-14). Every image registry in the game starts fetching at

   boot, but a fetched image is not a decoded one: the first visit to

   a district used to pay full PNG/JPEG decode (and, for Jay, Brooks

   and Unit 9, the one-time sheet slicing) inside a single frame,

   which showed up as a hitch on scene transitions. At idle, this

   pass decodes every registered image and pre-slices the sheets;

   goTo / carGoTo additionally warm the destination district's set

   during the transition fade, so the first frame there is clean.

   ================================================================ */

(function(){

  function warmDecode(im){ if(im && typeof im.decode === "function"){ var p = im.decode(); if(p && p.catch) p.catch(function(){}); } }

  function warmRegistry(reg){ if(!reg) return; Object.keys(reg).forEach(function(k){ warmDecode(reg[k]); }); }

  var warmTries = 0;

  function warmAll(){

    warmTries++;

    try{

      warmRegistry(typeof W1 !== "undefined" ? W1 : null);

      warmRegistry(typeof EXT_IMG !== "undefined" ? EXT_IMG : null);

      warmRegistry(typeof MC_IMG !== "undefined" ? MC_IMG : null);

      warmRegistry(typeof MT_IMG !== "undefined" ? MT_IMG : null);

      warmRegistry(typeof P9 !== "undefined" ? P9 : null);

      warmRegistry(typeof BROOKS !== "undefined" ? BROOKS : null);

      if(typeof DAWN_PLATES !== "undefined") Object.keys(DAWN_PLATES).forEach(function(k){ warmDecode(DAWN_PLATES[k].img); });

      warmDecode(document.getElementById("mapImg"));

      /* pre-slice the frame sheets (the smear fix's offscreen canvases)

         so the slicing cost is paid here, not on first close-up */

      var sliced = true;

      if(typeof extCarFrames === "function"){ if(!extCarFrames()) sliced = false; }

      /* sheets still downloading: retry a couple of times, then stop */

      if(!sliced && warmTries < 4) setTimeout(warmAll, 1200);

    }catch(e){}

  }

  if("requestIdleCallback" in window) requestIdleCallback(warmAll, { timeout: 2600 });

  else setTimeout(warmAll, 1600);



  function warmMapAssets(mapId){

    warmGameAssets(mapId);

    try{

      warmRegistry(typeof W1 !== "undefined" ? W1 : null);

      if(mapId === "plaza") warmRegistry(typeof EXT_IMG !== "undefined" ? EXT_IMG : null);

      else if(mapId === "residential") warmRegistry(typeof MC_IMG !== "undefined" ? MC_IMG : null);

      else if(mapId === "midtown") warmRegistry(typeof MT_IMG !== "undefined" ? MT_IMG : null);

      else if(mapId === "station"){ warmRegistry(typeof P9 !== "undefined" ? P9 : null); warmRegistry(typeof BROOKS !== "undefined" ? BROOKS : null); }

    }catch(e){}

  }

  if(typeof goTo === "function"){

    var goToPrev = goTo;

    goTo = function(mapId, x, y){ warmMapAssets(mapId); return goToPrev(mapId, x, y); };

  }

  if(typeof carGoTo === "function"){

    var carGoToPrev = carGoTo;

    carGoTo = function(destMap){ warmMapAssets(destMap); return carGoToPrev(destMap); };

  }



  /* Measured frame stats for the test handle: the ring buffer the

     main loop fills every rAF (last 600 frames). */

  if(window.ROOKIE){

    window.ROOKIE.perfStats = function(){

      var a = (typeof perfRing !== "undefined" ? perfRing.slice() : []).sort(function(x, y){ return x - y; });

      if(!a.length) return { frames: 0 };

      var sum = 0; for(var i = 0; i < a.length; i++) sum += a[i];

      var mean = sum / a.length;

      function q(p){ return Math.round(a[Math.min(a.length - 1, Math.floor(p * a.length))] * 10) / 10; }

      return {

        sampled: a.length,

        totalFrames: (typeof perfFramesTotal !== "undefined" ? perfFramesTotal : a.length),

        avgFps: Math.round(1000 / mean * 10) / 10,

        meanMs: Math.round(mean * 100) / 100, p50Ms: q(0.5), p95Ms: q(0.95), p99Ms: q(0.99),

        maxMs: Math.round(a[a.length - 1] * 10) / 10,

        longFrames: (typeof perfLongFrames !== "undefined" ? perfLongFrames : 0)

      };

    };

    window.ROOKIE.clearHeldInputs = function(){ if(typeof clearHeldInputs === "function") clearHeldInputs(); };

    window.ROOKIE.heldInputs = function(){

      return { keys: { up: !!keys.up, down: !!keys.down, left: !!keys.left, right: !!keys.right },

               drive: { up: !!driveKeys.up, down: !!driveKeys.down, left: !!driveKeys.left, right: !!driveKeys.right },

               space: !!window.__carSpace, animMoving: !!player.animMoving, walkPhase: Math.round(player.walkPhase * 100) / 100 };

    };

  }

})();



