/* Dedicated cinematic two-shot interview; original Maya finding remains authoritative. */

(function(){

 var panel=document.createElement('div');panel.id='hcInterviewMode';panel.className='hc-interview-mode';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Interview Maya Torres');panel.style.display='none';document.body.appendChild(panel);

 var active=false,timeline=false,support=false,response='',speaker='MAYA TORRES',previous=null;

 function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

 function render(){panel.innerHTML='<div class="hc-interview-shell"><header><span>INTERVIEW · MAYA TORRES</span><button id="hcInterviewExit" type="button">Leave ×</button></header><div class="hc-interview-art" role="img" aria-label="Jay and Maya seated across an interview table"></div><section class="hc-interview-dialogue"><b>'+speaker+'</b><p aria-live="polite">'+esc(response)+'</p><div class="hc-interview-actions"><button id="hcInterviewTimeline">Ask about the timeline</button><button id="hcInterviewSupport">Ask about the handoff</button><button id="hcInterviewEvidence">Present collected evidence</button><button id="hcInterviewNotes">Review notes</button><button id="hcInterviewRecord" '+(!state.findings.witness&&!(timeline&&support)?'disabled':'')+'>'+(state.findings.witness?'Statement recorded · Return':'Record statement')+'</button></div></section></div>';

 document.getElementById('hcInterviewExit').onclick=close;document.getElementById('hcInterviewTimeline').onclick=function(){ask('timeline');};document.getElementById('hcInterviewSupport').onclick=function(){ask('support');};document.getElementById('hcInterviewEvidence').onclick=function(){ask('evidence');};document.getElementById('hcInterviewNotes').onclick=function(){ask('notes');};document.getElementById('hcInterviewRecord').onclick=record;}

 function open(){if(active)return;previous={map:state.map,x:player.x,y:player.y};active=true;timeline=false;support=false;speaker='MAYA TORRES';response=state.findings.witness?'My statement is already on record. The transfer pouch was left in Intake Tray B.':'You’re looking for the drive? I can tell you about the handoff. I never saw a drive get stolen.';panel.style.display='flex';document.body.classList.add('hc-interview-active');keys.up=keys.down=keys.left=keys.right=false;render();}

 function close(){active=false;panel.style.display='none';document.body.classList.remove('hc-interview-active');keys.up=keys.down=keys.left=keys.right=false;}

 function ask(kind){if(!active)return false;speaker='MAYA TORRES';if(kind==='timeline'){timeline=true;response=FINDINGS.witness.text;}else if(kind==='support'){support=true;response='It was a transfer, not a theft. The paperwork had stalled. Check Intake Tray B for the pouch, and compare that with the access records before reaching a conclusion.';}else if(kind==='evidence'){speaker='CASE FILE';var list=[];['tag','records','drive'].forEach(function(k){if(state.findings[k])list.push(FINDINGS[k].title+': '+FINDINGS[k].text);});response=list.length?list.join('\n\n'):'You have no collected evidence to present yet. You can still ask Maya about the timeline and handoff.';}else if(kind==='notes'){speaker='JAY · NOTES';response='Timeline discussed: '+(timeline?'yes':'not yet')+'. Handoff discussed: '+(support?'yes':'not yet')+'. '+(state.findings.witness?'Maya’s statement is already recorded.':'Save the witness story after both questions. Leaving now keeps your existing case progress.');}else return false;render();return true;}

 function record(){if(!active)return false;if(state.findings.witness){close();return true;}if(!(timeline&&support))return false;close();completeFinding('witness');return true;}

 doWitness=open;var overlays=overlayOpen;overlayOpen=function(){return active||overlays();};

 document.addEventListener('keydown',function(e){if(active&&e.code==='Escape'){e.preventDefault();close();}});

 window.HARBOR.cinematicInterview={open:open,close:close,ask:ask,record:record,isOpen:function(){return active;},origin:function(){return previous;}};

})();



