 Object.keys(spec).forEach(function(k){var im=new Image();assignGameAsset(im,'assets/precinct-cast/'+spec[k].file);cast[k]={image:im,frames:null};});

 function identity(name,isPlayer){if(isPlayer)return null;var n=String(name||'').toUpperCase();if(n.indexOf('BROOKS')>=0)return'brooks';if(n.indexOf('CHEN')>=0)return'chen';if(n.indexOf('RIVERA')>=0)return'rivera';if(n.indexOf('OKAFOR')>=0)return'okafor';if(n.indexOf('LANE')>=0)return'lane';if(n.indexOf('PARK')>=0)return'park';if(n.indexOf('DIAZ')>=0)return'diaz';if(n.indexOf('FERRIS')>=0)return'ferris';if(/OFFICER|OFCR|POLICE/.test(n))return'diaz';return null;}

 function frames(key){var s=cast[key],m=spec[key];if(!s)return null;if(s.frames)return s.frames;var im=s.image;if(!im||!im.complete||!im.naturalWidth)return null;var scale=(m.heightInWorld||66)/m.frames[0].rect[3];s.frames=m.frames.map(function(f,i){var mirrored=key==='lane'&&i===8;var r=(mirrored?m.frames[11]:f).rect,c=document.createElement('canvas');c.width=Math.max(1,Math.round(r[2]*scale));c.height=Math.max(1,Math.round(r[3]*scale));var g=c.getContext('2d');g.imageSmoothingEnabled=false;if(mirrored){g.translate(c.width,0);g.scale(-1,1);}g.drawImage(im,r[0],r[1],r[2],r[3],0,0,c.width,c.height);return c;});s.image=null;builds++;return s.frames;}

