 characterRenderers.add('person','character-variety',20,function(x,y,color,hat,name,dir,isPlayer,hide,bob,phase){var key=identity(name,isPlayer);if(key&&paint(key,x,y,dir,bob,phase)){if(!hide&&name&&Math.hypot(player.x-x,player.y-y)<100)labelPill(name,x,y-72,11);return true;}return false;});

