 var aliases={BROOKS:'brooks',CHEN:'chen',PARK:'park',RIVERA:'rivera',DIAZ:'diaz',LANE:'lane',OKAFOR:'okafor',FERRIS:'ferris',MAYA:'maya',OMAR:'omar',LUCIA:'lucia',VOSS:'voss',DANA:'dana',REED:'reed',ORTIZ:'ortiz',REYES:'reyes',LINDQVIST:'ana',KOVAC:'bruno',AMES:'ames',AMARI:'dev',KOWALSKI:'dot',HALLORAN:'gus',PIERCE:'hank',FROST:'mabel',PETROV:'petrov',ALMEIDA:'almeida',QUINT:'quint',IBARRA:'ibarra',KIM:'kim','OLD TOM':'tom',LINDGREN:'pete',NAIR:'priya',MARCHETTI:'sal',ADEYEMI:'sam',VALE:'tessa',KROL:'wanda',INNKEEPER:'innkeeper','CAFÉ OWNER':'cafeowner','CAFE OWNER':'cafeowner',FISHMONGER:'fishmonger'};

