 function mutate(d){if(d.index===undefined)return function(){};var ref=m.decors[d.index],old={};if(d.type==='building'){['bx','btop','bw','bh','cx','dy','doorX'].forEach(function(k){old[k]=ref[k];});var frac=(ref.doorX-ref.bx)/ref.bw;ref.bx=d.x;ref.btop=d.y;ref.bw=d.w;ref.bh=d.h;ref.cx=d.x+d.w/2;ref.dy=d.y+d.h;ref.doorX=d.x+d.w*frac;}else{['x','y','w','dy'].forEach(function(k){old[k]=ref[k];});ref.x=d.x;ref.y=d.y;ref.w=d.w;ref.dy=d.y;}return function(){Object.keys(old).forEach(function(k){ref[k]=old[k];});};}

