 function render(){if(!active)return;eye.x=Math.max(0,Math.min(Math.max(0,m.w-960/eye.z),eye.x));eye.y=Math.max(0,Math.min(Math.max(0,m.h-640/eye.z),eye.y));var saved={ctx:ctx,canvas:canvas,VW:VW,VH:VH,zoom:worldZoom,cam:cam,fit:fitGameView,update:updateCam,ground:drawCityGround},restore=[];try{items.forEach(function(d){restore.push(mutate(d));});ctx=ec;canvas=cv;VW=960;VH=640;worldZoom=eye.z;cam={x:eye.x,y:eye.y};fitGameView=function(){};updateCam=function(){};var g=drawCityGround;drawCityGround=function(t){g(t);patches();};var extra=items.filter(function(d){return d.index===undefined&&!isGround(d);}).map(added);extra.forEach(function(d){m.decors.push(d);});try{draw(0);}finally{m.decors.splice(m.decors.length-extra.length,extra.length);}ec.save();ec.scale(eye.z,eye.z);ec.translate(-eye.x,-eye.y);if(collision){ec.strokeStyle='#ff6e6e';ec.lineWidth=2/eye.z;m.solids.forEach(function(s){ec.strokeRect(s.x,s.y,s.w,s.h);});ec.fillStyle='#ffe18b';m.spots.forEach(function(s){ec.beginPath();ec.arc(s.x,s.y,8/eye.z,0,7);ec.fill();});}if(selected){var b=bounds(selected);ec.strokeStyle='#64e8e0';ec.lineWidth=3/eye.z;ec.strokeRect(b.x,b.y,b.w,b.h);}ec.restore();}finally{restore.reverse().forEach(function(f){f();});ctx=saved.ctx;canvas=saved.canvas;VW=saved.VW;VH=saved.VH;worldZoom=saved.zoom;cam=saved.cam;fitGameView=saved.fit;updateCam=saved.update;drawCityGround=saved.ground;}}

 function change(x,y,w){if(!selected)return;w=Math.min(w,700*selected.w/selected.h);remember();selected.x=Math.max(0,Math.min(m.w,x));selected.y=Math.max(0,Math.min(m.h,y));var factor=w/selected.w;selected.w=w;selected.h*=factor;saveDraft();select(selected.id);}

 function open(){if(active)return;if(state.map!=='midtown'){toast('Visit Midtown to use its map workshop.');return false;}if(csActive||isDriving()){toast('Stop and leave the car before editing.');return false;}base=collect();items=copy(base);try{var draft=localStorage.getItem(key);if(draft)items=valid(JSON.parse(draft));}catch(e){msg('Saved draft belongs to another build; starting fresh.');}undo=[];origin={x:player.x,y:player.y};eye={x:0,y:0,z:Math.min(960/m.w,640/m.h)};active=true;root.style.display='flex';if(typeof clearHeldInputs==='function')clearHeldInputs();list();select(items[0]?.id);msg('Draft mode · no changes applied.');return true;}

 function close(){active=false;root.style.display='none';if(typeof clearHeldInputs==='function')clearHeldInputs();}

 // Apply existing items and update their collision footprints and entrance markers together.

 function apply(){var saved=copy(base);var changes=[];items.forEach(function(d){var b=base.find(function(b){return b.id===d.id;});if(!b)return;var ref=m.decors[d.index],old=bounds(b),newB=bounds(d);if(b.type==='building'){[m.solids,m.pedSolids].forEach(function(list){list.forEach(function(s){if(Math.abs(s.x-old.x-4)<2&&Math.abs(s.y-old.y-4)<2&&Math.abs(s.w-old.w+8)<2){changes.push({s:s,old:copy(s)});s.x=newB.x+4;s.y=newB.y+4;s.w=newB.w-8;s.h=newB.h-4;}});});var spot=m.spots.find(function(s){return Math.abs(s.x-ref.doorX)<2&&Math.abs(s.y-(ref.btop+ref.bh+16))<25;});if(spot){changes.push({s:spot,old:copy(spot)});var frac=(ref.doorX-ref.bx)/ref.bw;spot.x=d.x+d.w*frac;spot.y=d.y+d.h+16;}}else{[m.solids,m.pedSolids].forEach(function(list){list.forEach(function(s){if(Math.abs(s.y-(b.y-10))<1&&Math.abs(s.x+s.w/2-b.x)<1){changes.push({s:s,old:copy(s)});s.x=d.x-s.w/2;s.y=d.y-10;if(d.type!=='tree')s.w=d.w*.82;}});});}mutate(d);});

 var extras=[];items.filter(function(d){return d.index===undefined&&!isGround(d);}).forEach(function(d){var cw=d.type==='tree'?16:d.w*.82,s={x:d.x-cw/2,y:d.y-10,w:cw,h:12};m.decors.push(added(d));m.solids.push(s);m.pedSolids.push(s);extras.push(s);});

 var blocked=playerBoxHits(player.x,player.y)||m.spots.some(function(p){return m.solids.some(function(s){return p.x>s.x&&p.x<s.x+s.w&&p.y>s.y&&p.y<s.y+s.h;});});

 if(blocked){saved.forEach(mutate);changes.forEach(function(c){Object.assign(c.s,c.old);});if(extras.length){m.decors.splice(m.decors.length-extras.length,extras.length);m.solids=m.solids.filter(function(s){return extras.indexOf(s)<0;});m.pedSolids=m.pedSolids.filter(function(s){return extras.indexOf(s)<0;});}msg('Cannot apply: an object blocks Jay or an interaction point. Move it away.');return false;}

 appliedGround=items.filter(isGround).map(copy);base=collect();items=copy(base).concat(appliedGround);undo=[];saveDraft();list();select(items[0]?.id);msg('Applied locally. Export JSON to share; refresh restores the shipped map.');return true;}

 var appliedGround=[],ground=drawCityGround;drawCityGround=function(t){ground(t);if(state.map==='midtown'&&!active){var savedItems=items;items=appliedGround;patches();items=savedItems;}};

 var oldOverlay=overlayOpen;overlayOpen=function(){return active||oldOverlay();};

 el('edClose').onclick=close;el('edObject').onchange=function(){select(this.value);};el('edMove').onclick=function(){var x=Number(el('edX').value),y=Number(el('edY').value),w=Number(el('edW').value);if([x,y,w].every(Number.isFinite)&&w>=16&&w<=700)change(x,y,w);};el('edUndo').onclick=function(){if(undo.length){items=undo.pop();saveDraft();list();select(items[0]?.id);}};el('edReset').onclick=function(){remember();items=copy(base);saveDraft();list();select(items[0]?.id);};el('edCollision').onclick=function(){collision=!collision;render();};el('edApply').onclick=apply;

 el('edAdd').onclick=function(){remember();var k=el('edAddType').value,w=k==='tree'?120:k==='bench'?76:64,h=isGround({type:k})?w:w*window.HARBOR.landscape.spec[k].rect[3]/window.HARBOR.landscape.spec[k].rect[2];var d={id:'added:'+Date.now()+':'+items.length,type:k,name:k,x:Math.round((eye.x+480/eye.z)/8)*8,y:Math.round((eye.y+320/eye.z)/8)*8,w:w,h:h};items.push(d);saveDraft();list();select(d.id);};el('edDelete').onclick=function(){if(selected&&selected.index===undefined){remember();items=items.filter(function(d){return d!==selected;});saveDraft();list();select(items[0]?.id);}};

 el('edExport').onclick=function(){var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data(),null,2)],{type:'application/json'}));a.download='ROOKIE-Midtown-layout.json';a.click();setTimeout(function(){URL.revokeObjectURL(a.href);},1000);msg('Layout exported.');};el('edImport').onchange=async function(){try{if(!this.files?.[0])return;if(this.files[0].size>500000)throw Error('File is too large.');var value=valid(JSON.parse(await this.files[0].text()));remember();items=value;saveDraft();list();select(items[0]?.id);msg('Imported as a draft. Inspect before applying.');}catch(e){msg(e.message);}this.value='';};

 function pan(x,y){eye.x=Math.max(0,Math.min(m.w-100,eye.x+x/eye.z));eye.y=Math.max(0,Math.min(m.h-100,eye.y+y/eye.z));render();}el('edLeft').onclick=function(){pan(-160,0);};el('edRight').onclick=function(){pan(160,0);};el('edUp').onclick=function(){pan(0,-120);};el('edDown').onclick=function(){pan(0,120);};el('edZoomIn').onclick=function(){eye.z=Math.min(1.5,eye.z*1.2);render();};el('edZoomOut').onclick=function(){eye.z=Math.max(.25,eye.z/1.2);render();};

 function point(e){var r=cv.getBoundingClientRect();return{x:eye.x+(e.clientX-r.left)*960/r.width/eye.z,y:eye.y+(e.clientY-r.top)*640/r.height/eye.z};}cv.addEventListener('pointerdown',function(e){var p=point(e),hit=items.slice().reverse().find(function(d){var b=bounds(d);return p.x>=b.x&&p.x<=b.x+b.w&&p.y>=b.y&&p.y<=b.y+b.h;});if(hit){select(hit.id);remember();drag={id:e.pointerId,dx:p.x-hit.x,dy:p.y-hit.y};cv.setPointerCapture(e.pointerId);}});cv.addEventListener('pointermove',function(e){if(!drag||!selected)return;var p=point(e);selected.x=Math.max(0,Math.min(m.w,Math.round((p.x-drag.dx)/8)*8));selected.y=Math.max(0,Math.min(m.h,Math.round((p.y-drag.dy)/8)*8));render();});function drop(){if(drag){drag=null;saveDraft();select(selected?.id);}}cv.addEventListener('pointerup',drop);cv.addEventListener('pointercancel',drop);

