(function(){

 var phrases=[['corroborating witnesses','witnesses whose stories match the clues'],['corroboration','clues that support the story'],['corroborate','check against other clues'],['unsupported accusation','blaming someone without proof'],['unlawful entry','entering without permission'],['chain of custody','record of who handled the evidence'],['exculpatory','showing someone may be innocent'],['procurement','buying supplies'],['requisition','official request'],['authorization','permission'],['authorized','allowed'],['testimony','witness story'],['consented','agreed'],['redacting','leaving out'],['redact','leave out'],['indefinitely','with no end date'],['ledger','shipping book'],['manifest','supply list'],['hasp','door latch'],['intact','unbroken'],['countersigned','signed by a second person'],['perpetrator','person who did it'],['discrepancy','difference'],['verify','check'],['verified','checked'],['conclusion','answer'],['consequences','what happens next']];

 function simplify(text){if(typeof text!=='string')return text;phrases.forEach(function(p){text=text.replace(new RegExp('\\b'+p[0]+'\\b','gi'),function(found){var t=p[1];return /^[A-Z]/.test(found)?t[0].toUpperCase()+t.slice(1):t;});});return text;}

 function chunks(text){text=simplify(text);if(text.length<=240)return[text];var sentences=text.match(/[^.!?]+[.!?]+(?:[”"’']|$)?|[^.!?]+$/g)||[text],out=[],part='';sentences.forEach(function(s){s=s.trim();if(!s)return;if(part&&part.length+s.length>240){out.push(part);part='';}part+=(part?' ':'')+s;});if(part)out.push(part);return out;}

 var dialogue=setDialogue;setDialogue=function(s,t,a){return dialogue(s,simplify(t),a);};

 var lines=showLines;showLines=function(items,done){var cards=[];items.forEach(function(l){var parts=chunks(l[1]);parts.forEach(function(t,i){cards.push([l[0],t,i===parts.length-1?l[2]:undefined]);});});return lines(cards,done);};

 var choices=showChoices;showChoices=function(s,t,list){return choices(s,simplify(t),list.map(function(c){return Object.assign({},c,{label:simplify(c.label)});}));};

 Object.keys(MISSIONS).forEach(function(k){MISSIONS[k].intro=simplify(MISSIONS[k].intro);});

 window.HARBOR.language={simplify:simplify,chunks:chunks};

})();



