 function attachment(dt){var p=center(),pose=H.cover.sample('warehouse',m,p.x,p.y,angle(),dt||0);pose.halfAngle=Math.PI*.24-.35*pose.precision;pose.tool='light';return pose;}

 function angle(){return{right:0,down:Math.PI/2,left:Math.PI,up:-Math.PI/2}[player.dir]||0;}

 // Slab ray/AABB intersection, shared by vision and awareness. No visibility through cover.

 function distanceToBox(x,y,dx,dy,b,max){var lo=0,hi=max;for(var axis=0;axis<2;axis++){var p=axis?y:x,d=axis?dy:dx,a=axis?b.y:b.x,z=a+(axis?b.h:b.w);if(Math.abs(d)<1e-9){if(p<a||p>z)return max;continue;}var t1=(a-p)/d,t2=(z-p)/d;if(t1>t2){var swap=t1;t1=t2;t2=swap;}lo=Math.max(lo,t1);hi=Math.min(hi,t2);if(lo>hi)return max;}return lo>=0&&lo<max?lo:max;}

 function ray(x,y,a,max,solids){var dx=Math.cos(a),dy=Math.sin(a),d=max,boxes=solids||m.solids,ex=x+dx*max,ey=y+dy*max,minX=Math.min(x,ex),maxX=Math.max(x,ex),minY=Math.min(y,ey),maxY=Math.max(y,ey);for(var i=0;i<boxes.length;i++){var b=boxes[i];if(b.x>maxX||b.x+b.w<minX||b.y>maxY||b.y+b.h<minY)continue;d=Math.min(d,distanceToBox(x,y,dx,dy,b,d));}return d;}

 function los(a,b){var d=Math.hypot(b.x-a.x,b.y-a.y);return d<1||ray(a.x,a.y,Math.atan2(b.y-a.y,b.x-a.x),d+.1)>=d-.2;}

 function visible(x,y){var p=center(),nearD=Math.hypot(x-p.x,y-p.y);if(nearD<=82&&los(p,{x:x,y:y}))return true;var pose=attachment(),o=pose.muzzle,d=Math.hypot(x-o.x,y-o.y),a=Math.atan2(y-o.y,x-o.x),delta=Math.atan2(Math.sin(a-angle()),Math.cos(a-angle()));return d<=330&&Math.abs(delta)<=pose.halfAngle&&los(o,{x:x,y:y});}

 function vision(){var p=center(),pose=attachment(),o=pose.muzzle,key=[Math.round(o.x),Math.round(o.y),player.dir,Math.round(pose.halfAngle*100),quality].join(':');if(key===visionKey)return;visionKey=key;visionAge=0;ambient.length=beam.length=0;var count=quality==='low'?24:48;

  for(var i=0;i<=count;i++){var a=angle()-pose.halfAngle+i/count*pose.halfAngle*2,d=ray(o.x,o.y,a,330);beam.push({x:o.x+Math.cos(a)*d,y:o.y+Math.sin(a)*d});stats.rays++;}

  for(var j=0;j<count;j++){var a=j/count*Math.PI*2,d=ray(p.x,p.y,a,82);ambient.push({x:p.x+Math.cos(a)*d,y:p.y+Math.sin(a)*d});stats.rays++;}stats.visionBuilds++;

 }



 function bodyBlocked(x,y){var box={x:x-10,y:y-10,w:20,h:20};return x<22||y<22||x>m.w-22||y>m.h-22||m.solids.some(function(s){return overlaps(box,s);});}

 function makeGrid(){var step=20,w=Math.floor((m.w-40)/step)+1,h=Math.floor((m.h-40)/step)+1,solid=new Uint8Array(w*h);for(var i=0;i<solid.length;i++)solid[i]=bodyBlocked(20+i%w*step,20+Math.floor(i/w)*step)?1:0;return{w:w,h:h,solid:solid,point:function(i){return{x:20+i%w*step,y:20+Math.floor(i/w)*step};}};}

