  var nearby=[],oneBox=[null],lastKey='',age=1,candidate=0,choice=0,choiceTime=0,side=0,lateral=0,reach=barrelReach,focus=0,settle=0,px=null,py=0,pa=0,edge=null;

  var evaluated=false,stats={queries:0,probes:0,rays:0},pose={x:0,y:0,angle:0,lateral:0,reach:barrelReach,side:0,peeking:false,precision:0,halfAngle:.48,blocked:false,muzzle:{x:0,y:0},edge:null,occluders:nearby};

