  if(!owner||pending||document.fullscreenElement)return;

  var el=document.documentElement,expected=owner;if(!el.requestFullscreen)return;pending=true;

  try{Promise.resolve(el.requestFullscreen()).then(function(){ownsFullscreen=true;if(owner!==expected){restore();return;}queue(true);}).catch(function(){}).then(function(){pending=false;});}catch(e){pending=false;}

