  var desired={x:r.x+95,y:r.y+r.h-100},best=null,cost=Infinity;

  for(var dy=-160;dy<=160;dy+=8)for(var dx=-160;dx<=160;dx+=8){var x=desired.x+dx,y=desired.y+dy,d=dx*dx+dy*dy;

   if(d>=cost||x<r.x+35||y<r.y+35||x>r.x+r.w-35||y>r.y+r.h-35)continue;

   if(m.solids.some(function(b){return x-20<b.x+b.w&&x+20>b.x&&y-20<b.y+b.h&&y+20>b.y;}))continue;best={x:x,y:y};cost=d;

  }

