 var maskState=null,maskBuilds=0,maskHits=0;

 var lightMask=null,visionKey='',visionAge=1,visionAngle=0,visionX=0,visionY=0,beam=[],near=[],visionBuilds=0,rayCount=0;

 var building={t:'academyBuilding',x:220,y:280,w:240,h:200,dy:480},entry={id:'trainingDoor',x:340,y:508,label:'Enter Academy Training Center',to:{map:'training',x:147,y:2700}};

 MAPS.plaza.decors.push(building);var box={x:220,y:280,w:240,h:200};MAPS.plaza.solids.push(box);MAPS.plaza.pedSolids.push(box);

 var ui=document.createElement('section');ui.id='trainingTools';ui.setAttribute('aria-label','Academy practice controls');ui.innerHTML='<p id="trainingStatus" role="status" aria-live="polite"></p><button id="trainingOptions" type="button" aria-expanded="false" aria-label="Course options">•••</button><div class="training-actions"><button id="trainingStart" type="button">START / RESET</button><button id="trainingReload" type="button">RELOAD · R</button><button id="trainingPlan" type="button">FLOOR PLAN</button><button id="trainingFinish" type="button">FINISH RUN</button><button id="trainingExit" type="button">EXIT CENTER</button><label class="atmosphere-setting">ATMOSPHERE <select id="academyAtmosphere" aria-label="Academy atmosphere"><option value="standard">Standard</option><option value="dark">Dark</option><option value="spooky">Spooky</option></select></label></div><div id="trainingAim" role="group" aria-label="Swipe left or right to turn your view"><span class="look-hint">SWIPE TO TURN</span></div>';document.querySelector('.canvas-wrap').appendChild(ui);ui.style.display='none';var pad=document.getElementById('trainingAim'),status=document.getElementById('trainingStatus');

