 var atmosphereSelect=document.getElementById('academyAtmosphere');atmosphereSelect.value=H.atmosphere.get();atmosphereSelect.onchange=function(){H.atmosphere.set(this.value);clearHeldInputs();cancelAim();ensureAudio();};

 function coach(){return H.profiles.current()==='rosa'?'JAY':'ROSA';}

 function trainee(){return {jay:'JAY',rosa:'ROSA',kaleb:'KALEB',gigi:'GIGI',lingling:'LINGLING'}[H.profiles.current()]||'CADET';}

 function welcomeLines(){var lines={

  jay:[['I brought my serious training face.', 'Good. Did it bring its listening ears?'],['My listening ears are on duty. My snack stomach is requesting backup.','One mission at a time, Officer Snack Stomach.']],

  rosa:[['You are running the desk today? Very official, Papi.','I even found a pen that works. We are unstoppable.'],['If I finish the course, do you handle the dishes?','That is a very advanced negotiation technique.']],

  kaleb:[['I have a plan: be fast, look cool, and do not bump into a crate.','Excellent. Start with looking carefully. The crates are undefeated.'],['Can I earn a cool codename?','How about Captain Checks-Before-He-Shoots? Long name. Excellent habit.']],

  gigi:[['Can my badge have sparkles?','Of course. The sparkles still have to follow the rules.'],['I am ready! My bravery is this big!','Wonderful. Bring a little patience with that giant bravery.']],

  lingling:[['If I get lost, I am calling it a secret mission.','Fair. Your secret mission is to ask for directions.'],['I am going to be sneaky like a ninja kitten.','A ninja kitten who checks every target. Perfect.']]

 };var pair=lines[H.profiles.current()]||lines.kaleb,v=pair[progress().runs%pair.length];return [[coach(),'Welcome, '+trainee()+'! Ready for a little practice?'],[trainee(),v[0]],[coach(),v[1]],[coach(),'Orange bullseyes are practice targets. Blue hands mean HOLD FIRE: keep them OUT of the narrow center of your light. The wide part lets you look safely.'],[coach(),'Move with the left stick. Swipe left or right in the clear right half of the screen to turn. Center a target and your practice tool fires four quick shots: bap, bap, bap, bap! Keep your aim steady. Thirty-two rounds give you eight bursts. RELOAD uses your reserve rounds. Walk onto marked AMMO, ARMOR or HEALTH packs to collect them when needed. Blue-hand mistakes dent your practice armor by 15; nobody gets hurt.'],[trainee(),'Look first, think first. Got it!'],[coach(),'Find 24 targets, or tap FINISH RUN whenever you want your results. This is practice. We learn, we laugh, and we try again. Your case clues stay safe.']];}

 function atDesk(){return active()&&Math.hypot(player.x+13-160,player.y+13-2580)<90;}

 function progress(){return state.training||(state.training=trainingSave());}

