 function stopFire(){held=false;lockId=null;lockTime=0;fireDelay=.12;burstLeft=0;burstWait=0;burstTarget=null;}

 function cancelReload(){reloadTotal=0;stopWeaponReload();if(run)run.reload=0;}

 function closeOptions(){ui.classList.remove('options-open');document.getElementById('trainingOptions').setAttribute('aria-expanded','false');}

 function reset(){if(H.armory)H.armory.reset();weapon=H.weapons.profiles.rifle;MAGAZINE_SIZE=32;nextShot=0;H.atmosphere.stop();H.cover.reset('training');closeOptions();H.tacticalView.set('training',false);cancelReload();owner=null;run=null;supplyEffects=[];mini=false;lightMask=null;maskState=null;aimCone.reset();H.academyLighting.reset();visionKey='';visionAge=1;beam=[];near=[];stopFire();cancelAim();ui.style.display='none';document.body.classList.remove('training-mode');}

 function attachment(dt,a){var p=point();var pose=H.cover.sample('training',m,p.x,p.y,Number.isFinite(a)?a:run.angle,dt||0,weapon.reach||43);pose.halfAngle=Math.max(pose.halfAngle,weapon.halfAngle+.08);return pose;}

 function point(){return{x:player.x+13,y:player.y+13};}

 function combatCourse(){return H.academy&&H.academy.combat();}

 function sync(){if(owner&&owner!==state)reset();if(!active()){if(owner)reset();return false;}if(!owner){owner=state;run=progress().session?academyRunSave(progress().session):resources({stage:'ready',angle:-Math.PI/2,shots:0,roundHits:0,hits:0,holds:0,ammo:MAGAZINE_SIZE,reload:0,time:0,hit:{},shot:null});}ui.style.display='block';document.body.classList.add('training-mode');H.tacticalView.set('training',run.stage!=='ready'&&(combatCourse()||player.y<2376));if(blocked()){H.atmosphere.stop();cancelReload();cancelAim();stopFire();}var text=run.stage==='ready'?'ACADEMY • Walk to the check-in desk and talk to the instructor for Training, Zombie Outbreak or Tactical Arena.':run.stage==='done'?'Run saved • '+run.hits+'/24 targets • '+accuracy()+'% accuracy • Best full run: '+progress().best:'AUTO FIRE • '+run.hits+'/24 targets • '+accuracy()+'% accuracy • '+(run.reload>0?'Reloading…':run.ammo+'/'+MAGAZINE_SIZE+' shots')+' • Blue hits: '+run.holds;var talk=document.getElementById('trainingStart');talk.textContent='TALK TO '+coach();talk.style.display=H.academy&&H.academy.active()?'':atDesk()?'':'none';if(H.academy&&H.academy.active())talk.textContent='RETRY SESSION';talk.disabled=blocked();if(run.stage==='running'&&player.y<2376)text=run.hits+'/24 targets · '+(run.reload>0?'Reloading…':run.ammo+'/'+MAGAZINE_SIZE+' · Reserve '+run.reserve)+' · Blue hits '+run.holds;if(H.academy&&H.academy.active())text=H.academy.label(run);if(status.textContent!==text)status.textContent=text;return true;}

 function targetList(){return H.academy&&H.academy.combat()?H.academy.targets():m.trainingTargets;}

 function accuracy(){return run.shots?Math.round(run.roundHits/run.shots*100):100;}

 function guard(s,r){return state===s&&owner===s&&run===r&&active();}

 function start(){if(!sync()||blocked())return false;ensureAudio();warmWeaponAudio();var s=state,r=run;cancelReload();stopFire();clearHeldInputs();cancelAim();showLines(welcomeLines(),function(){if(!guard(s,r))return;run=resources({stage:'running',angle:-Math.PI/2,shots:0,roundHits:0,hits:0,holds:0,ammo:MAGAZINE_SIZE,reload:0,time:0,hit:{},shot:null});supplyEffects=[];player.x=147;player.y=2260;player.dir='up';save();sync();});return true;}

 function finish(){if(H.academy&&H.academy.active())return H.academy.finish(run&&run.hits===24?'victory':'ended');if(!sync()||blocked()||run.stage!=='running')return false;var score=Math.max(0,run.hits*10-(run.shots-run.roundHits)-run.holds*15),p=progress();p.runs=Math.min(100000,p.runs+1);p.last={hits:run.hits,shots:run.shots,holds:run.holds,score:score};if(run.hits===24)p.best=Math.max(p.best,score);run.stage='done';cancelReload();clearHeldInputs();stopFire();cancelAim();save();showLines([[coach(),'You found '+run.hits+' of 24 targets. Accuracy: '+accuracy()+'%. Blue-hand hits: '+run.holds+'. Practice score: '+score+'.'],[trainee(),run.holds?'Oops. My aiming got ahead of my thinking brain.':'I checked the blue hands. Very polite targets.'],[coach(),run.holds?'Then let your thinking brain drive next time! Keep blue hands away from the center. You can do this.':'Excellent manners. They send you a very quiet high-five.'],[trainee(),{jay:'Does that high-five come with a snack?',rosa:'I am still counting this as my turn off dish duty.',kaleb:'Captain Checks-Before-He-Shoots reporting back!',gigi:'Careful AND sparkly. That is my style.',lingling:'Ninja kitten mission complete. Time for a tiny victory dance.'}[H.profiles.current()]||'Ready to keep learning!'],[coach(),'Talk to me at the check-in desk to practice again, or leave through EXIT CENTER. Your story progress is unchanged.']],null);sync();return true;}

 function equipWeapon(id){var w=H.weapons.loadouts[id];if(!w||!run||!H.armory||!H.armory.preparing())return false;cancelReload();stopFire();weapon=w;MAGAZINE_SIZE=w.magazine;run.weaponId=id;run.ammo=w.magazine;run.reserve=w.reserve;nextShot=run.time;H.cover.reset('training');aimCone.reset();visionKey='';return true;}

