 function paint(){if(!sync())return;ctx.save();ctx.scale(effZoom(),effZoom());ctx.translate(-cam.x,-cam.y);m.walls.forEach(function(w){if(!inView(w))return;ctx.fillStyle='#080e17';ctx.fillRect(w.x,w.y,w.w,w.h);if(H.academy&&H.academy.combat())H.academyScene.wall(ctx,w);ctx.strokeStyle='#26333c';ctx.lineWidth=1;ctx.strokeRect(w.x+.5,w.y+.5,w.w-1,w.h-1);});for(var list=targetList(),i=0;i<list.length;i++){var t=list[i];if(!inView({x:t.x-25,y:t.y-25,w:50,h:50})||!visible(t))continue;if(t.kind==='opponent')continue;ctx.save();ctx.translate(t.x,t.y);ctx.globalAlpha=run.hit[t.id]?.35:1;ctx.fillStyle=t.kind==='target'?'#d99350':'#5ba1be';ctx.beginPath();ctx.arc(0,0,24,0,7);ctx.fill();ctx.strokeStyle='#f4e0ad';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,15,0,7);ctx.stroke();if(t.kind==='target'){ctx.fillStyle='#5b3930';ctx.beginPath();ctx.arc(0,0,7,0,7);ctx.fill();}else{ctx.fillStyle='#e8f0da';ctx.fillRect(-8,-5,16,15);for(var f=0;f<4;f++)ctx.fillRect(-8+f*5,-16,4,15);}ctx.restore();}if(H.academy&&H.academy.active())H.academy.paintWorld();var pose=attachment(),p=pose.muzzle,d=H.tactical.ray(p.x,p.y,run.angle,weapon.range,m.solids);var aimD=Math.min(160,Math.max(0,d-2)),ax=p.x+Math.cos(run.angle)*aimD,ay=p.y+Math.sin(run.angle)*aimD;ctx.strokeStyle=centerTarget()?'rgba(255,197,128,.95)':'rgba(215,239,232,.72)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(ax-7,ay);ctx.lineTo(ax-3,ay);ctx.moveTo(ax+3,ay);ctx.lineTo(ax+7,ay);ctx.moveTo(ax,ay-7);ctx.lineTo(ax,ay-3);ctx.moveTo(ax,ay+3);ctx.lineTo(ax,ay+7);ctx.stroke();if(run.shot&&run.shot.until>Date.now()){var s=run.shot;ctx.strokeStyle='#ffe2a0';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.ex,s.ey);if(s.rays)for(var ri=1;ri<s.rays.length;ri++){ctx.moveTo(s.x,s.y);ctx.lineTo(s.rays[ri].ex,s.rays[ri].ey);}ctx.stroke();ctx.fillStyle='#ffe6ad';ctx.beginPath();ctx.arc(s.x,s.y,6,0,7);ctx.fill();ctx.fillRect(s.ex-3,s.ey-3,6,6);ctx.strokeStyle='#ffe6ad';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(s.ex-7,s.ey-7);ctx.lineTo(s.ex+7,s.ey+7);ctx.moveTo(s.ex+7,s.ey-7);ctx.lineTo(s.ex-7,s.ey+7);ctx.stroke();}ctx.restore();darkness();fireBand();litEdges();fixtures();deskPaint();ctx.save();ctx.scale(effZoom(),effZoom());ctx.translate(-cam.x,-cam.y);paintSupplies();ctx.restore();paintOpponents();playerSilhouette();paintResources();if(!H.tacticalCamera||!H.tacticalCamera.rendering())paintPlan();}

 function paintOpponents(){if(!H.academy||!H.academy.combat())return;ctx.save();ctx.scale(effZoom(),effZoom());ctx.translate(-cam.x,-cam.y);targetList().forEach(function(e){if(inView({x:e.x-30,y:e.y-30,w:60,h:60})&&visible(e))H.academy.paintActor(e);});H.academy.paintEffects();ctx.restore();}

