 function paintSupplies(){supplies.forEach(function(t){if(run.collected[t.id]||!inView({x:t.x-24,y:t.y-24,w:48,h:48})||!visible(t))return;var def=H.supplies.definitions[t.kind];upright(t.x,t.y,function(){ctx.fillStyle='#101e2b';ctx.fillRect(-19,-19,38,38);ctx.fillStyle=def.color;ctx.fillRect(-16,-16,32,32);ctx.strokeStyle='#eee0b8';ctx.lineWidth=1;ctx.strokeRect(-18,-18,36,36);ctx.fillStyle='#172c39';ctx.font='bold 22px sans-serif';ctx.textAlign='center';ctx.fillText(def.symbol,0,7);ctx.fillStyle='#f4ebcf';ctx.font='bold 9px sans-serif';if(!H.academy||!H.academy.combat()||H.academy.annotationClear(t.x,t.y))ctx.fillText(def.label,0,30);});});}

 function paintResources(){if(run.stage==='ready')return;var p=point(),rotation=H.tacticalCamera&&H.tacticalCamera.rendering()?H.tacticalCamera.rotation():0;

 ctx.save();ctx.scale(effZoom(),effZoom());ctx.translate(-cam.x,-cam.y);upright(p.x,p.y,function(){if(H.academy&&H.academy.active())H.academy.paintFeedback(ctx);if(run.reload>0){ctx.strokeStyle='#8fc7d7';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,29,-Math.PI/2,-Math.PI/2+Math.PI*2*(1-run.reload/(reloadTotal||reloadSoundDuration())));ctx.stroke();ctx.fillStyle='#d3eaf0';ctx.font='bold 9px sans-serif';ctx.textAlign='center';ctx.fillText('RELOADING',0,-39);}ctx.fillStyle='rgba(8,18,28,.85)';ctx.fillRect(-27,29,54,13);ctx.fillStyle='#87d5a1';ctx.fillRect(-25,31,50*run.health/100,4);ctx.fillStyle='#78bce0';ctx.fillRect(-25,37,50*run.armor/100,3);ctx.fillStyle='#f4eddb';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText('HP '+run.health+'  AR '+run.armor,0,50);

 supplyEffects=supplyEffects.filter(function(e){return e.until>supplyClock;});supplyEffects.forEach(function(e,i){ctx.globalAlpha=Math.min(1,(e.until-supplyClock)*2);ctx.fillStyle=e.color;ctx.font='bold 12px sans-serif';ctx.fillText(e.text,0,-40-i*16-(1.4-e.until+supplyClock)*12);});ctx.globalAlpha=1;});ctx.restore();}

 function paintPlan(){var p=point();if(mini){ctx.save();var w=Math.min(230,VW*.42),sc=w/m.w,x=VW-w-12,y=130;ctx.fillStyle='rgba(8,23,35,.94)';ctx.fillRect(x-5,y-5,w+10,m.h*sc+10);ctx.translate(x,y);ctx.scale(sc,sc);ctx.fillStyle='#acb8a4';m.walls.forEach(function(b){ctx.fillRect(b.x,b.y,b.w,b.h);});if(H.outbreak&&H.outbreak.active())H.outbreak.paintPlan(ctx);ctx.fillStyle='#f2ce6c';ctx.beginPath();ctx.arc(p.x,p.y,40,0,7);ctx.fill();ctx.restore();}}

