 H.training={trigger:trigger,equipWeapon:equipWeapon,beginSession:function(x,y){reset();owner=state;run=resources({stage:'running',angle:-Math.PI/2,shots:0,roundHits:0,hits:0,holds:0,ammo:MAGAZINE_SIZE,reload:0,time:0,hit:{},shot:null});player.x=x-13;player.y=y-13;if(H.locomotion){player.locomotion=H.locomotion.seed(x,y);player.locomotion.map='training';}clearHeldInputs();sync();return run;},reindexSupplies:function(){nearbySupplies=H.supplies.index(supplies);},resources:function(){return run;},invalidateVision:function(){visionKey='';visionAge=1;aimCone.reset();},get weapon(){return weapon;},aimStats:function(){return aimCone.stats();},get magazineSize(){return MAGAZINE_SIZE;},supplies:supplies,attachment:attachment,paintPlan:paintPlan,centerTarget:centerTarget,coach:coach,checkIn:{x:160,y:2580},cameraLead:cameraLead,visible:visible,lightStats:function(){return{visionBuilds:visionBuilds,rays:rayCount,maskBuilds:maskBuilds,maskHits:maskHits,maskBytes:lightMask?lightMask.width*lightMask.height*4:0};},map:m,building:building,entry:entry,start:start,fire:fire,aim:aim,reload:reload,finish:finish,exit:exit,update:update,reset:reset,progress:progress,status:function(){return run?{weaponId:run.weaponId||null,magazine:MAGAZINE_SIZE,nextFire:nextShot,stage:run.stage,angle:run.angle,hits:run.hits,holds:run.holds,shots:run.shots,ammo:run.ammo,reserve:run.reserve,health:run.health,armor:run.armor,collected:Object.assign({},run.collected),reload:run.reload,shot:run.shot&&Object.assign({},run.shot),burstLeft:burstLeft,hit:Object.assign({},run.hit)}:null;}};

