  poly(g,[-12,-8,-6,-11,7,-10,11,-4,8,8,-9,9],p.seam);

  poly(g,[-10,-5,-3,-8,8,-5,11,4,6,11,-10,11],p.cloth);

  line(g,[-8,-2,-5,4,-7,11], '#263940',1.1);line(g,[4,-3,7,3,5,8],p.seam,1);

  poly(g,[-10,11,-5,8,-1,11,-4,14],p.skin);poly(g,[8,8,13,5,13,11,9,13],p.shade);

  box(g,0,0,3,5,'#a0a894');line(g,[1,-1,2,7], '#2c4148',.7);

  // Reaching arms: ragged sleeves -> thin green forearms -> spread fingers.

  poly(g,[-17,-9,-12,-7,-15,1,-21,-1,-24,-10,-21,-15],p.cloth,'#17262c',1.2);

  poly(g,[-22,-12,-17,-13,-14,-23-reach,-18,-27-reach,-23,-20],p.skin,'#425842',1);

  line(g,[-22,-17,-20,-22-reach],p.shade,1.3);

  poly(g,[-18,-23-reach,-13,-25-reach,-11,-29-reach,-13,-31-reach,-16,-28-reach,-17,-33-reach,-19,-33-reach,-20,-28-reach,-22,-31-reach,-24,-30-reach,-22,-24-reach],p.skin,'#3c5346',.8);

  poly(g,[12,-10,18,-8,23,-15,20,-20,16,-17],p.cloth,'#17262c',1.2);

  poly(g,[20,-18,24,-17,25,-26+reach,21,-29+reach,18,-25+reach],p.skin,'#425842',1);

  poly(g,[21,-26+reach,18,-30+reach,20,-32+reach,22,-30+reach,24,-34+reach,26,-33+reach,26,-29+reach,28,-31+reach,30,-29+reach,28,-25+reach,24,-23+reach],p.skin,'#3c5346',.8);

  // Crown dominates the face: this remains a true overhead character, not a portrait.

  g.save();g.translate(s*.5,breath-2);

  oval(g,-1,-10,11,12,p.shade,'#23372f',1.5);

  poly(g,[-10,-14,-6,-22,3,-23,9,-17,10,-10,6,-3,-4,-2,-10,-8],p.skin,'#3b5140',1);

  poly(g,[-8,-16,-4,-21,2,-20,5,-17,1,-14], '#cad1a3');

  // Sparse hair, scalp seam, sunken brow and tiny contrasting amber eyes.

  poly(g,[-10,-14,-8,-20,-4,-23,0,-24,3,-22,0,-20,-5,-19,-6,-14], '#3c4940');

  line(g,[4,-19,6,-15,4,-12],p.shade,1);line(g,[3,-17,6,-16,3,-14], '#6e7857',.7);

  oval(g,-4,-18,3.5,2.4,'#425443');oval(g,5,-18,3,2.5,'#425443');

  box(g,-5.5,-19,2.5,1.6,'#f1d87c');box(g,4,-19,2.2,1.6,'#f1d87c');

  poly(g,[-2,-21,1,-22,3,-20,0,-19],p.shade);

