  g.restore();

  if(type==='brute'){poly(g,[-23,-11,-14,-17,-10,-9,-14,4,-25,0],'#626e72','#142732',2);poly(g,[14,-16,24,-10,25,1,15,6,11,-6],'#626e72','#142732',2);box(g,-12,1,24,11,'#4a5355');line(g,[-10,3,10,3],'#a8b3a0',2);}

