  if(type==='screamer'){poly(g,[-11,-12,-7,-7,6,-7,13,-14,10,-3,-1,1,-11,-4],'#9aab83','#3b5140',1);oval(g,0,-8,6,5,'#27313d');line(g,[-26,-23,-31,-34],'#a3b28c',4);line(g,[25,-23,31,-34],'#a3b28c',4);}

