 function paint(g,e,kind,time){g.save();g.translate(e.x,e.y);g.rotate(e.angle+Math.PI/2);if(e.flash>0)g.translate(0,Math.sin((.2-e.flash)/.2*Math.PI)*2);g.lineJoin='round';g.lineCap='round';if(kind==='zombie')zombieActor(g,e,time||0);else swatActor(g,e,time||0);g.restore();}

