  poly(g,[-11,7,-3,7,-3,29,-10,31,-13,27],z?'#3c4a49':'#203248','#10202c',1.4);poly(g,[3,7,11,7,14,26,10,30,4,29],z?'#465451':'#263b52','#10202c',1.4);

  box(g,-12,28,9,5,'#142330');box(g,5,27,10,6,'#142330');

  poly(g,[-14,-12,10,-13,14,9,8,17,-9,16,-15,7],cloth,'#132431',1.7);box(g,-9,-5,18,17,z?p.seam:'#324b61');

  line(g,[-14,-7,-20,0,-16,15],'#11222d',7);line(g,[-14,-7,-20,0,-16,15],cloth,5);line(g,[13,-8,19,0,16,13],'#11222d',7);line(g,[13,-8,19,0,16,13],cloth,5);oval(g,-16,15,3,4,skin);oval(g,16,13,3,4,skin);

