  // Fixtures reuse occluded, cached masks. Positions match bulkheads, doors and workstations.

  zones.forEach(r=>{lights.push({x:r.x+80,y:r.y+32,emergency:false},{x:r.x+r.w-80,y:r.y+r.h-32,emergency:true});});

  for(const [x,y] of[[1350,650],[3170,650],[2070,1600],[3650,1560],[2660,2050],[3620,2540],[2640,2930]])lights.push({x,y,emergency:false});

  for(const [x,y] of[[1780,900],[2500,900],[3500,800],[3500,2240],[1050,2470],[1950,2470],[3750,3000]])lights.push({x,y,emergency:false});

