  for(const [x,y] of[[480,1020],[1030,1040],[600,340],[1100,690],[3400,540],[3940,550],[3400,1330],[4000,1380],[3100,2280],[3910,2280],[550,2440],[1200,2480],[1920,2480],[1200,3090],[2200,3120],[3020,2990],[4020,3040]])lights.push({x,y,emergency:false});

