 [['brooks','SGT. BROOKS','sergeant'],['rivera','RIVERA','rivera'],['torres','OFFICER TORRES','caperTorres'],['maya','MAYA','caperMaya']].forEach(function(a){var p=points[a[0]],q=nearby(p.x,p.y-22);m.npcs.push({x:q.x,y:q.y,name:a[1],talk:a[2],hat:a[0]!=='maya',color:'#365369',hideName:true,caper:true});});

