updatePeds=function(dt){updateBefore(dt);if(!active()||state.map!=='station'||dlgOpen||overlayOpen())return;taskClock+=Math.min(.1,dt||0);m.npcs.forEach(function(n){if(!n.familyId||n.familyId==='jay')return;var index=ids.indexOf(n.familyId),seat=familySeats[n.familyId],phase=(taskClock+index*2)%12,goal=seat[0]+(phase<6?0:24),dx=goal-n.x,nx=n.x+Math.sign(dx)*Math.min(Math.abs(dx),28*Math.min(.1,dt||0));n.walking=Math.abs(dx)>1;if(n.walking&&free(nx,n.y)){n.x=nx;n.dir=dx>0?'right':'left';n.walkPhase=(n.walkPhase||0)+dt*4;}else n.dir='down';var spot=m.spots.find(function(s){return s.id==='caper:family:'+n.familyId;});if(spot){spot.x=n.x;spot.y=n.y+20;}});};

