/* User-provided main-adventure theme. One streamed media element; no Academy audio edits. */

(function(){

 'use strict';

 var H=window.HARBOR,key='rookie:campaign-music:v1',enabled=true,unlocked=false,blurred=false,pending=false,needsGesture=false,failed=false,serial=0,loaded=false;

 try{enabled=localStorage.getItem(key)!=='off';}catch(e){}

 var track=document.createElement('audio');track.id='campaignMusicAudio';track.preload='none';track.loop=true;track.volume=0;track.setAttribute('aria-hidden','true');track.style.display='none';document.body.appendChild(track);

 var label=document.createElement('label');label.style.cssText='display:flex;align-items:center;gap:10px;min-height:44px';

 var toggle=document.createElement('input');toggle.type='checkbox';toggle.id='campaignMusicToggle';toggle.checked=enabled;toggle.setAttribute('aria-label','Background music');label.appendChild(toggle);label.appendChild(document.createTextNode('Background music'));

 var status=document.createElement('small');status.id='campaignMusicStatus';status.style.display='block';status.setAttribute('aria-live','polite');var host=document.querySelector('#avPanel .body');host.appendChild(label);host.appendChild(status);

 var lastText='';function notice(t){if(t!==lastText){status.textContent=t;lastText=t;}}

 function academy(){return state.map==='training'||H.academy&&H.academy.active();}

 function allowed(){return enabled&&unlocked&&!blurred&&!document.hidden&&!academy()&&!musicMode&&!H.profiles.isOpen()&&avMusicGain()>0;}

 function pause(){serial++;if(typeof track.pause==='function'&&track.paused!==true)track.pause();}

 function start(){

  if(pending||needsGesture||failed||!allowed()||track.paused===false||typeof track.play!=='function')return;

  if(!loaded){track.src='assets/audio/campaign/main-theme.mp3';loaded=true;}

  pending=true;var epoch=serial;

  try{var promise=track.play();if(promise&&typeof promise.then==='function')promise.then(function(){pending=false;if(!allowed())pause();else notice('Playing · The volume follows Music above.');},function(){pending=false;if(epoch===serial&&allowed()){needsGesture=true;notice('Tap the game to start the music.');}});else pending=false;}

  catch(e){pending=false;needsGesture=true;notice('Tap the game to start the music.');}

 }

 function sync(){

  var volume=Math.max(0,Math.min(1,avMusicGain()*.30*(dlgOpen?.55:1)));

  if(track.volume!==volume)track.volume=volume;

  if(!allowed()){pause();notice(!enabled?'Background music off.':academy()?'Paused during Academy practice.':musicMode?'Paused for scene music.':avMusicGain()===0?'Music muted.':!unlocked?'Starts after you tap the game.':'Paused.');return;}

  if(failed){notice('Music could not load. Refresh to retry.');return;}start();if(track.paused===false)notice('Playing · The volume follows Music above.');

 }

 function gesture(e){if(e&&e.repeat)return;unlocked=true;needsGesture=false;sync();}

 toggle.addEventListener('change',function(){enabled=toggle.checked;try{localStorage.setItem(key,enabled?'on':'off');}catch(e){}sync();});

 track.addEventListener('error',function(){failed=true;pause();notice('Music could not load. Refresh to retry.');});

 document.addEventListener('pointerdown',gesture);document.addEventListener('keydown',gesture);document.addEventListener('click',sync);document.addEventListener('input',sync);

 document.addEventListener('visibilitychange',sync);window.addEventListener('pagehide',pause);window.addEventListener('blur',function(){blurred=true;pause();});window.addEventListener('focus',function(){blurred=false;sync();});

 var render=draw;draw=function(){var result=render.apply(this,arguments);sync();return result;};

 var location=updateLocLabel;updateLocLabel=function(){var result=location.apply(this,arguments);sync();return result;};

 var sceneStart=musicStart,sceneStop=musicStop;musicStart=function(){var result=sceneStart.apply(this,arguments);sync();return result;};musicStop=function(){var result=sceneStop.apply(this,arguments);sync();return result;};

 H.campaignMusic={sync:sync,status:function(){return{enabled:enabled,unlocked:unlocked,loaded:loaded,pending:pending,needsGesture:needsGesture,failed:failed,playing:track.paused===false,loop:track.loop,volume:track.volume,suspendedForAcademy:!!academy()};}};

 sync();

})();



