 var courseLabel=document.createElement('label');courseLabel.style.cssText=label.style.cssText;var courseToggle=document.createElement('input');courseToggle.type='checkbox';courseToggle.id='outbreakCourseMusicToggle';courseToggle.checked=enabled;courseToggle.setAttribute('aria-label','Outbreak background music');courseLabel.appendChild(courseToggle);courseLabel.appendChild(document.createTextNode('Loop background music'));document.getElementById('outbreakAudioSettings').appendChild(courseLabel);

