 function gesture(e){if(e&&e.repeat)return;unlocked=true;needsGesture=false;sync();}

 function setEnabled(value){enabled=value;toggle.checked=courseToggle.checked=enabled;try{localStorage.setItem(key,enabled?'on':'off');}catch(e){}sync();}

